package com.mindarray.agent;

import com.mindarray.BootstrapAgent;
import com.mindarray.GlobalConstants;
import com.mindarray.api.Agent;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.AgentConfigUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.PortUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;
import org.apache.commons.io.FileUtils;
import org.xerial.snappy.Snappy;

import java.io.File;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

import static com.mindarray.GlobalConstants.VALUE_SEPARATOR_WITH_ESCAPE;
import static com.mindarray.agent.AgentConstants.AGENT_TYPE;

public class AgentCacheManager extends AbstractVerticle
{
    public static final File CACHE_FOLDER = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "cache");
    private static final Logger LOGGER = new Logger(AgentCacheManager.class, GlobalConstants.MOTADATA_AGENT, "Agent Cache Manager");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var qualifications = 100; //ToDo: need to decide the number as per backpressure...

        vertx.setPeriodic(AgentConfigUtil.getAgentCacheFlushTimerSeconds(), handler ->
        {
            try
            {
                var events = 0;

                var files = CACHE_FOLDER.listFiles();

                if (files != null && files.length > 0)
                {
                    if (PortUtil.isConnected(CommonUtil.getRemoteEventPublisher(), CommonUtil.getEventSubscriberPort(), 3))
                    {
                        LOGGER.debug("motadata server is up...");

                        var cacheFiles = new HashMap<String, Map<String, Long>>();

                        AgentConstants.agents.forEach(agent -> cacheFiles.put(agent, new HashMap<>()));

                        Arrays.stream(files).filter(item -> item.getAbsoluteFile().getName().split("-").length == 4).collect(Collectors.groupingBy(item -> item.getAbsoluteFile().getName().split("-")[0],
                                        Collectors.groupingBy(File::getAbsolutePath,
                                                Collectors.mapping(item -> CommonUtil.getLong(item.getAbsoluteFile().getName().split("-")[2].replace(".cache",GlobalConstants.EMPTY_VALUE)), Collectors.toList()))))
                                .forEach((key, items) -> items.entrySet().stream().filter(item -> !cacheFiles.get(key).containsKey(item.getKey())).forEach(entry -> cacheFiles.get(key).put(entry.getKey(), entry.getValue().get(0))));

                        for (var agent : AgentConstants.agents)
                        {
                            cacheFiles.get(agent).entrySet().stream().sorted(Map.Entry.comparingByValue()).forEach(item ->
                            {
                                var cacheFile = item.getKey();

                                if (vertx.fileSystem().existsBlocking(cacheFile))
                                {
                                    try
                                    {
                                        var values = new String(Snappy.uncompress(vertx.fileSystem().readFileBlocking(cacheFile).getBytes())).split(VALUE_SEPARATOR_WITH_ESCAPE);

                                        for (var value : values)
                                        {
                                            vertx.eventBus().send(EventBusConstants.EVENT_AGENT, new JsonObject()
                                                    .put(EventBusConstants.EVENT_TYPE, EventBusConstants.EVENT_AGENT_RESPONSE_STREAM)
                                                    .put(Agent.AGENT_UUID, BootstrapAgent.getAgentUUID()).put(EventBusConstants.EVENT_COPY_REQUIRED, false)
                                                    .put(AGENT_TYPE, agent).put(EventBusConstants.EVENT_CONTEXT, Snappy.compress(value)));
                                        }

                                        vertx.fileSystem().deleteBlocking(cacheFile);

                                        LOGGER.debug(String.format("cache file %s is deleted", cacheFile));
                                    }
                                    catch (Exception exception)
                                    {
                                        LOGGER.error(exception);
                                    }
                                }
                            });
                        }
                    }
                    else
                    {
                        LOGGER.warn("motadata server is not reachable...");

                        if (FileUtils.sizeOfDirectory(CACHE_FOLDER) > AgentConfigUtil.getAgentCacheFileMaxSizeBytes())
                        {
                            var cacheFiles = new HashMap<String, Map<String, Long>>();

                            AgentConstants.agents.forEach(agent -> cacheFiles.put(agent, new HashMap<>()));

                            LOGGER.info(String.format("%s size is greater than %s bytes", CACHE_FOLDER.getAbsolutePath(), AgentConfigUtil.getAgentCacheFileMaxSizeBytes()));

                            Arrays.stream(files).filter(item -> item.getAbsoluteFile().getName().split("-").length == 3).collect(Collectors.groupingBy(item -> item.getAbsoluteFile().getName().split("-")[0],
                                            Collectors.groupingBy(File::getAbsolutePath,
                                                    Collectors.mapping(item -> CommonUtil.getLong(item.getAbsoluteFile().getName().split("-")[2].replace(".cache", GlobalConstants.EMPTY_VALUE)), Collectors.toList()))))
                                    .forEach((key, items) -> items.entrySet().stream().filter(item -> !cacheFiles.get(key).containsKey(item.getKey())).forEach(entry -> cacheFiles.get(key).put(entry.getKey(), entry.getValue().get(0))));

                            var finished = false;

                            while (!finished)
                            {
                                for (var agent : AgentConstants.agents)
                                {
                                    if (!cacheFiles.get(agent).isEmpty())
                                    {
                                        var file = cacheFiles.get(agent).entrySet().stream().sorted(Map.Entry.comparingByValue()).toList().get(0).getKey();

                                        if (file != null)
                                        {
                                            vertx.fileSystem().deleteBlocking(file);

                                            cacheFiles.get(agent).remove(file);

                                            LOGGER.info(String.format("cache file %s is deleted....", file));

                                            if (FileUtils.sizeOfDirectory(CACHE_FOLDER) < AgentConfigUtil.getAgentCacheFileMaxSizeBytes())
                                            {
                                                finished = true;

                                                break;
                                            }
                                        }
                                    }
                                }

                                if (!finished)
                                {
                                    finished = AgentConstants.agents.stream().map(item -> cacheFiles.get(item).size()).reduce(0, Integer::sum) == 0;
                                }
                            }
                        }
                    }
                }
            }

            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        promise.complete();
    }
}

