/**
 * Integration class for Slack notification system.
 * <p>
 * This class provides functionality to:
 * - Synchronize channels information from Slack
 * - Handle authentication with Slack using OAuth tokens
 * - Provide endpoints for sending notifications to Slack channels
 * - Support both automatic and manual synchronization of Slack data
 * <p>
 * Unlike other integration classes that focus on ticket management,
 * this integration is primarily used for sending notifications to Slack channels.
 * It uses Slack Web API to communicate with Slack.
 */
public class SlackIntegration extends AbstractVerticle
{
    public static final String SLACK = "Slack";
    public static final String CHANNELS = "channels";
    public static final String CHANNEL = "channel";
    public static final String MESSAGE_END_POINT = "chat.postMessage";
    private static final Logger LOGGER = new Logger(SlackIntegration.class, INTEGRATION_DIR, "Slack Integration");
    private final AtomicBoolean SYNC_FLAG = new AtomicBoolean();
    private Long timerId;
    private JsonObject integration;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            init();

            vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
            {
                if (ChangeNotificationType.valueOf(message.body().getString(CHANGE_NOTIFICATION_TYPE)) == ChangeNotificationType.UPDATE_INTEGRATION)
                {
                    try
                    {
                        var event = message.body();

                        if (event.containsKey(ID) && event.getValue(ID) != null
                             && event.getLong(ID).equals(IntegrationConstants.IntegrationId.SLACK.getName()))
                        {
                            init();
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }
            });

            // manual sync integration attributes
            vertx.eventBus().<JsonObject>localConsumer(IntegrationConstants.IntegrationType.SLACK.getName() + DOT_SEPARATOR + EVENT_INTEGRATION_SYNC, message ->
            {
                try
                {
                    var event = message.body();

                    if (event.containsKey(ID) && event.getValue(ID) != null
                         && event.getLong(ID).equals(IntegrationConstants.IntegrationId.SLACK.getName()))
                    {
                        sync().onComplete(reply ->
                        {
                            if (reply.succeeded())
                            {
                                message.reply(reply.result());
                            }
                            else
                            {
                                LOGGER.warn(reply.cause());

                                message.fail(HttpStatus.SC_BAD_REQUEST, reply.cause().getMessage());
                            }
                        });
                    }
                    else
                    {
                        message.fail(HttpStatus.SC_BAD_REQUEST, "Invalid integration ID");
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);

                    message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, exception.getMessage());
                }
            });

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
    }

    /**
     * Initializes the Slack integration.
     * <p>
     * This method:
     * 1. Loads the Slack integration configuration from the store
     * 2. Sets up periodic synchronization if auto-sync is enabled:
     * - Cancels any existing sync timer
     * - Creates a new timer with the configured interval
     * 3. Disables periodic synchronization if auto-sync is disabled
     * <p>
     * The synchronization process keeps channels information up-to-date
     * for sending notifications to the correct destinations.
     */
    private void init()
    {
        try
        {
            integration = IntegrationConfigStore.getStore().getItem(IntegrationConstants.IntegrationId.SLACK.getName());

            if (integration != null && integration.containsKey(Integration.INTEGRATION_CONTEXT))
            {
                var context = integration.getJsonObject(INTEGRATION_CONTEXT);

                if (context.containsKey(Integration.AUTO_SYNC)
                     && context.getString(Integration.AUTO_SYNC).equalsIgnoreCase(YES)
                     && context.containsKey(Integration.SYNC_INTERVAL))
                {
                    if (timerId != null)
                    {
                        vertx.cancelTimer(timerId);
                    }

                    timerId = vertx.setPeriodic(TimeUnit.HOURS.toMillis(context.getInteger(SYNC_INTERVAL, 8)), timer -> sync());
                }
                else if (context.containsKey(AUTO_SYNC) && context.getString(AUTO_SYNC).equalsIgnoreCase(NO))
                {
                    if (timerId != null)
                    {
                        vertx.cancelTimer(timerId);
                    }
                }
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Synchronizes channels information from Slack.
     * <p>
     * This method:
     * 1. Ensures only one synchronization job runs at a time using the SYNC_FLAG
     * 2. Retrieves the integration configuration
     * 3. Initiates the actual synchronization by calling the overloaded sync method
     * 4. Updates the integration configuration in the database when synchronization completes
     * 5. Handles various error scenarios:
     * - Integration not configured
     * - Synchronization already running
     * - Exceptions during synchronization
     *
     * @return A Future that completes with the synchronization result or fails with an error message
     */
    private Future<JsonObject> sync()
    {
        var promise = Promise.<JsonObject>promise();
        try
        {
            if (!SYNC_FLAG.get())
            {
                SYNC_FLAG.set(true);

                var context = integration.getJsonObject(INTEGRATION_CONTEXT);

                sync(context.getString(TARGET, EMPTY_VALUE), context, integration.getJsonObject(INTEGRATION_ATTRIBUTES)).onComplete(result ->
                {
                    if (result.succeeded())
                    {
                        Bootstrap.configDBService().update(DBConstants.TBL_INTEGRATION,
                         new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, integration.getLong(ID)),
                         integration, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, asyncResult ->
                         {
                             SYNC_FLAG.set(false);

                             if (asyncResult.succeeded())
                             {
                                 IntegrationConfigStore.getStore().updateItem(integration.getLong(ID));

                                 promise.complete(result.result());
                             }
                             else
                             {
                                 LOGGER.error(asyncResult.cause());

                                 promise.fail(String.format(INTEGRATION_ATTRIBUTE_SYNC_FAILED, IntegrationConstants.IntegrationType.SLACK.getName(), asyncResult.cause()));
                             }
                         });
                    }
                    else
                    {
                        SYNC_FLAG.set(false);

                        promise.fail(result.cause());
                    }
                });
            }
            else
            {
                promise.fail("Sync already running");
            }
        }
        catch (Exception exception)
        {
            SYNC_FLAG.set(false);

            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    /**
     * Synchronizes Slack channels using the Slack Web API.
     * <p>
     * This method:
     * 1. Generates an OAuth access token for Slack Web API authentication
     * 2. Fetches channels via `conversations.list`
     * 3. Builds a structure of channels
     * 4. Updates the integration attributes with the synchronized information
     * <p>
     * The synchronized data is used when sending notifications to ensure
     * messages are sent to the correct channels.
     *
     * @param url        The base URL for Slack Web API calls
     * @param context    The integration context containing configuration parameters
     * @param attributes The integration attributes object to be updated
     * @return A Future that completes with the synchronization result or fails with an error message
     */
    private Future<JsonObject> sync(String url, JsonObject context, JsonObject attributes)
    {
        var promise = Promise.<JsonObject>promise();

        var entities = new JsonArray();

        if (context.containsKey(INTEGRATION_CREDENTIAL_PROFILE))
        {
            var credentialProfile = CredentialProfileConfigStore.getStore().getItem(context.getLong(INTEGRATION_CREDENTIAL_PROFILE));

            var token = credentialProfile.getJsonObject(CredentialProfile.CREDENTIAL_PROFILE_CONTEXT).getString(OAuthUtil.ACCESS_TOKEN);

            // First, get workspace information using auth.test
            WebClientUtil.getWebClient().getAbs(url + "auth.test")
                    .timeout(TimeUnit.SECONDS.toMillis(context.getLong(TIMEOUT, 60L)))
                    .bearerTokenAuthentication(token)
                    .send(authResponse ->
                    {
                        if (authResponse.succeeded())
                        {
                            var authHttpResponse = authResponse.result();

                            if (authHttpResponse.statusCode() == HttpStatus.SC_OK)
                            {
                                if (CommonUtil.validJSONResponse(authHttpResponse))
                                {
                                    var authResponseBody = authHttpResponse.bodyAsJsonObject();

                                    if (authResponseBody.getBoolean("ok", false))
                                    {
                                        // Now get channels list
                                        WebClientUtil.getWebClient().getAbs(url + "conversations.list")
                                                .timeout(TimeUnit.SECONDS.toMillis(context.getLong(TIMEOUT, 60L)))
                                                .bearerTokenAuthentication(token)
                                                .addQueryParam("types", "public_channel,private_channel")
                                                .addQueryParam("exclude_archived", "true")
                                                .send(asyncResponse ->
                                                {
                                                    if (asyncResponse.succeeded())
                                                    {
                                                        var httpResponse = asyncResponse.result();

                                                        if (httpResponse.statusCode() == HttpStatus.SC_OK)
                                                        {
                                                            if (CommonUtil.validJSONResponse(httpResponse))
                                                            {
                                                                var responseBody = httpResponse.bodyAsJsonObject();

                                                                if (responseBody.getBoolean("ok", false))
                                                                {
                                                                    var channels = responseBody.getJsonArray("channels");

                                                                    // Create team object with workspace info
                                                                    var slackTeam = new JsonObject()
                                                                            .put(ID, authResponseBody.getString("team_id"))
                                                                            .put("name", authResponseBody.getString("team"))
                                                                            .put(CHANNELS, new JsonArray());

                                                                    // Add all channels to the team
                                                                    for (var i = 0; i < channels.size(); i++)
                                                                    {
                                                                        var channel = channels.getJsonObject(i);

                                                                        slackTeam.getJsonArray(CHANNELS).add(new JsonObject()
                                                                                .put(ID, channel.getString(ID))
                                                                                .put("name", channel.getString("name"))
                                                                                .put("membershipType", channel.getBoolean("is_private", false) ? "private" : "standard"));
                                                                    }

                                                                    entities.add(slackTeam);

                                                                    if (!entities.isEmpty())
                                                                    {
                                                                        attributes.put(SLACK, entities);
                                                                    }

                                                                    promise.complete(new JsonObject().put(STATUS, STATUS_SUCCEED).put(MESSAGE, String.format(InfoMessageConstants.INTEGRATION_SYNC_SUCCEEDED, IntegrationConstants.IntegrationType.SLACK.getName())));
                                                                }
                                                                else
                                                                {
                                                                    LOGGER.warn(String.format("Slack API error in conversations.list: %s", responseBody.getString("error", "Unknown error")));

                                                                    promise.fail(String.format("Slack API error in conversations.list: %s", responseBody.getString("error", "Unknown error")));
                                                                }
                                                            }
                                                            else
                                                            {
                                                                LOGGER.warn("Invalid JSON response from Slack conversations.list API");

                                                                promise.fail("Invalid JSON response from Slack conversations.list API");
                                                            }
                                                        }
                                                        else
                                                        {
                                                            LOGGER.warn(String.format("Invalid status code in conversations.list: %s", httpResponse.statusCode()));

                                                            promise.fail(String.format("Invalid status code in conversations.list: %s", httpResponse.statusCode()));
                                                        }
                                                    }
                                                    else
                                                    {
                                                        LOGGER.error(asyncResponse.cause());

                                                        promise.fail(asyncResponse.cause());
                                                    }
                                                });
                                    }
                                    else
                                    {
                                        LOGGER.warn(String.format("Slack API error in auth.test: %s", authResponseBody.getString("error", "Unknown error")));

                                        promise.fail(String.format("Slack API error in auth.test: %s", authResponseBody.getString("error", "Unknown error")));
                                    }
                                }
                                else
                                {
                                    LOGGER.warn("Invalid JSON response from Slack auth.test API");

                                    promise.fail("Invalid JSON response from Slack auth.test API");
                                }
                            }
                            else
                            {
                                LOGGER.warn(String.format("Invalid status code in auth.test: %s", authHttpResponse.statusCode()));

                                promise.fail(String.format("Invalid status code in auth.test: %s", authHttpResponse.statusCode()));
                            }
                        }
                        else
                        {
                            LOGGER.error(authResponse.cause());

                            promise.fail(authResponse.cause());
                        }
                    });
        }
        else
        {
            promise.fail("Credential profile not configured");
        }

        return promise.future();
    }

    /**
     * Generates an OAuth access token for Slack Web API authentication.
     * <p>
     * This method:
     * 1. Validates the integration context
     * 2. Retrieves the credential profile from the store using the ID in the context
     * 3. Sends a request to the OAuth token generation event bus
     * 4. Returns the generated access token or fails with an error message
     * <p>
     * The access token is used to authenticate requests to Slack Web API
     * when synchronizing channels data or sending notifications.
     *
     * @param context The integration context containing credential profile information
     * @return A Future that completes with the access token or fails with an error message
     */
    private Future<String> getToken(JsonObject context)
    {
        var promise = Promise.<String>promise();

        try
        {
            if (context.containsKey(INTEGRATION_CREDENTIAL_PROFILE))
            {
                var credentialProfile = CredentialProfileConfigStore.getStore().getItem(context.getLong(INTEGRATION_CREDENTIAL_PROFILE));

                if (credentialProfile != null)
                {
                    Bootstrap.vertx().eventBus().<String>request(EVENT_OAUTH_TOKEN_GENERATE, credentialProfile,
                     new DeliveryOptions().setSendTimeout(15 * 1000L), asyncResult ->
                     {
                         if (asyncResult.succeeded())
                         {
                             promise.complete(asyncResult.result().body());
                         }
                         else
                         {
                             LOGGER.error(asyncResult.cause());

                             promise.fail(asyncResult.cause());
                         }
                     });
                }
                else
                {
                    promise.fail("Credential profile not found");
                }
            }
            else
            {
                promise.fail("Credential profile not configured");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }
}
