package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import com.mindarray.util.PortUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.eventbus.EventBusConstants.ChangeNotificationType.UPDATE_CACHE;

public class ConfigDatastore extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(ConfigDatastore.class, MOTADATA_DATASTORE, "Config Datastore Manager");
    private boolean flag = true;
    private DatastoreEngine eventEngine;

    private String uuid;

    public ConfigDatastore()
    {

    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var tokens = config().getString(EventBusConstants.EVENT_TYPE).split(DOT_SEPARATOR_ESCAPE);

        uuid = tokens[tokens.length - 2];

        eventEngine = new DatastoreEngine().setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                .setPersistEventOffset(true).setRemoteStatus(false).setPause(true).setLogger(LOGGER).setEventHandler(this::publish).start(vertx, promise);

        // this timer will run till all the required failover or slave node registered.
        vertx.setPeriodic(30 * 1000L, timer ->
        {
            if (RemoteEventProcessorConfigStore.getStore().getItemsByValue(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.APP.name()).size() == MotadataConfigUtil.getHAFailoverNodes())
            {
                flag = true;

                vertx.cancelTimer(timer);

                LOGGER.info(String.format("%s item registered. now app can send the data to observer to write data with respect to uuid", MotadataConfigUtil.getHAFailoverNodes()));
            }
        });

        //send a request to check if the cache file needs updated. If an update file then read the file and send the response back.
        vertx.setPeriodic(MotadataConfigUtil.getCachePollTimerSeconds(), message ->
        {
            if (flag)
            {
                if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                {
                    vertx.eventBus().publish(EVENT_CHANGE_NOTIFICATION, new JsonObject().put(CHANGE_NOTIFICATION_TYPE, UPDATE_CACHE.name()));
                }
                else
                {
                    LOGGER.warn(String.format("observer is down , address : %s ", MotadataConfigUtil.getRemoteEventObserverPublisher() + ":" + MotadataConfigUtil.getMotadataObserverEventPublisherPort()));
                }
            }
        });

        vertx.setPeriodic(MotadataConfigUtil.getConfigDBPollTimerSeconds(), handler ->
        {
            if (flag)
            {
                if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                {
                    for (var index = 0; index < MotadataConfigUtil.getConfigDBWorkerInstances(); index++)
                    {
                        vertx.eventBus().publish(EVENT_HA_CONFIG_MANGER_SYNC + DOT_SEPARATOR + Bootstrap.getRegistrationId() + DOT_SEPARATOR + index +  DOT_SEPARATOR + "active",1);
                    }
                }
                else
                {
                    LOGGER.warn(String.format("Observer is down , address : %s ", MotadataConfigUtil.getRemoteEventObserverPublisher() + ":" + MotadataConfigUtil.getMotadataObserverEventPublisherPort()));
                }
            }
        });
    }

    private void publish(JsonObject event)
    {
        vertx.eventBus().send(EVENT_HA_OBSERVER, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,uuid).put(EVENT_TOPIC, EVENT_HA_OBSERVER).put(EVENT_TYPE, EVENT_HA_CONFIG_OBSERVER_SYNC));

        LOGGER.trace(String.format("event sent to publication motadata observer %s ",uuid));
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            if (eventEngine != null)
            {
                eventEngine.stop(vertx,promise);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}


