import com.mindarray.util.CodecUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

import static com.mindarray.eventbus.EventBusConstants.*;

public class DatastoreManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(DatastoreManager.class, GlobalConstants.MOTADATA_DB, "Datastore Manager");
    private final Set<String> eventCategories = new HashSet<>();
    private JsonObject metricColumns;
    private JsonObject eventColumns;
    private JsonObject indexableColumns;
    private boolean metricColumnMapperUpdated = false;
    private boolean eventColumnMapperUpdated = false;
    private boolean indexableColumnMapperUpdated = false;
    private boolean categoryUpdated = false;

    @Override
    public void start(Promise<Void> promise)
    {
        metricColumns = new JsonObject();

        eventColumns = new JsonObject();

        indexableColumns = new JsonObject();

        loadColumns(metricColumns, DBConstants.METRIC_COLUMNS);

        loadColumns(eventColumns, DBConstants.EVENT_COLUMNS);

        loadColumns(indexableColumns, DBConstants.INDEXABLE_COLUMNS);

        loadCategories();

        vertx.setPeriodic(10000, timerHandler ->
        {
            try
            {
                if (metricColumnMapperUpdated)
                {
                    metricColumnMapperUpdated = false;

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + DBConstants.METRIC_COLUMNS,
                            Buffer.buffer(CodecUtil.compress(metricColumns.encode().getBytes())));

                    if(MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(GlobalConstants.BootstrapType.MASTER.name()))
                    {
                        DBConstants.sync(DBConstants.METRIC_COLUMNS,metricColumns.encode().getBytes(),"vertical",DBConstants.METRIC_COLUMNS);
                    }

                }

                if (eventColumnMapperUpdated)
                {
                    eventColumnMapperUpdated = false;

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + DBConstants.EVENT_COLUMNS,
                            Buffer.buffer(CodecUtil.compress(eventColumns.encode().getBytes())));

                    if(MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(GlobalConstants.BootstrapType.MASTER.name()))
                    {
                        DBConstants.sync(DBConstants.EVENT_COLUMNS,eventColumns.encode().getBytes(),"verticle",DatastoreManager.class.getSimpleName());
                    }

                }

                if (indexableColumnMapperUpdated)
                {
                    indexableColumnMapperUpdated = false;

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + DBConstants.INDEXABLE_COLUMNS,
                            Buffer.buffer(CodecUtil.compress(indexableColumns.encode().getBytes())));

                    if(MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(GlobalConstants.BootstrapType.MASTER.name()))
                    {
                        DBConstants.sync(DBConstants.INDEXABLE_COLUMNS,indexableColumns.encode().getBytes(),"verticle",DatastoreManager.class.getSimpleName());
                    }

                }

                if (categoryUpdated)
                {
                    categoryUpdated = false;

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + DBConstants.EVENT_CATEGORIES,
                            Buffer.buffer(CodecUtil.compress(new JsonArray(new ArrayList<>(eventCategories)).encode().getBytes())));

                    if(MotadataConfigUtil.getSystemBootstrapType().equalsIgnoreCase(GlobalConstants.BootstrapType.MASTER.name()))
                    {
                        DBConstants.sync(DBConstants.EVENT_CATEGORIES,CodecUtil.compress(new JsonArray(new ArrayList<>(eventCategories)).encode().getBytes()),"verticle",DatastoreManager.class.getSimpleName());
                    }

                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<String>localConsumer(EVENT_EVENT_CATEGORY_UPDATE, message ->
        {
            try
            {
                if (!message.body().isEmpty() && !eventCategories.contains(message.body()))
                {
                    eventCategories.add(message.body());

                    categoryUpdated = true;
                }
            }
            catch (Exception exception)
            {
                message.fail(GlobalConstants.NOT_AVAILABLE, exception.getMessage());

                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_COLUMN_MAPPER_QUERY, message ->
        {
            try
            {
                message.reply(new JsonObject().put(DBConstants.METRIC_COLUMNS, metricColumns).put(DBConstants.EVENT_COLUMNS, eventColumns));
            }

            catch (Exception exception)
            {
                message.fail(GlobalConstants.NOT_AVAILABLE, exception.getMessage());

                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EVENT_INDEXABLE_COLUMN_UPDATE, message ->
        {
            var event = message.body();

            try
            {
                if (!event.isEmpty())
                {

                    for (var entry : event.getJsonObject(EVENT_CONTEXT).getMap().entrySet())
                    {
                        indexableColumns.getMap().computeIfAbsent(entry.getKey(), value -> new JsonArray());

                        for (var column : JsonObject.mapFrom(entry.getValue()).getMap().entrySet())
                        {
                            if (!indexableColumns.getJsonArray(entry.getKey()).contains(column.getKey()))
                            {
                                indexableColumns.getJsonArray(entry.getKey()).add(column.getKey());

                                indexableColumnMapperUpdated = true;
                            }
                        }
                    }
                }
            }
            catch (Exception exception)
            {
                message.fail(GlobalConstants.NOT_AVAILABLE, exception.getMessage());

                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_INDEXABLE_COLUMN_QUERY, message ->
        {
            var event = message.body();

            try
            {
                if (!event.isEmpty())
                {
                    var pluginIds = event.getJsonArray(GlobalConstants.PLUGIN_ID);

                    var indexableColumns = new HashSet<>();

                    for (var index = 0; index < pluginIds.size(); index++)
                    {
                        var tokens = pluginIds.getString(index).split(GlobalConstants.DASH_SEPARATOR);

                        if (CommonUtil.getInteger(tokens[0]) != DBConstants.PluginId.CORRELATED_METRIC.getName())
                        {
                            if (CommonUtil.getInteger(tokens[0]) == DBConstants.PluginId.GENERIC_LOG_EVENT.getName() || CommonUtil.getInteger(tokens[0]) == DBConstants.PluginId.LOG_EVENT_STAT.getName())
                            {
                                indexableColumns.add(EVENT_SOURCE);

                                indexableColumns.add(LogEngineConstants.EVENT_CATEGORY);

                                indexableColumns.add(LogEngineConstants.EVENT_SOURCE_TYPE);
                            }

                            else if (CommonUtil.getInteger(tokens[0]) == DBConstants.PluginId.FLOW_EVENT.getName())
                            {
                                indexableColumns.add(EVENT_SOURCE);

                                indexableColumns.addAll(FlowEngineConstants.FLOW_INDEXABLE_COLUMNS.getList());
                            }

                            else
                            {

                                var plugin = pluginIds.getString(index).replace(" ", ".").toLowerCase();

                                if (CommonUtil.getInteger(tokens[0]) > DBConstants.PluginId.LOG_EVENT.getName())//log plugin
                                {
                                    indexableColumns.add(EVENT_SOURCE);

                                    indexableColumns.add(LogEngineConstants.EVENT_CATEGORY);

                                    indexableColumns.add(LogEngineConstants.EVENT_SOURCE_TYPE);
                                }


                                if (this.indexableColumns.containsKey(plugin) && this.indexableColumns.getValue(plugin) != null && !this.indexableColumns.getJsonArray(plugin).isEmpty())
                                {
                                    indexableColumns.addAll(this.indexableColumns.getJsonArray(plugin).getList());
                                }

                                else
                                {
                                    //as indexable column not updated then show all columns for grouping and filtering purpose

                                    for (var entry : eventColumns.getMap().entrySet())
                                    {
                                        var column = JsonObject.mapFrom(entry.getValue());

                                        if (column.getJsonArray(DBConstants.MAPPER_PLUGIN_IDS).contains(CommonUtil.getInteger(tokens[0])) && column.getString(DBConstants.MAPPER_EVENT_CATEGORY).equalsIgnoreCase(tokens[1]))
                                        {
                                            indexableColumns.add(entry.getKey());
                                        }
                                    }
                                }
                            }
                        }
                    }

                    indexableColumns.remove(EVENT);

                    indexableColumns.remove(LogEngineConstants.EVENT_PATTERN_ID);

                    indexableColumns.remove(GlobalConstants.MESSAGE);

                    message.reply(new JsonObject().put(GlobalConstants.RESULT, new ArrayList<>(indexableColumns)));
                }
            }

            catch (Exception exception)
            {
                message.fail(GlobalConstants.NOT_AVAILABLE, exception.getMessage());

                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE, message ->
        {
            try
            {
                var event = message.body();

                if (event.getString(CHANGE_NOTIFICATION_TYPE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.UPDATE_METRIC_COLUMN.name()))
                {
                    update(metricColumns, event.getString(DBConstants.MAPPER).split(GlobalConstants.COLUMN_SEPARATOR, -1), true);

                    metricColumnMapperUpdated = true;
                }

                else if (event.getString(CHANGE_NOTIFICATION_TYPE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.UPDATE_EVENT_COLUMN.name()))
                {
                    update(eventColumns, event.getString(DBConstants.MAPPER).split(GlobalConstants.COLUMN_SEPARATOR, -1), false);

                    eventColumnMapperUpdated = true;
                }
            }

            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        promise.complete();
    }

    private void update(JsonObject columns, String[] tokens, boolean metric)
    {
        var column = tokens[DBConstants.MetricWriterOrdinal.COLUMN.ordinal()].toLowerCase();

        var garbageColumn = false;

        if (!columns.containsKey(column))
        {
            columns.put(column, new JsonObject());
        }

        var mapper = columns.getJsonObject(column);

        var plugins = mapper.getJsonArray(DBConstants.MAPPER_PLUGIN_IDS);

        if (plugins == null)
        {
            plugins = new JsonArray(new ArrayList<>(1));
        }

        if (!plugins.contains(CommonUtil.getInteger(tokens[1])))
        {
            mapper.put(DBConstants.MAPPER_PLUGIN_IDS, plugins.add(CommonUtil.getInteger(tokens[1])));
        }

        var dataCategories = mapper.getJsonArray(DBConstants.MAPPER_DATA_CATEGORIES);

        if (metric)
        {
            mapper.put(DBConstants.MAPPER_STATUS, tokens[3]);

            //#24371 add garbage column
            if (mapper.getString(DBConstants.MAPPER_STATUS).equalsIgnoreCase(GlobalConstants.NO) && (column.endsWith(".id") || column.endsWith(".uptime") || column.endsWith(".version") || column.endsWith(".state") ||
                    column.endsWith(".status") || column.endsWith(".creation.time.seconds") || column.endsWith(".uptime.sec") ||
                    column.endsWith(".uptime.seconds") || column.endsWith(".time.seconds") || column.endsWith(".started.time")))
            {
                garbageColumn = true;
            }
        }

        if (plugins.contains(DBConstants.PluginId.CORRELATED_METRIC.getName()))
        {
            mapper.put(DBConstants.MAPPER_CORRELATED, tokens[3]);
        }

        if (!metric && tokens.length > 4)
        {
            mapper.put(DBConstants.MAPPER_EVENT_CATEGORY, tokens[4]);
        }

        if (metric && tokens.length > 4)
        {
            mapper.put(DBConstants.MAPPER_DURATION, tokens[4]);
        }

        if (dataCategories == null)
        {
            dataCategories = new JsonArray(new ArrayList<>(1));
        }

        if (garbageColumn)
        {
            mapper.put(DBConstants.MAPPER_DATA_CATEGORIES, dataCategories.add(DBConstants.DataCategory.STRING.getName()));
        }
        else
        {
            if (!dataCategories.contains(CommonUtil.getInteger(tokens[0])))
            {
                mapper.put(DBConstants.MAPPER_DATA_CATEGORIES, dataCategories.add(CommonUtil.getInteger(tokens[0])));
            }
        }

        if (column.contains(GlobalConstants.INSTANCE_SEPARATOR))
        {
            //25286 Bug lowercase
            mapper.put(DBConstants.MAPPER_INSTANCE, column.split(GlobalConstants.INSTANCE_SEPARATOR)[0].toLowerCase());
        }

        if (mapper.containsKey(DBConstants.MAPPER_CORRELATED) && mapper.getString(DBConstants.MAPPER_CORRELATED).equalsIgnoreCase(GlobalConstants.YES))
        {
            mapper.put(DBConstants.MAPPER_GROUP, tokens[DBConstants.EventWriterOrdinal.GROUP.ordinal()]);
        }
    }

    private void loadColumns(JsonObject columns, String filter)
    {
        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + filter);

            if (file.exists())
            {
                var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    columns.mergeIn(new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))));

                    LOGGER.info(String.format("%s loaded from the backup file...", filter));
                }
            }

            else
            {
                vertx.fileSystem().createFileBlocking(file.getPath());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void loadCategories()
    {
        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + DBConstants.EVENT_CATEGORIES);

            if (file.exists())
            {
                var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    new JsonArray(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).forEach(category -> eventCategories.add(CommonUtil.getString(category)));

                    LOGGER.info("loaded event categories");
                }
            }
            else
            {
                vertx.fileSystem().createFileBlocking(file.getPath());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
