package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.LicenseUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class LicenseCacheStore extends AbstractCacheStore
{
    private static final LicenseCacheStore STORE = new LicenseCacheStore();

    private static final Logger LOGGER = new Logger(LicenseCacheStore.class, GlobalConstants.MOTADATA_STORE, "License Cache Store");
    private final Map<String, Integer> items = new ConcurrentHashMap<>();

    private LicenseCacheStore()
    {
    }

    public static LicenseCacheStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        if (Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.DEFAULT)
        {
            items.put(NMSConstants.OBJECTS, ObjectConfigStore.getStore().getProvisionedItems());
            items.put(NMSConstants.AGENTS, AgentConfigStore.getStore().getProvisionedMetricAgents());
            items.put(NMSConstants.VMS, MetricConfigStore.getStore().getProvisionedInstances(NMSConstants.VMS));
            items.put(NMSConstants.APPS, MetricConfigStore.getStore().getProvisionedInstances(NMSConstants.APPS));
            items.put(NMSConstants.ACCESS_POINTS, MetricConfigStore.getStore().getProvisionedInstances(NMSConstants.ACCESS_POINTS));
            items.put(NMSConstants.CONFIG_DEVICES, ConfigurationConfigStore.getStore().getProvisionedItems());

            promise.complete();

            LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
        }

        else
        {
            promise.fail(String.format("failed to init store %s, reason: invalid boot sequence...", this.getClass().getSimpleName()));
        }

        return promise.future();
    }

    public long getConsumedLicenses()
    {
        return (items.getOrDefault(NMSConstants.VMS, 0) +
                items.getOrDefault(NMSConstants.OBJECTS, 0) +
                items.getOrDefault(NMSConstants.APPS, 0) +
                items.getOrDefault(NMSConstants.AGENTS, 0)) +
                Math.round(Math.ceil(CommonUtil.getDouble(items.getOrDefault(NMSConstants.ACCESS_POINTS, 0)) / LicenseUtil.InstanceLicense.ACCESS_POINT.getValue()));
    }

    public void update(String type, int number, boolean provision)
    {
        if (provision)
        {
            items.put(type, items.getOrDefault(type, 0) + number);

            if (CommonUtil.traceEnabled())
            {
                LOGGER.trace(String.format("provision type: %s, cache license: %s", type, items));
            }
        }
        else
        {
            items.put(type, items.getOrDefault(type, 0) - number);

            if (CommonUtil.traceEnabled())
            {

                LOGGER.trace(String.format("provision type: %s, cache license: %s", type, items));
            }
        }

    }

    /**
     * @param type      type of Objects (example: objects, apps, agents)
     * @param provision `true` if added to cache and `false` to remove from cache
     */
    public void update(String type, boolean provision)
    {
        if (provision)
        {
            items.put(type, items.getOrDefault(type, 0) + 1);
        }
        else
        {
            items.put(type, items.getOrDefault(type, 0) - 1);
        }
    }

    public long getConsumedConfigLicenses()
    {
        return items.getOrDefault(NMSConstants.CONFIG_DEVICES, 0);
    }
}

