package com.mindarray.store;

import com.mindarray.GlobalConstants;
import com.mindarray.api.APIConstants;
import com.mindarray.db.ConfigDBConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class AuthTokenConfigStore extends AbstractConfigStore
{

    private static final Logger LOGGER = new Logger(AuthTokenConfigStore.class, GlobalConstants.MOTADATA_STORE, "Auth Token Config Store");

    private static final AuthTokenConfigStore STORE = new AuthTokenConfigStore();

    private final Map<String, Long> tokens = new ConcurrentHashMap<>();

    private AuthTokenConfigStore()
    {

        super(ConfigDBConstants.COLLECTION_TOKEN, LOGGER, false);
    }

    public static AuthTokenConfigStore getStore()
    {
        return STORE;
    }

    public JsonObject getItem(String refreshToken)
    {
        JsonObject token = null;

        if (tokens.containsKey(refreshToken))
        {
            token = new JsonObject();

            var item = items.get(tokens.get(refreshToken));

            token.put(APIConstants.AUTH_ACCESS_TOKEN, item.getString(APIConstants.AUTH_ACCESS_TOKEN));

            token.put(GlobalConstants.REMOTE_ADDRESS, item.getString(GlobalConstants.REMOTE_ADDRESS));
        }

        return token;
    }

    public long getUserId(String refreshToken)
    {
        var userId = CommonUtil.getLong(GlobalConstants.NOT_AVAILABLE);

        if (tokens.containsKey(refreshToken))
        {
            userId = items.get(tokens.get(refreshToken)).getLong(APIConstants.TOKEN_USER);
        }

        return userId;
    }

    public void deleteItem(String refreshToken)
    {
        if (tokens.containsKey(refreshToken))
        {
            deleteItem(tokens.remove(refreshToken));
        }

    }

    public Future<Void> updateItem(String refreshToken)
    {
        var promise = Promise.<Void>promise();

        if (tokens.containsKey(refreshToken))
        {
            addItem(tokens.get(refreshToken)).onComplete(future ->
            {

                if (future.succeeded())
                {
                    promise.complete();
                }

                else
                {
                    promise.fail(future.cause());
                }
            });
        }

        else
        {
            promise.complete();
        }

        return promise.future();

    }

    @Override
    public Future<Void> addItem(long id)
    {
        var promise = Promise.<Void>promise();

        super.addItem(id).onComplete(future ->
        {

            if (future.succeeded())
            {
                tokens.put(items.get(id).getString(APIConstants.TOKEN_ID), id);

                promise.complete();
            }

            else
            {
                promise.fail(future.cause());

            }
        });

        return promise.future();

    }

    @Override
    public Future<Void> initStore()
    {

        var promise = Promise.<Void>promise();

        try
        {
            super.initStore().onComplete(future ->
            {
                if (future.succeeded())
                {
                    items.forEach((id, item) -> tokens.put(item.getString(APIConstants.TOKEN_ID), id));

                    promise.complete();
                }

                else
                {
                    promise.fail(future.cause());
                }

            });
        }

        catch (Exception exception)
        {
            promise.fail(exception);

            LOGGER.error(exception);
        }

        return promise.future();
    }
}

