package com.mindarray.agent;

import com.mindarray.GlobalConstants;
import com.mindarray.api.APIConstants;
import com.mindarray.api.Agent;
import com.mindarray.api.MotadataApp;
import com.mindarray.db.DBConstants;
import com.mindarray.store.AgentCacheStore;
import com.mindarray.store.AgentConfigStore;
import com.mindarray.store.ArtifactConfigStore;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.DateTimeUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.*;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.MotadataApp.ARTIFACT_UPGRADE_STATUS;
import static com.mindarray.eventbus.EventBusConstants.*;

public class AgentUpgradeManager extends AbstractVerticle
{
    private static final int MAX_CONCURRENT_UPGRADES = MotadataConfigUtil.getConcurrentAgentUpgradeLimit();

    private static final int AGENT_UPGRADE_TIMEOUT_SECONDS = MotadataConfigUtil.getAgentUpgradeTimeoutSeconds();

    private final List<JsonObject> upgradeEvents = new ArrayList<>();// queue of upgrade events

    private final Map<String, Long> activeUpgrades = new HashMap<>();// currently processing upgrade events till their completion or timeout

    private final Set<String> activeBatches = new HashSet<>();// currently processing upgrade batches till artifact download complete

    private static final Logger LOGGER = new Logger(AgentUpgradeManager.class, GlobalConstants.MOTADATA_AGENT, "Agent Upgrade Manager");

    private boolean timeHandlerActive = false;

    private int eventProbes;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EVENT_AGENT_UPGRADE_QUEUE, message ->
        {
            if (!activeUpgrades.containsKey(message.body().getString(Agent.AGENT_UUID)))
            {
                upgradeEvents.add(message.body());

                var id = AgentConfigStore.getStore().getAgentId(message.body().getString(Agent.AGENT_UUID));

                var status = String.format("%s Upgrade Queued", message.body().getString(DBConstants.TYPE, APIConstants.Entity.AGENT.getName()));

                var artifact = ArtifactConfigStore.getStore().getItem(id)
                        .put(ARTIFACT_UPGRADE_STATUS, status)
                        .put(MESSAGE, String.format("upgrade queued at %s", DateTimeUtil.timestamp()));

                vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION, new JsonObject().put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_ARTIFACT.name()).put(EVENT_CONTEXT, artifact).put(MotadataApp.ARTIFACT_TYPE, BootstrapType.AGENT.name()).put(ID, id).put(EVENT_COPY_REQUIRED, false));

                publish(UI_NOTIFICATION_AGENT_UPGRADE_PROGRESS, new JsonObject().put(ARTIFACT_UPGRADE_STATUS, status).put(ID, id).put(PROGRESS, 2.0).put(MESSAGE, String.format("upgrade queued at %s", DateTimeUtil.timestamp())));
            }
            else
            {
                LOGGER.warn(String.format("duplicate upgrade event received for agent : %s", ObjectConfigStore.getStore().getAgentObjectName(message.body().getLong(ID))));
            }

            if (!timeHandlerActive)
            {
                eventProbes = 0;

                timeHandlerActive = true;

                vertx.setPeriodic(TimeUnit.SECONDS.toMillis(30), timer ->
                {
                    try
                    {
                        var iterator = upgradeEvents.listIterator();

                        eventProbes = iterator.hasNext() ? 0 : eventProbes + 1;

                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace(String.format("Pending upgrade events: %d, Active upgrades: %d, Active batches: %d", upgradeEvents.size(), activeUpgrades.size(), activeBatches.size()));
                        }

                        processActiveUpgrades();

                        while (iterator.hasNext() && activeBatches.size() < MAX_CONCURRENT_UPGRADES)
                        {
                            var event = iterator.next();

                            var id = AgentConfigStore.getStore().getAgentId(event.getString(Agent.AGENT_UUID));

                            activeBatches.add(event.getString(Agent.AGENT_UUID));

                            activeUpgrades.put(event.getString(Agent.AGENT_UUID), DateTimeUtil.currentSeconds());

                            if (MotadataConfigUtil.devMode())
                            {
                                vertx.eventBus().publish(EVENT_PUBLICATION_MOTADATA_MANAGER, event.put(EVENT_COPY_REQUIRED, false));
                            }
                            else
                            {
                                vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_MANAGER, event.put(EVENT_COPY_REQUIRED, false));
                            }

                            var status = String.format("%s Upgrade Initiated", event.getString(DBConstants.TYPE, APIConstants.Entity.AGENT.getName()));

                            var artifact = ArtifactConfigStore.getStore().getItem(id)
                                    .put(ARTIFACT_UPGRADE_STATUS, status)
                                    .put(MESSAGE, String.format("upgrade started at %s", DateTimeUtil.timestamp()));

                            vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION, new JsonObject().put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_ARTIFACT.name()).put(EVENT_CONTEXT, artifact).put(MotadataApp.ARTIFACT_TYPE, BootstrapType.AGENT.name()).put(ID, id).put(EVENT_COPY_REQUIRED, false));

                            publish(UI_NOTIFICATION_AGENT_UPGRADE_PROGRESS, new JsonObject().put(ARTIFACT_UPGRADE_STATUS, status).put(ID, id).put(PROGRESS, 3.0).put(MESSAGE, String.format("upgrade started at %s", DateTimeUtil.timestamp())));

                            iterator.remove();
                        }

                        if (eventProbes > 60) //max 60 probes... i.e. 30 minutes of inactivity
                        {
                            processActiveUpgrades();

                            activeUpgrades.clear();

                            activeBatches.clear();

                            //disable timer to save cpu cycle...

                            vertx.cancelTimer(timer);

                            timeHandlerActive = false;
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                });
            }

        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EVENT_UPGRADE_COMPLETE, message ->
        {
            try
            {
                var id = message.body().getString(Agent.AGENT_UUID);

                activeUpgrades.remove(id);

                activeBatches.remove(id);
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }

        }).exceptionHandler(LOGGER::error);

        promise.complete();
    }

    private void processActiveUpgrades()
    {
        activeUpgrades.entrySet().removeIf(entry ->
        {
            var uuid = entry.getKey();

            var timestamp = entry.getValue();

            var id = AgentConfigStore.getStore().getAgentId(uuid);

            if (activeBatches.contains(uuid) && AgentCacheStore.getStore().getProgress(id) != null && AgentCacheStore.getStore().getProgress(id) >= 15)
            {
                activeBatches.remove(uuid);

                LOGGER.info(String.format("Agent/Manager artifacts download completed for agent: %s", ObjectConfigStore.getStore().getAgentObjectName(id)));
            }

            // If timeout occurs then send failure response
            if ((DateTimeUtil.currentSeconds() - timestamp) >= AGENT_UPGRADE_TIMEOUT_SECONDS)
            {
                LOGGER.info(String.format("Upgrade event processing timed out for agent/manager: %s", ObjectConfigStore.getStore().getAgentObjectName(id)));

                vertx.eventBus().send(EVENT_MANAGER_RESPONSE_PROCESSOR, new JsonObject()
                        .put(EVENT_TOPIC, MOTADATA_MANAGER_TOPIC).put(EVENT_TYPE, EVENT_AGENT_UPGRADE).put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name())
                        .put(Agent.AGENT_UUID, AgentConfigStore.getStore().getAgentUUID(id)).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                        .put(GlobalConstants.PROGRESS, 100.0).put(ID, id).put(MESSAGE, "agent/manager upgrade event timed out").put(DBConstants.TYPE, ArtifactConfigStore.getStore().getItem(id).getString(ARTIFACT_UPGRADE_STATUS, EMPTY_VALUE).contains(APIConstants.Entity.MANAGER.getName()) ? APIConstants.Entity.MANAGER.getName() : APIConstants.Entity.AGENT.getName())
                );

                return true;
            }

            return false;
        });
    }
}

