package com.mindarray;

import com.mindarray.eventbus.*;
import com.mindarray.flow.FlowListener;
import com.mindarray.flow.FlowProcessor;
import com.mindarray.util.*;
import io.vertx.core.CompositeFuture;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.eventbus.EventBusConstants.EVENT_CONFIG_INIT;

public class BootstrapFlowCollector
{
    private static final Logger LOGGER = new Logger(BootstrapFlowCollector.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Flow Collector");

    private static void startRemoteEventProcessor()
    {
        Bootstrap.startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                .onComplete(response ->
                {
                    if (response.succeeded())
                    {
                        var asyncResults = new ArrayList<Future>();

                        var subscriberPort = CommonUtil.getEventSubscriberPort();

                        for (var index = 0; index < MotadataConfigUtil.getEventSubscribers(); index++)
                        {
                            var promise = Promise.promise();

                            asyncResults.add(promise.future());

                            Bootstrap.startEngine(new RemoteEventSubscriber(subscriberPort + index), RemoteEventSubscriber.class.getSimpleName() + " " + (subscriberPort + index), null).onComplete(handler ->
                            {
                                if (handler.succeeded())
                                {
                                    promise.complete();
                                }
                                else
                                {
                                    promise.fail(handler.cause());
                                }
                            });
                        }
                        CompositeFuture.join(asyncResults).onComplete(handler ->
                        {
                            if (handler.succeeded())
                            {
                                try
                                {
                                    EventBusConstants.setRemoteEventProcessorRegistrationId();

                                    //need to start this engine after RPE register
                                    var futures = new ArrayList<Future>();

                                    var forwarderPort = CommonUtil.getEventPublisherPort();

                                    for (var index = 0; index < MotadataConfigUtil.getEventPublishers(); index++)
                                    {
                                        var promise = Promise.promise();

                                        futures.add(promise.future());

                                        Bootstrap.startEngine(new RemoteEventForwarder(forwarderPort + index), RemoteEventForwarder.class.getSimpleName() + " " + (forwarderPort + index), null).onComplete(asyncResult ->
                                        {
                                            if (asyncResult.succeeded())
                                            {
                                                promise.complete();
                                            }
                                            else
                                            {
                                                promise.fail(asyncResult.cause());
                                            }
                                        });
                                    }

                                    CompositeFuture.join(futures).onComplete(result ->
                                    {
                                        if (result.failed())
                                        {
                                            Bootstrap.stop(result.cause());
                                        }
                                        else
                                        {
                                            try
                                            {
                                                LOGGER.info(String.format("%s request to register...", Bootstrap.bootstrapType()));

                                                EventBusConstants.register(new CipherUtil(),Bootstrap.bootstrapType(),MotadataConfigUtil.getInstallationMode());

                                                GeoDBUtil.init(Bootstrap.vertx());
                                            }
                                            catch (Exception exception)
                                            {
                                                LOGGER.error(exception);
                                            }
                                        }
                                    });
                                }
                                catch (Exception exception)
                                {
                                    Bootstrap.stop(exception);
                                }
                            }
                            else
                            {
                                Bootstrap.stop(handler.cause());
                            }
                        });
                    }
                    else
                    {
                        Bootstrap.stop(response.cause());
                    }
                });

        Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EVENT_CONFIG_INIT, message ->
        {

            if (message.body() != null)
            {
                Bootstrap.startEngine(new FlowListener(), FlowListener.class.getSimpleName(), null)
                        .compose(future -> Bootstrap.startEngine(new EventSubscriber(CommonUtil.getEventSubscriberPort(), "Event Subscriber " + CommonUtil.getEventSubscriberPort(), "localhost"), EventSubscriber.class.getSimpleName() + " " + CommonUtil.getEventSubscriberPort(), null))
                        .compose(future -> Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_FLOW, "peer_ip_src", MotadataConfigUtil.getFlowProcessors(), FlowProcessor.class.getCanonicalName(), true, true, true), FlowProcessor.class.getSimpleName(), null))
                        .onComplete(result ->
                        {
                            if (result.failed())
                            {
                                Bootstrap.stop(result.cause());
                            }
                            else
                            {
                                LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                            }
                        });
            }
        });
    }

    /*
     *   Port details for Agent/RemoteEventProcessor:
     *
     *   event.publisher.port : start from 9449
     *   event.subscriber.port :start from 9444
     * */

    public void start()
    {
        try
        {
            Bootstrap.logSystemConfig();

            PortUtil.init();

            WebClientUtil.init();

            ProcessUtil.setProcessors();

            startRemoteEventProcessor();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

