        {
            Bootstrap.configDBService().update(ConfigDBConstants.COLLECTION_EVENT_POLICY, new JsonObject().put(ConfigDBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, policyId),
                    new JsonObject().put(POLICY_STATE, state), routingContext.user().principal().getString(USER_NAME)
                    , routingContext.request().remoteAddress().host(), result ->
                    {
                        if (result.succeeded())
