    private static final Set<String> INDEXING_METADATA_FIELDS = Set.of(PLUGIN_ID, EventBusConstants.EVENT_TIMESTAMP, MESSAGE, RECEIVED_TIMESTAMP, EVENT_TYPE, DatastoreConstants.DATASTORE_TYPE, EVENT_VOLUME_BYTES);

    private static final JsonObject SEVERITIES = new JsonObject().put("info", "Informational").put("warn", "Warning");

