    {
    }

    private static URLClassLoader init()
    {

        try
        {

            return new URLClassLoader(new URL[]{new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.PLUGIN_SCRIPT_DIR + GlobalConstants.PATH_SEPARATOR).toURI().toURL()});

