package com.mindarray.runbook;

import com.mindarray.Bootstrap;
import com.mindarray.BootstrapMain;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.GlobalConstants;
import com.mindarray.aiops.AIOpsConstants;
import com.mindarray.api.Integration;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.IntegrationConfigStore;
import com.mindarray.util.Logger;
import com.mindarray.util.WebClientUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;
import io.vertx.ext.web.multipart.MultipartForm;
import org.apache.http.HttpStatus;

import static com.mindarray.ErrorMessageConstants.*;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.InfoMessageConstants.INTEGRATION_TEST_SUCCEEDED;
import static com.mindarray.api.APIConstants.CLIENT_ID;
import static com.mindarray.api.APIConstants.REQUEST;
import static com.mindarray.api.Integration.*;
import static com.mindarray.db.DBConstants.COLLECTION_INTEGRATION;
import static com.mindarray.db.DBConstants.FIELD_NAME;
import static com.mindarray.eventbus.EventBusConstants.ChangeNotificationType;
import static io.netty.handler.codec.rtsp.RtspHeaders.Values.URL;

public class IntegrationHelper extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(IntegrationHelper.class, GlobalConstants.MOTADATA_UTIL, "Integration Util");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_INTEGRATION_AUTH_TOKEN_CREATE, message ->
        {

            if (!IntegrationConfigStore.getStore().getItems().isEmpty())
            {
                var event = message.body();

                var form = MultipartForm.create().attribute(USERNAME, event.getString(USERNAME)).attribute(PASSWORD, event.getString(PASSWORD)).attribute("grant_type", PASSWORD);

                event.put(INTEGRATION_SERVER_TOKEN_URL, event.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? event.getString(INTEGRATION_SERVER_URL) + AIOpsConstants.INTEGRATION_TOKEN_APIS.get(event.getString(INTEGRATION_TYPE)) : event.getString(INTEGRATION_SERVER_URL) + "/" + AIOpsConstants.INTEGRATION_TOKEN_APIS.get(event.getString(INTEGRATION_TYPE)));

                WebClientUtil.getWebClient().postAbs(event.getString(INTEGRATION_SERVER_TOKEN_URL))
                        .basicAuthentication(event.getString(CLIENT_ID), event.getString("client.secret")).timeout(event.getInteger(INTEGRATION_SERVER_URL_TIMEOUT_SECONDS) * 1000L).sendMultipartForm(form, handler ->
                        {
                            if (handler.succeeded())
                            {
                                var result = handler.result();

                                if (result.statusCode() == HttpStatus.SC_UNAUTHORIZED)
                                {
                                    LOGGER.warn(String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_TOKEN_URL)));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_TOKEN_URL))).put(MESSAGE, "Integration test failed"));
                                }
                                else if (result.statusCode() == HttpStatus.SC_BAD_REQUEST)
                                {
                                    LOGGER.warn(String.format("Invalid credentials for %s integration", event.getString(INTEGRATION_TYPE)));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, CREDENTIAL_ERROR).put(MESSAGE, "Integration test failed"));
                                }
                                else if (result.statusCode() == HttpStatus.SC_OK)
                                {
                                    LOGGER.info(String.format(INTEGRATION_TEST_SUCCEEDED, event.getString(INTEGRATION_TYPE)));

                                    if (event.containsKey(REQUEST))
                                    {
                                        LOGGER.info(String.format("Auth Token Regenerated for integration: %s", event.getString(INTEGRATION_TYPE)));

                                        BootstrapMain.configDBService().update(COLLECTION_INTEGRATION,
                                                new JsonObject().put(FIELD_NAME, ID).put(VALUE, event.getLong(ID)),
                                                new JsonObject().put(IntegrationEngine.INTEGRATION_ACCESS_TOKEN, result.bodyAsJsonObject().getString(IntegrationEngine.INTEGRATION_ACCESS_TOKEN)),
                                                SYSTEM_USER, SYSTEM_REMOTE_ADDRESS,
                                                asyncResult -> Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject().put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_INTEGRATION.name())));

                                    }
                                    else
                                    {
                                        message.reply(result.bodyAsJsonObject().put(STATUS, STATUS_SUCCEED).put(MESSAGE, "Integration test succeeded"));
                                    }
                                }
                                else if (result.statusCode() == HttpStatus.SC_NOT_FOUND)
                                {
                                    LOGGER.warn(String.format("%s integration is Down...", event.getString(Integration.INTEGRATION_TYPE)));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, UNABLE_TO_CONNECT).put(MESSAGE, "Integration test failed"));

                                }
                                else
                                {
                                    LOGGER.warn(String.format("Failed to connect with %s, status code: %s", event.getString(Integration.INTEGRATION_TYPE), result.statusCode()));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, result.statusMessage()).put(MESSAGE, "Integration test failed"));

                                }
                            }
                            else
                            {
                                message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, handler.cause().getMessage());

                                LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s", event.getString(INTEGRATION_TYPE)));
                            }
                        });
            }
            else
            {
                message.fail(HttpStatus.SC_BAD_REQUEST, "Integration(s) not found...");
            }

        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_INTEGRATION_RESPONSE_GET, message ->
        {

            if (!IntegrationConfigStore.getStore().getItems().isEmpty())
            {
                var event = message.body();

                var item = IntegrationConfigStore.getStore().getItemByValue(INTEGRATION_TYPE, event.getString(INTEGRATION_TYPE));

                event.put(INTEGRATION_SERVER_TOKEN_URL, item.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? item.getString(INTEGRATION_SERVER_URL) + "api/v1/request/" + event.getString(IntegrationEngine.ACK_ID) : item.getString(INTEGRATION_SERVER_URL) + "/" + "api/v1/request/" + event.getString(IntegrationEngine.ACK_ID));

                WebClientUtil.getWebClient().getAbs(event.getString(INTEGRATION_SERVER_TOKEN_URL))
                        .bearerTokenAuthentication(item.getString(IntegrationEngine.INTEGRATION_ACCESS_TOKEN)).send(handler ->
                        {
                            if (handler.succeeded())
                            {
                                var result = handler.result();

                                if (result.statusCode() == HttpStatus.SC_UNAUTHORIZED)
                                {
                                    LOGGER.warn(String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_TOKEN_URL)));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_TOKEN_URL))).put(MESSAGE, "Integration test failed"));
                                }
                                else if (result.statusCode() == HttpStatus.SC_BAD_REQUEST)
                                {
                                    LOGGER.warn(String.format("Invalid credentials for %s integration", event.getString(INTEGRATION_TYPE)));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, CREDENTIAL_ERROR).put(MESSAGE, "Integration test failed"));
                                }
                                else if (result.statusCode() == HttpStatus.SC_OK)
                                {
                                    LOGGER.info(String.format(INTEGRATION_TEST_SUCCEEDED, event.getString(INTEGRATION_TYPE)));

                                    message.reply(result.bodyAsJsonObject().put(STATUS, STATUS_SUCCEED).put(MESSAGE, "Integration test succeeded").put(URL, event.getString(INTEGRATION_SERVER_TOKEN_URL)).put(IntegrationEngine.INTEGRATION_ACCESS_TOKEN, item.getString(IntegrationEngine.INTEGRATION_ACCESS_TOKEN)));
                                }
                                else if (result.statusCode() == HttpStatus.SC_NOT_FOUND)
                                {
                                    LOGGER.warn(String.format("%s integration is Down...", event.getString(Integration.INTEGRATION_TYPE)));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, String.format("Integration %s is Down", event.getString(Integration.INTEGRATION_TYPE))).put(MESSAGE, "Integration test failed"));

                                }
                                else
                                {
                                    LOGGER.warn(String.format("Failed to connect with %s, status code: %s", event.getString(Integration.INTEGRATION_TYPE), result.statusCode()));

                                    message.reply(new JsonObject().put(STATUS, STATUS_FAIL).put(ERROR, INTERNAL_ERROR).put(MESSAGE, "Integration test failed"));

                                }
                            }
                            else
                            {
                                message.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR, handler.cause().getMessage());

                                LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s", event.getString(INTEGRATION_TYPE)));
                            }
                        });
            }
            else
            {
                message.fail(HttpStatus.SC_BAD_REQUEST, "Integration(s) not found...");
            }

        });

        promise.complete();
    }

    @Override
    public void stop(Promise<Void> promise)
    {
        promise.complete();
    }
}

