package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.SingleSignOn;
import com.mindarray.db.DBConstants;
import com.mindarray.store.SingleSignOnConfigStore;
import com.mindarray.util.Logger;
import com.mindarray.util.SingleSignOnUtil;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.GlobalConstants.*;

public class Patch813 implements Patch
{
    private static final Logger LOGGER = new Logger(Patch813.class, MOTADATA_PATCH, "Patch 8.1.3");

    private static final String VERSION = "8.1.3";

    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("executing 8.1.3 patch...");

            var futures = new ArrayList<Future<Void>>();

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully executed 8.1.3 patch");

                    futures.add(executeSingleSignOnPatch());

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> executeSingleSignOnPatch()
    {
        var promise = Promise.<Void>promise();

        var item = SingleSignOnConfigStore.getStore().getItem();

        var context = item.getJsonObject(SingleSignOn.SAML_AUTHENTICATION_CONTEXT);

        if (context != null && context.containsKey(SingleSignOn.SAML_FILE_BASED_AUTHENTICATION))
        {
            item.getJsonObject(SingleSignOn.SAML_AUTHENTICATION_CONTEXT).put(SingleSignOn.SAML_CONSUMER_SERVICE, SingleSignOnUtil.getServerURL());

            Bootstrap.configDBService().update(DBConstants.TBL_SINGLE_SIGN_ON,
                    new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, item.getLong(ID)),
                    item, DEFAULT_USER, MOTADATA_SYSTEM, result ->
                    {
                        if (result.succeeded())
                        {
                            SingleSignOnConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult -> promise.complete());
                        }
                        else
                        {
                            LOGGER.error(result.cause());

                            promise.fail(result.cause());
                        }
                    });
        }
        else
        {
            LOGGER.info("SSO is not configured, no need to execute patch");

            promise.complete();
        }

        return promise.future();
    }
}

