                TestAPIUtil.put(METRIC_API_ENDPOINT + "/" + esxiId, new JsonObject().put(REQUEST_PARAMS, new JsonArray().add(metric.getJsonArray("VMware ESXi VM").getJsonObject(0))), testContext.succeeding(httpResponse ->
