        runServiceCheckDiscoveryTest(testContext, DiscoveryConfigStore.getStore().getItemByValue(Discovery.DISCOVERY_NAME, DISCOVERY_PROFILES.getJsonObject(testInfo.getTestMethod().get().getName()).getString(Discovery.DISCOVERY_NAME)));
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(5)
    void testNTPServiceCheckDiscovery(VertxTestContext testContext, TestInfo testInfo)
    {
        runServiceCheckDiscoveryTest(testContext, DiscoveryConfigStore.getStore().getItemByValue(Discovery.DISCOVERY_NAME, DISCOVERY_PROFILES.getJsonObject(testInfo.getTestMethod().get().getName()).getString(Discovery.DISCOVERY_NAME)));
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(6)
