package com.mindarray.store;

import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.APIConstants;
import com.mindarray.api.Discovery;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.db.DBConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

import static com.mindarray.api.APIConstants.*;

public class RemoteEventProcessorConfigStore extends AbstractConfigStore
{

    private static final Logger LOGGER = new Logger(RemoteEventProcessorConfigStore.class, GlobalConstants.MOTADATA_STORE, "Remote Event Processor Config Store");
    private static final RemoteEventProcessorConfigStore STORE = new RemoteEventProcessorConfigStore();
    private final Map<String,Map<String, Long>> itemTypeByUUID = new ConcurrentHashMap<>(); // type -> (uuid -> id)
    private final Map<String, String> dataStoreTypeByUUID = new ConcurrentHashMap<>();   // type -> uuid
    private final Map<String, String> itemByUUID = new ConcurrentHashMap<>();

    private RemoteEventProcessorConfigStore()
    {

        super(DBConstants.COLLECTION_REMOTE_EVENT_PROCESSOR, LOGGER, false, new ArrayList<>()
        {{

            add(new HashMap<>()
            {{
                put(REFERENCE_ENTITY, APIConstants.Entity.DISCOVERY);
                put(REFERENCE_ENTITY_PROPERTY, Discovery.DISCOVERY_EVENT_PROCESSORS);
                put(REFERENCE_ENTITY_STORE, ConfigStore.DISCOVERY);
                put(REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.MULTI_VALUE);
            }});

            add(new HashMap<>()
            {{
                put(REFERENCE_ENTITY, APIConstants.Entity.OBJECT);
                put(REFERENCE_ENTITY_PROPERTY, AIOpsObject.OBJECT_EVENT_PROCESSORS);
                put(REFERENCE_ENTITY_STORE, ConfigStore.OBJECT);
                put(REFERENCE_ENTITY_PROPERTY_TYPE, ReferenceEntityPropertyType.MULTI_VALUE);
            }});

        }});
    }

    public static RemoteEventProcessorConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> addItem(long id)
    {
        var promise = Promise.<Void>promise();

        super.addItem(id).onComplete(result ->
        {
            if (result.succeeded())
            {
                var item = getItem(id);

                var type = item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE);

                itemTypeByUUID.computeIfAbsent(type, value->new HashMap<>());

                itemTypeByUUID.get(type).put(item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID),id);

                itemByUUID.put(getItem(id).getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID), getItem(id).getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_IP));

                if(item.containsKey(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE)
                        && item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE).equalsIgnoreCase(GlobalConstants.BootstrapType.DATANODE.name())
                        && (item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE).equalsIgnoreCase(GlobalConstants.InstallationMode.PRIMARY.name())
                        || item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE).equalsIgnoreCase(GlobalConstants.InstallationMode.SECONDARY.name())))
                {
                    LOGGER.info(String.format("datanode added : %s ",item.encodePrettily()));

                    dataStoreTypeByUUID.put(item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE),getItem(id).getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID));
                }
            }

            promise.complete();
        });

        return promise.future();
    }

    @Override
    public void deleteItem(long id)
    {
        if (items.containsKey(id))
        {
            super.deleteItem(id);

            RemoteEventProcessorCacheStore.getStore().deleteItem(id);

            init();
        }

    }

    @Override
    public void deleteItems(JsonArray ids)
    {
        super.deleteItems(ids);

        init();
    }

    public Long getItemUUIDByType(String uuid, String type)
    {
        if (itemTypeByUUID.containsKey(type))
        {
            return itemTypeByUUID.get(type).get(uuid);
        }

        return null;
    }

    public String getItemByUUID(String uuid)
    {
        return itemByUUID.getOrDefault(uuid,null);
    }

    public String getDatastoreTypeByUUID()
    {
        if(!dataStoreTypeByUUID.isEmpty())
        {
            var uuid = dataStoreTypeByUUID.get(DBConstants.DataNodeType.PRIMARY.name());

            if(uuid != null && RemoteEventProcessorCacheStore.getStore().getState(itemTypeByUUID.get(GlobalConstants.BootstrapType.DATANODE.name()).get(uuid)).equalsIgnoreCase(NMSConstants.STATE_RUNNING))
            {
                return uuid;
            }
            else if(dataStoreTypeByUUID.containsKey(DBConstants.DataNodeType.SECONDARY.name()))
            {
                return dataStoreTypeByUUID.get(DBConstants.DataNodeType.SECONDARY.name());
            }
        }

        return GlobalConstants.EMPTY_VALUE;
    }

    private void init()
    {
        itemTypeByUUID.clear();

        dataStoreTypeByUUID.clear();

        var iterator = items.entrySet().iterator();

        while (iterator.hasNext())
        {
            var item = iterator.next();

            var id = item.getKey();

            var processor = item.getValue();

            var processorByType = itemTypeByUUID.getOrDefault(processor.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE),new HashMap<>());

            processorByType.put(processor.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID),id);

            itemTypeByUUID.put(processor.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE),processorByType);
        }

        items.values().stream().filter(item -> item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_IP) != null)
                .collect(Collectors.groupingBy(item -> item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_IP),
                        Collectors.mapping(item -> item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE), Collectors.toList())))
                .forEach((key, value) -> itemByUUID.put(key, value.get(0)));


        items.forEach((key, value) ->
        {
            if (value.containsKey(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE) && value.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE).equalsIgnoreCase(GlobalConstants.BootstrapType.DATANODE.name()))
            {
                LOGGER.info(String.format("datanode initialized : %s ",value.encodePrettily()));

                dataStoreTypeByUUID.put(value.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE), value.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID));
            }
        });

    }

    @Override
    public Future<Void> initStore()
    {

        var promise = Promise.<Void>promise();

        super.initStore().onComplete(result ->
        {
            if (result.succeeded())
            {
                try
                {
                    init();

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
                }

                catch (Exception exception)
                {
                    promise.fail(exception);

                    LOGGER.warn("failed to init remote event processor config store...");

                    LOGGER.error(exception);
                }
            }

            else
            {
                promise.fail(result.cause());
            }
        });

        return promise.future();
    }

}

