                    new JsonArray().add(NMSConstants.Type.WINDOWS.getName()).add(NMSConstants.Type.WINDOWS_CLUSTER.getName()).add(NMSConstants.Type.HYPER_V.getName()).add(NMSConstants.Type.HYPER_V_CLUSTER.getName());

