package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.*;

public class DatastoreManager extends AbstractVerticle
{
    private final Set<String> items = new HashSet<>(); //items by uuid store last read file
    private static final Logger LOGGER = new Logger(DatastoreManager.class, GlobalConstants.MOTADATA_DATASTORE, "Datastore Manager");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            var metricType = EventBusConstants.EVENT_DATASTORE_WRITE + GlobalConstants.DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.METRIC.getName();

            var eventType = EventBusConstants.EVENT_DATASTORE_WRITE + GlobalConstants.DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.EVENT.getName();

            load(metricType,eventType);

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_DATASTORE_REGISTER, message ->
            {
                var uuid = message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID);

                if(!items.contains(uuid))
                {
                    LOGGER.info(String.format("%s datastore registration event received...",uuid));

                    Bootstrap.startEngine(new MetricDatastoreManager(metricType + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getMetricDatastoreWorkerInstances(), MetricDatastoreWorker.class.getCanonicalName(), true), MetricDatastoreManager.class.getCanonicalName() + " " + uuid, null)
                            .compose(future -> Bootstrap.startEngine(new EventDatastoreManager(eventType + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getEventDatastoreWorkerInstances(), EventDatastoreWorker.class.getCanonicalName(), true), EventDatastoreManager.class.getCanonicalName() + " " + uuid, null))
                            .onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    items.add(uuid);

                                    LOGGER.info(String.format("%s datastore registration event completed...",uuid));
                                }
                            });
                }

            }).exceptionHandler(LOGGER::error);

            vertx.eventBus().<byte[]>localConsumer(metricType, message ->
                    items.forEach(entry-> vertx.eventBus().send(metricType + GlobalConstants.DOT_SEPARATOR + entry,message.body()))).exceptionHandler(LOGGER::error);

            vertx.eventBus().<byte[]>localConsumer(eventType, message ->
                    items.forEach(entry-> vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + entry,message.body()))).exceptionHandler(LOGGER::error);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    private void load(String metricType, String eventType)
    {
        var entities = RemoteEventProcessorConfigStore.getStore().getItemsByValue(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE,GlobalConstants.BootstrapType.DATASTORE.name());

        for (int index = 0; index < entities.size(); index++)
        {
            var uuid = entities.getJsonObject(index).getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID);

            if(!items.contains(uuid))
            {
                Bootstrap.startEngine(new MetricDatastoreManager(metricType + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getMetricDatastoreWorkerInstances(), MetricDatastoreWorker.class.getCanonicalName(), true), MetricDatastoreManager.class.getCanonicalName() + " " + uuid, null)
                        .compose(future -> Bootstrap.startEngine(new EventDatastoreManager(eventType + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getEventDatastoreWorkerInstances(), EventDatastoreWorker.class.getCanonicalName(), true), EventDatastoreManager.class.getCanonicalName() + " " + uuid, null))
                        .onComplete(result ->
                        {
                            if (result.succeeded())
                            {
                                items.add(uuid);

                                LOGGER.info(String.format("%s datastore registration event completed...",uuid));
                            }
                        });
            }
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        promise.complete();
    }
}

