package com.mindarray.ha;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.*;
import io.vertx.core.*;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import org.apache.commons.io.FileUtils;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;

public class ConfigHADatastoreManager extends AbstractVerticle
{
    private final Logger LOGGER;
    private final TreeSet<String> eventFiles = new TreeSet<>();
    private final Map<String, Map<String, Integer>> eventFileOffset = new TreeMap<>();
    private final Map<String, String> deployedRouters = new HashMap<>();
    private final Map<String, Long> eventFileTimer = new HashMap<>();
    private final String eventType;
    private final String clazz;
    private final int eventRouters;
    private String storeDirectory;
    private final boolean blocking;
    private final Set<String> datastoreUUIDs;

    public ConfigHADatastoreManager(String eventType, int eventRouters, String clazz, boolean blocking)
    {
        this.blocking = blocking;

        this.eventType = eventType;

        this.clazz = clazz;

        this.eventRouters = eventRouters >= 0 ? eventRouters : 1;

        this.datastoreUUIDs = new HashSet<>();

        this.LOGGER = new Logger(MetricHADatastoreManager.class, MOTADATA_DB, String.format("Metric Data Store Manager:(%s)", eventType));
    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var futures = new ArrayList<Future>();

        var maxRetentionTime = MotadataConfigUtil.getDataStoreRetentionTimerHours() * 60 * 60;

        storeDirectory = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.APP_EVENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.replace(eventType);

        for (var eventRouter = 0; eventRouter < this.eventRouters; eventRouter++)
        {
            var future = Promise.<Void>promise();

            var router = eventType + GlobalConstants.DOT_SEPARATOR + eventRouter;

            var createTopic = router.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_CREATE);

            futures.add(future.future());

            if (blocking)
            {
                vertx.deployVerticle(clazz, new DeploymentOptions().setConfig(new JsonObject().put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router)).put(EVENT_TYPE, router)).setWorker(true).setWorkerPoolSize(1).setWorkerPoolName("wp." + router), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.setPeriodic(60 * 1000, handler -> saveBookmarks(CURRENT_DIR + PATH_SEPARATOR + APP_EVENT_DIR + PATH_SEPARATOR + EventBusConstants.replace(router)));

                        vertx.eventBus().<String>localConsumer(createTopic, message -> eventFileTimer.put(message.body(),System.currentTimeMillis()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });
            }
            else
            {
                vertx.deployVerticle(clazz, new DeploymentOptions()
                        .setConfig(new JsonObject()
                                .put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router))
                                .put(EVENT_TYPE, router)), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.setPeriodic(60 * 1000, handler -> saveBookmarks(CURRENT_DIR + PATH_SEPARATOR + APP_EVENT_DIR + PATH_SEPARATOR + EventBusConstants.replace(router)));

                        vertx.eventBus().<String>localConsumer(createTopic, message -> eventFileTimer.put(message.body(),System.currentTimeMillis()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });
            }
        }

        CompositeFuture.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                var requestTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_REQUEST);

                var readTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_READ);

                var removeTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_REMOVE);

                var updateTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_UPDATE);

                vertx.setPeriodic(120 * 1000, handler -> clear(removeTopic,maxRetentionTime));

                vertx.setPeriodic(30 * 1000, handler -> update(updateTopic));

                for (var eventRouter = 0; eventRouter < this.eventRouters; eventRouter++)
                {
                    load(eventRouter,updateTopic);
                }

                vertx.eventBus().<JsonObject>localConsumer(requestTopic, message ->
                {
                    try
                    {
                        LOGGER.trace("datastore write request received...");

                        var totalBytes = 0L;

                        var futurePromise = Promise.<Void>promise();

                        var requests = new ArrayList<JsonObject>();

                        var datastoreUUID = message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID);

                        datastoreUUIDs.add(datastoreUUID);

                        var maxBufferBytes = message.body().getLong(DBConstants.DATASTORE_WRITER_MAX_BUFFER_BYTES);

                        for (var eventFile : eventFiles)
                        {
                            var timestamp = CommonUtil.getLong(eventFile.split(GlobalConstants.DASH_SEPARATOR)[0]);

                            if(totalBytes <= maxBufferBytes )
                            {
                                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + eventFile + ".dat");

                                if(file.exists() && file.length() > 0)
                                {
                                    var length = CommonUtil.getInteger(file.length());

                                    if (!eventFileOffset.containsKey(eventFile))
                                    {
                                        eventFileOffset.computeIfAbsent(eventFile,value->new HashMap<>());

                                        requests.add(new JsonObject()
                                                .put(EVENT_TYPE,readTopic + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                .put(EVENT_TOPIC, HA_TOPIC)
                                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,datastoreUUID)
                                                .put(EVENT_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                        for (var uuid : datastoreUUIDs)
                                        {
                                            eventFileOffset.get(eventFile).put(uuid, -1);
                                        }

                                        eventFileOffset.get(eventFile).put(datastoreUUID,length);

                                        totalBytes += length;
                                    }
                                    else if(!eventFileOffset.get(eventFile).containsKey(datastoreUUID)
                                            || (eventFileOffset.get(eventFile).containsKey(datastoreUUID) && eventFileOffset.get(eventFile).get(datastoreUUID) == -1))
                                    {
                                        requests.add(new JsonObject()
                                                .put(EVENT_TYPE,readTopic + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                .put(EVENT_TOPIC, HA_TOPIC)
                                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,datastoreUUID)
                                                .put(EVENT_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                        eventFileOffset.get(eventFile).put(datastoreUUID,length);

                                        totalBytes += length;
                                    }
                                }
                            }
                        }

                        if (!requests.isEmpty())
                        {
                            var requestFutures = new ArrayList<Future>();

                            LOGGER.debug(String.format("db store qualified %s files total bytes %s", requests.size(),totalBytes));

                            requests.forEach(item ->
                            {
                                var future = Promise.<Void>promise();

                                requestFutures.add(future.future());

                                Bootstrap.vertx().eventBus().<JsonObject>request(item.getString(EVENT_TYPE), item, handler -> future.complete());
                            });

                            CompositeFuture.join(requestFutures).onComplete(handler ->
                            {
                                LOGGER.debug(String.format("db store %s files received response", requests.size()));

                                requests.forEach(item->
                                {
                                    if(item.containsKey(EVENT_CONTEXT))
                                    {
                                        if(Bootstrap.bootstrapType().name().equalsIgnoreCase(GlobalConstants.BootstrapType.SLAVE.name()))
                                        {
                                            vertx.eventBus().send(EVENT_HA_MANAGER, item.put(EVENT_COPY_REQUIRED,false).put(EVENT_TYPE, EVENT_HA_SYNC_FLUSH));
                                        }
                                        else
                                        {
                                            vertx.eventBus().send(EVENT_PUBLICATION,item.put(EVENT_COPY_REQUIRED,false).put(EVENT_TYPE, EVENT_HA_SYNC_FLUSH));
                                        }

                                        LOGGER.debug(String.format("db store %s file send to datastore", item.getString(EVENT_FILE)));
                                    }
                                });

                                futurePromise.complete();
                            });
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }

                }).exceptionHandler(LOGGER::error);

                vertx.eventBus().<byte[]>localConsumer(eventType, message -> vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + (ByteUtil.readLongValue(message.body()) % eventRouters), message.body())).exceptionHandler(LOGGER::error);

                promise.complete();
            }
            else
            {
                promise.fail(result.cause());
            }
        });
    }

    private void clear(String removeTopic, int maxRetentionTime)
    {
        try
        {
            for (var iterator = eventFiles.iterator(); iterator.hasNext();)
            {
                var entry = iterator.next();

                var router = CommonUtil.getLong(entry.split(GlobalConstants.DASH_SEPARATOR)[0]) % eventRouters;

                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + router + GlobalConstants.PATH_SEPARATOR + entry + ".dat");

                if(file.exists() && eventFileOffset.containsKey(entry))
                {
                    var deleted = true;

                    for (Map.Entry<String, Integer> stringIntegerEntry : eventFileOffset.get(entry).entrySet())
                    {
                        deleted = deleted && stringIntegerEntry.getValue() == file.length();
                    }

                    if(deleted)
                    {
                        eventFileOffset.remove(entry);

                        eventFileTimer.remove(entry);

                        vertx.eventBus().send(removeTopic + GlobalConstants.DOT_SEPARATOR + router, entry);

                        iterator.remove();

                        LOGGER.debug(String.format("event db store %s file deleted due to read file all datastore and file point reach EOF", entry));

                    }
                    else if((System.currentTimeMillis() - eventFileTimer.get(entry))/1000 > maxRetentionTime)
                    {
                        eventFileOffset.remove(entry);

                        eventFileTimer.remove(entry);

                        vertx.eventBus().send(removeTopic + GlobalConstants.DOT_SEPARATOR + router, entry);

                        iterator.remove();

                        LOGGER.debug(String.format("event db store %s file deleted due to max retention time overlapped", entry));

                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void update(String updateTopic)
    {
        try
        {
            for (Map.Entry<String, Long> entry : eventFileTimer.entrySet())
            {
                if (!eventFileOffset.containsKey(entry.getKey()) && eventFileTimer.containsKey(entry.getKey()) && (System.currentTimeMillis() - eventFileTimer.get(entry.getKey()) >= 30000))
                {
                    var eventFile = entry.getKey().split(GlobalConstants.DOT_SEPARATOR_ESCAPE)[0];

                    var router = CommonUtil.getLong(entry.getKey().split(GlobalConstants.DASH_SEPARATOR)[0]) % eventRouters;

                    vertx.eventBus().send(updateTopic + GlobalConstants.DOT_SEPARATOR + router, eventFile);

                    eventFiles.add(eventFile);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load(int eventRouter, String updateTopic)
    {
        try
        {
            var files = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + eventRouter).listFiles();

            if (files != null)
            {
                var datastoreUUIDs = loadBookmark(storeDirectory + GlobalConstants.DASH_SEPARATOR + eventRouter);

                Arrays.stream(files).filter(file->file.getName().endsWith(".dat")).forEach(file->
                {
                    var eventFile = file.getName().split(GlobalConstants.DOT_SEPARATOR_ESCAPE)[0];

                    var router = CommonUtil.getLong(eventFile.split(GlobalConstants.DASH_SEPARATOR)[0]) % eventRouters;

                    vertx.eventBus().send(updateTopic + GlobalConstants.DOT_SEPARATOR + router, eventFile);

                    eventFileTimer.put(eventFile,System.currentTimeMillis());

                    eventFiles.add(eventFile);

                    var uuids = datastoreUUIDs.get(eventFile);

                    if (uuids != null)
                    {
                        for (var uuid : uuids)
                        {
                            Map<String, Integer> value = new HashMap<>();

                            value.put(uuid, 0);

                            eventFileOffset.put(eventFile, value);
                        }
                    }
                });
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void saveBookmarks(String path)
    {
        var bookmarks = new JsonObject();

        for (var eventFiles : eventFileOffset.entrySet())
        {

            bookmarks.put(eventFiles.getKey(), new JsonArray());

            for (var stringIntegerEntry : eventFiles.getValue().entrySet())
            {

                var dataStoreUUID = stringIntegerEntry.getKey();

                if (stringIntegerEntry.getValue() != -1)
                {
                    bookmarks.getJsonArray(eventFiles.getKey()).add(dataStoreUUID);
                }
            }
        }

        try
        {
            Bootstrap.vertx().fileSystem().writeFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "bookmarks", bookmarks.toBuffer());
        }
        catch (Exception exception)
        {
            LOGGER.fatal(exception);
        }
    }

    private Map<String, List<String>> loadBookmark(String path)
    {
        var datastoreUUIDs = new HashMap<String, List<String>>();

        var bookmark = new File(path + GlobalConstants.PATH_SEPARATOR + "bookmarks");

        if (bookmark.exists())
        {
            JsonObject value = null;

            try
            {
                value = new JsonObject(FileUtils.readFileToString(bookmark, StandardCharsets.UTF_8));
            }
            catch (Exception exception)
            {
                LOGGER.fatal(exception);
            }

            if (value != null)
            {
                for (var entry : value)
                {
                    datastoreUUIDs.put(entry.getKey(), new JsonArray(entry.getValue().toString()).getList());
                }
            }
        }

        return datastoreUUIDs;
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            var futures = new ArrayList<Future>();

            for (var key : deployedRouters.keySet())
            {
                var deploymentId = deployedRouters.get(key);

                var future = Promise.<Void>promise();

                saveBookmarks(CURRENT_DIR + PATH_SEPARATOR + APP_EVENT_DIR + PATH_SEPARATOR + EventBusConstants.replace(key));

                futures.add(future.future());

                vertx.undeploy(deploymentId, handler -> future.complete());
            }

            CompositeFuture.join(futures).onComplete(handler -> promise.complete());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            if (!promise.future().isComplete())
            {
                promise.fail(exception);
            }
        }
    }
