    public static List<long[]> getCorrectionTimestamps(JsonObject sloCycle, JsonObject correction)
    {
        var timestamps = new ArrayList<long[]>();

        try
        {
            if (sloCycle != null && !sloCycle.isEmpty())
            {
                if (correction != null && !correction.isEmpty() && correction.containsKey(CorrectionProfile.CORRECTION_PROFILE_CONTEXT))
                {
                    var context = correction.getJsonObject(CorrectionProfile.CORRECTION_PROFILE_CONTEXT);

                    var cycleStartTime = sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME);

                    var cycleEndTime = sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME);

                    switch (RecurringType.valueOfName(correction.getString(CorrectionProfile.CORRECTION_PROFILE_RECURRING_TYPE)))
                    {
                        case ONCE ->
                        {
                            if (context.containsKey(CorrectionProfile.CORRECTION_TIMES))
                            {
                                var correctionTimes = context.getJsonArray(CorrectionProfile.CORRECTION_TIMES);

                                // 1. Clip correction windows
                                for (var index = 0; index < correctionTimes.size(); index++)
                                {
                                    var correctionTime = correctionTimes.getJsonArray(index);

                                    var correctionStartTime = correctionTime.getLong(0);

                                    var correctionEndTime = correctionTime.getLong(1);

                                    if (correctionEndTime < correctionStartTime || correctionStartTime > cycleEndTime)
                                    {
                                        continue;
                                    }

                                    var start = Math.max(cycleStartTime, correctionStartTime);

                                    var end = Math.min(cycleEndTime, correctionEndTime);

                                    if (start < end)
                                    {
                                        timestamps.add(new long[]{start, end});
                                    }
                                }

                                return mergeOverlappingIntervals(timestamps);
                            }
                            else
                            {
                                LOGGER.warn("correction times are missing in correction profile context");
                            }
                        }
                        case MONITORING_HOURS ->
                        {
                            var item = BusinessHourConfigStore.getStore().getItem(context.getLong(CorrectionProfile.BUSINESS_HOUR_PROFILE));

                            if (item != null && item.containsKey(BusinessHour.BUSINESS_HOUR_CONTEXT))
                            {
                                var businessHours = item.getJsonObject(BusinessHour.BUSINESS_HOUR_CONTEXT);

                                var start = Instant.ofEpochSecond(cycleStartTime).atZone(ZoneId.systemDefault()).toLocalDate();

                                var end = Instant.ofEpochSecond(cycleEndTime).atZone(ZoneId.systemDefault()).toLocalDate();

                                for (var date = start; date.isBefore(end); date = date.plusDays(1))
                                {
                                    var hours = businessHours.getJsonArray(BusinessHour.DAYS.getString(date.getDayOfWeek().getValue()));

                                    if (hours != null && !hours.isEmpty())
                                    {
                                        for (var hour = 0 ; hour < 24; hour++)
                                        {
                                            if (!hours.contains(hour))
                                            {
                                                timestamps.add(new long[]{date.atTime(hour, 0).atZone(ZoneId.systemDefault()).toEpochSecond()
                                                        , date.atTime(hour + 1, 0).atZone(ZoneId.systemDefault()).toEpochSecond()});
                                            }
                                        }
                                    }
                                    else
                                    {
                                        LOGGER.warn("business hours are missing for day: " + date.getDayOfWeek());
                                    }
                                }

                                return mergeOverlappingIntervals(timestamps);
                            }
                            else
                            {
                                LOGGER.warn("business hour is not configured");
                            }
                        }
                    }
                }
                else
                {
                    LOGGER.warn("Either correction profile is null or empty or correction context is missing");
                }
            }
            else
            {
                LOGGER.warn("slo cycle is null or empty");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return timestamps;
    }

    private static List<long[]> mergeOverlappingIntervals(List<long[]> timestamps)
    {
        // 2. Sort by start time
        timestamps.sort(Comparator.comparingLong(timestamp -> timestamp[0]));

        // 3. Merge overlapping intervals
        var merged = new ArrayList<long[]>();

        long[] current = null;

        for (var timestamp : timestamps)
        {
            if (current == null)
            {
                current = timestamp;
            }
            else if (timestamp[0] <= current[1])
            {
                // Overlap → extend
                current[1] = Math.max(current[1], timestamp[1]);
            }
            else
            {
                merged.add(current);

                current = timestamp;
            }
        }

        if (current != null)
        {
            merged.add(current);
        }

        return merged;
    }
}

