package com.mindarray.util;

import com.google.common.base.Strings;
import com.mindarray.GlobalConstants;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;
import java.util.Map;

public class CipherUtil
{

    private static final Logger LOGGER = new Logger(CipherUtil.class, GlobalConstants.MOTADATA_UTIL, "Cipher Util");

    private Cipher encryption;

    private Cipher decryption;

    public CipherUtil()
    {
        try
        {
            encryption = Cipher.getInstance("AES");

            var key = new SecretKeySpec(new byte[]{'C', 'O', 'V', 'I', 'D', '-', '1', '9', 'M', 'O', 'T', 'A', 'D', 'A', 'T', 'A'}, "AES");

            encryption.init(Cipher.ENCRYPT_MODE, key);

            decryption = Cipher.getInstance("AES");

            decryption.init(Cipher.DECRYPT_MODE, key);

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected CipherUtil(Map<String, String> encryptionParameters)
    {
        try
        {
            encryption = Cipher.getInstance(encryptionParameters.get("transformation"));

            decryption = Cipher.getInstance(encryptionParameters.get("transformation"));

            SecretKeySpec keyspec = new SecretKeySpec(encryptionParameters.get("encryptionKey").getBytes(), encryptionParameters.get("algorithm"));

            if (!Strings.isNullOrEmpty(encryptionParameters.get("ivParameter")))
            {
                IvParameterSpec ivspec = new IvParameterSpec(encryptionParameters.get("ivParameter").getBytes());

                encryption.init(Cipher.ENCRYPT_MODE, keyspec, ivspec);

                decryption.init(Cipher.DECRYPT_MODE, keyspec, ivspec);
            }
            else
            {
                encryption.init(Cipher.ENCRYPT_MODE, keyspec);

                decryption.init(Cipher.ENCRYPT_MODE, keyspec);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    public String encrypt(String value)
    {

        String result = null;

        try
        {
            if (CommonUtil.isNotNullOrEmpty(value))
            {

                result = Base64.getEncoder().encodeToString(encryption.doFinal(value.getBytes()));

            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return result;
    }

    public String decrypt(String value)
    {

        var result = GlobalConstants.EMPTY_VALUE;

        try
        {
            if (CommonUtil.isNotNullOrEmpty(value))
            {
                result = new String(decryption.doFinal(Base64.getDecoder().decode(value.trim())));
            }

        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return result;

    }

    public byte[] encrypt(byte[] bytes)
    {

        try
        {
            if (bytes != null)
            {
                bytes = encryption.doFinal(bytes);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return bytes;
    }

    public byte[] decrypt(byte[] bytes)
    {
        try
        {
            if (bytes != null)
            {
                bytes = decryption.doFinal(bytes);
            }
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return bytes;

    }

}

