                            .put(MESSAGE,String.format(UNABLE_TO_CONNECT_MOTADATA_ENTITY,BootstrapType.OBSERVER.name(),MotadataConfigUtil.getRemoteEventObserverSender(),EMPTY_VALUE).replaceAll(DASH_SEPARATOR,EMPTY_VALUE)));

                    LOGGER.warn(String.format("Observer is down , address : %s ", MotadataConfigUtil.getRemoteEventObserverSender() + ":" + MotadataConfigUtil.getMotadataObserverEventSenderPort()));
                }
            }
        });
    }

