package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.HashSet;
import java.util.Set;

import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID;
import static com.mindarray.eventbus.EventBusConstants.*;

public class DatastoreManager extends AbstractVerticle
{
    private final Set<String> items = new HashSet<>(); //items by uuid store last read file
    private static final Logger LOGGER = new Logger(DatastoreManager.class, GlobalConstants.MOTADATA_DATASTORE, "Datastore Manager");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            var metricType = EventBusConstants.EVENT_DATASTORE_WRITE + GlobalConstants.DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.METRIC.getName();

            var eventType = EventBusConstants.EVENT_DATASTORE_WRITE + GlobalConstants.DOT_SEPARATOR + DatastoreConstants.DatastoreCategory.EVENT.getName();

            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_DATASTORE_REGISTER, message -> {
                var uuid = message.body().getString(REMOTE_EVENT_PROCESSOR_UUID);

                if(!items.contains(uuid))
                {
                    LOGGER.info(String.format("%s datastore registration event received...",uuid));

                    Bootstrap.startEngine(new MetricDatastoreManager(metricType + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getMetricDatastoreWorkerInstances(), MetricDatastoreWorker.class.getCanonicalName(), true), MetricDatastoreManager.class.getCanonicalName() + " " + uuid, null)
                            .compose(future -> Bootstrap.startEngine(new EventDatastoreManager(eventType + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getEventDatastoreWorkerInstances(), EventDatastoreWorker.class.getCanonicalName(), true), EventDatastoreManager.class.getCanonicalName() + " " + uuid, null))
                            .onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    items.add(uuid);

                                    LOGGER.info(String.format("%s datastore registration event completed...",uuid));
                                }
                                else
                                {
                                    LOGGER.error(result.cause());
                                }
                            });
                }

            }).exceptionHandler(LOGGER::error);

            if(MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(GlobalConstants.InstallationMode.PRIMARY.name()))
            {
                var secondaryApp = RemoteEventProcessorConfigStore.getStore().flatItemsByValue(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE, GlobalConstants.BootstrapType.APP.name(),RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,GlobalConstants.InstallationMode.SECONDARY.name());

                vertx.eventBus().<byte[]>localConsumer(metricType, message ->
                        items.forEach(entry-> vertx.eventBus().send(metricType + GlobalConstants.DOT_SEPARATOR + entry,message.body()))).exceptionHandler(LOGGER::error);

                vertx.eventBus().<byte[]>localConsumer(eventType, message ->
                        items.forEach(entry-> vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + entry,message.body()))).exceptionHandler(LOGGER::error);

                vertx.eventBus().<JsonObject>localConsumer(EVENT_DATASTORE_SYNC_WRITE, message ->
                {
                    //TODO
                    var event = message.body();

                    vertx.eventBus().send(EventBusConstants.EVENT_DATASTORE_WRITE + GlobalConstants.DOT_SEPARATOR
                            + event.getInteger(DatastoreConstants.DATASTORE_CATEGORY)
                            + GlobalConstants.DOT_SEPARATOR
                            + event.getString(REMOTE_EVENT_PROCESSOR_UUID),message.body());

                }).exceptionHandler(LOGGER::error);

                var eventRequestTimer = vertx.setPeriodic(MotadataConfigUtil.getDatastoreRequestTimer(),handler ->
                {
                    if (!secondaryApp.isEmpty())
                    {
                        var processorUUID = secondaryApp.getJsonObject(0).getString(REMOTE_EVENT_PROCESSOR_UUID);

                        items.forEach(uuid ->
                        {
                            var context = new JsonObject().put(REMOTE_EVENT_PROCESSOR_UUID,processorUUID)
                                    .put(EVENT_TOPIC,REMOTE_EVENT_PROCESSOR_TOPIC)
                                    .put(EVENT_TYPE,EVENT_DATASTORE_SYNC_READ).put(DatastoreConstants.DATASTORE_UUID,uuid)
                                    .put(DatastoreConstants.DATASTORE_CATEGORY,DatastoreConstants.DatastoreCategory.EVENT.getName());

                            vertx.eventBus().send(EVENT_PUBLICATION,context);

                            LOGGER.info(String.format("requesting for datastore event category to %s ",uuid));
                        });
                    }
                });

                var metricRequestTimer = vertx.setPeriodic(MotadataConfigUtil.getDatastoreRequestTimer(),handler ->
                {
                    if (!secondaryApp.isEmpty())
                    {
                        var processorUUID = secondaryApp.getJsonObject(0).getString(REMOTE_EVENT_PROCESSOR_UUID);

                        items.forEach(uuid ->
                        {
                            var context = new JsonObject().put(REMOTE_EVENT_PROCESSOR_UUID,processorUUID)
                                    .put(EVENT_TOPIC,REMOTE_EVENT_PROCESSOR_TOPIC)
                                    .put(EVENT_TYPE,EVENT_DATASTORE_SYNC_READ).put(DatastoreConstants.DATASTORE_UUID,uuid)
                                    .put(DatastoreConstants.DATASTORE_CATEGORY,DatastoreConstants.DatastoreCategory.METRIC.getName());

                            vertx.eventBus().send(EVENT_PUBLICATION,context);

                            LOGGER.info(String.format("requesting for datastore metric category to %s ",uuid));
                        });
                    }
                });

                // need to think of ack because for metric and event it has to be separate.

                vertx.eventBus().localConsumer(EVENT_DATASTORE_METRIC_SYNC_ACKNOWLEDGEMENT,timer -> vertx.cancelTimer(metricRequestTimer));

                vertx.eventBus().localConsumer(EVENT_DATASTORE_EVENT_SYNC_ACKNOWLEDGEMENT,timer -> vertx.cancelTimer(eventRequestTimer));

            }
            else if(MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(GlobalConstants.InstallationMode.SECONDARY.name()))
            {
                vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_DATASTORE_SYNC_READ, message ->
                {
                    var context = message.body();

                    var datastoreUUID = context.getString(DatastoreConstants.DATASTORE_UUID);

                    if (items.contains(datastoreUUID))
                    {
                        context.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, datastoreUUID).put(EVENT_TYPE, EVENT_DATASTORE_SYNC_WRITE);

                        vertx.eventBus().send(EVENT_DATASTORE_REQUEST + GlobalConstants.DOT_SEPARATOR
                                + context.getInteger(DatastoreConstants.DATASTORE_CATEGORY) + GlobalConstants.DOT_SEPARATOR
                                + context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID), context.put(EVENT_COPY_REQUIRED, false));
                    }
                    else
                    {
                        LOGGER.info(String.format("datastore item does not exist , uuid : %s ",datastoreUUID));
                    }
                });
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        promise.complete();
    }
}

