import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.*;
import static com.mindarray.eventbus.EventBusConstants.ChangeNotificationType;
import static com.mindarray.eventbus.EventBusConstants.EVENT_POLICY_CLEAR;

public class Integration extends AbstractAPI
{

    public static final String INTEGRATION_TYPE = "integration.type";

    public static final String INTEGRATION_AUTH_TOKEN = "integration.auth.token";

    public static final String INTEGRATION_SERVER_TOKEN_URL = "integration.server.token.url";

    public static final String INTEGRATION_SERVER_TICKET_CREATION_API = "integration.server.ticket.creation.api";

    public static final String INTEGRATION_SERVER_TICKET_UPDATION_API = "integration.server.ticket.updation.api";

    public static final String INTEGRATION_SERVER_URL = "integration.server.url";

    public static final String INTEGRATION_SERVER_URL_TIMEOUT_SECONDS = "integration.server.url.timeout.sec";

    public static final String INTEGRATION_FAILED_NOTIFICATION_EMAIL_RECIPIENT = "integration.failed.notification.email.recipient";

    public static final String INTEGRATION_AUTO_CLOSE_TICKET_STATUS = "integration.auto.close.ticket.status";

    public static final String INTEGRATION_TICKET_RESOLUTION_STATE = "integration.ticket.resolution.state";

    private static final Logger LOGGER = new Logger(Integration.class, MOTADATA_API, "Integration API");

    public Integration()
    {
        super("integrations", IntegrationConfigStore.getStore(), new Logger(Integration.class, MOTADATA_API, "Integration API"));

    }

    @Override
    public void init(Router router)
    {
        super.init(router, new HashSet<>()
        {{
            add(REQUEST_GET);
        }});

        router.get("/" + endpoint).handler(this::getAll);

        router.get("/" + endpoint + "/clear-alert").handler(this::integrationManualClear);

    }

    private void integrationManualClear(RoutingContext routingContext) {

        var id = routingContext.request().getParam(ID);

        var name = routingContext.request().getParam("name");

        var integrationType = IntegrationCacheStore.getStore().getIntegration(name + HASH_SEPARATOR + id);

        if(IntegrationType.SERVICEOPS.getName().equalsIgnoreCase(integrationType))
        {
            if(STATUS_RESOLVED.equalsIgnoreCase(routingContext.request().getParam(STATUS)) || STATUS_CLOSED.equalsIgnoreCase(routingContext.request().getParam(STATUS)))
            {
                //key: integrationType + policy.id + object.id + metric + instance
                var policyKey = IntegrationCacheStore.getStore().getPolicyKey(name + HASH_SEPARATOR + id);

                if(!policyKey.equalsIgnoreCase(EMPTY_VALUE))
                {
                    var keys = policyKey.split(SEPARATOR_WITH_ESCAPE);

                    LOGGER.info(String.format("Manual clear from integration: %s, ack id: %s, policy key: %s",integrationType,id,policyKey));

                    IntegrationCacheStore.getStore().remove(IntegrationType.SERVICEOPS.getName(),policyKey);

                    if(keys.length == 5) //scaler metric policy
                    {
                        Bootstrap.vertx().eventBus().publish(EVENT_POLICY_CLEAR, new JsonObject().put("action.type","clear").put(PolicyEngineConstants.POLICY_ID,CommonUtil.getLong(keys[1])).put("alert.type",0).put(ENTITY_ID,CommonUtil.getLong(keys[2])).put(METRIC,keys[4]));
                    }
                    else //instance metric policy
                    {
                        Bootstrap.vertx().eventBus().publish(EVENT_POLICY_CLEAR, new JsonObject().put("action.type","clear").put(PolicyEngineConstants.POLICY_ID,CommonUtil.getLong(keys[1])).put("alert.type",0).put(ENTITY_ID,CommonUtil.getLong(keys[2])).put(METRIC,keys[4]).put(INSTANCE,keys[5]));
                    }

                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED));
                }
                else
                {
                    LOGGER.trace(String.format("Integration: %s, Ack:%s does not have track in AIOps.",name,integrationType));
                }
            }
        }
    }

    @Override
    protected void getAll(RoutingContext routingContext)
    {
        try
        {
            var requestParameters = JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER)));

            if (requestParameters.containsKey(INTEGRATION_TYPE))
            {
                var item = IntegrationConfigStore.getStore().getItemByValue(INTEGRATION_TYPE, requestParameters.getString(INTEGRATION_TYPE));

                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(ID, item.getLong(ID)).put(GlobalConstants.RESULT, item));
            }
            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR).put(GlobalConstants.STATUS, STATUS_FAIL).put(MESSAGE, ErrorMessageConstants.INTERNAL_ERROR));
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    @Override
    protected Future<JsonObject> afterUpdate(JsonObject entity, RoutingContext routingContext)
    {
        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, routingContext.body().asJsonObject().put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_INTEGRATION.name()));

        return super.afterUpdate(entity, routingContext);
    }


    public enum IntegrationType
    {
        SERVICEOPS("ServiceOps");

        private static final Map<String, IntegrationType> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(IntegrationType::getName, e -> e)));
        private final String name;

        IntegrationType(String name)
        {
            this.name = name;
        }

        public static IntegrationType valueOfName(String name)
        {
            return VALUES.get(name);
        }

        public String getName()
        {
            return name;
        }
    }
}

