package com.mindarray;

import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.datastore.DatastoreManager;
import com.mindarray.db.ConfigDBInitializer;
import com.mindarray.db.DBConstants;
import com.mindarray.db.DBServiceProvider;
import com.mindarray.eventbus.*;
import com.mindarray.ha.Observer;
import com.mindarray.util.*;
import io.vertx.core.Future;
import io.vertx.core.Promise;

import java.util.ArrayList;

import static com.mindarray.Bootstrap.*;
import static com.mindarray.GlobalConstants.DOT_SEPARATOR;
import static com.mindarray.GlobalConstants.INSTALLATION_DATE;
import static com.mindarray.eventbus.EventBusConstants.EVENT_APP;
import static com.mindarray.eventbus.EventBusConstants.EVENT_HA_OBSERVER;

public class BootstrapFailover
{
    private static final Logger LOGGER = new Logger(BootstrapFailover.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Failover");

    public void start()
    {
        try
        {
            if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverSender(), MotadataConfigUtil.getMotadataObserverEventSenderPort(), 3))
            {
                DatastoreConstants.loadConfigs();

                Bootstrap.logSystemConfig();

                ProcessUtil.setProcessors();

                EventBusConstants.setRemoteEventProcessorRegistrationId();

                startEngine(new DBServiceProvider(), DBServiceProvider.class.getSimpleName(), null)

                        .compose(future -> startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getEventObserverProtocol(), MotadataConfigUtil.getMotadataObserverEventReceiverPort(), null, MotadataConfigUtil.getRemoteEventObserverReceiver(), EventBusConstants.SocketMode.PUSH)), RemoteEventSender.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventReceiverPort(), null,EVENT_HA_OBSERVER))
                        .compose(future -> startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getEventObserverProtocol(), MotadataConfigUtil.getMotadataObserverEventSenderPort(), EVENT_APP + DOT_SEPARATOR + MotadataConfigUtil.getMotadataObserverEventSenderPort(), MotadataConfigUtil.getRemoteEventObserverSender(), EventBusConstants.SocketMode.SUB)), RemoteEventReceiver.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSenderPort(), null,EVENT_APP + DOT_SEPARATOR + MotadataConfigUtil.getMotadataObserverEventSenderPort()))

                        .compose(future -> startEngine(new DatastoreManager(), DatastoreManager.class.getSimpleName(), null))
                        .compose(future -> startEngine(new Observer(), Observer.class.getSimpleName(), null))
                        .onComplete(promiseResult ->
                        {
                            if (promiseResult.succeeded())
                            {
                                LOGGER.info("Starting syncing config events ......");

                                sync().onComplete(syncHandler ->
                                {
                                    if (syncHandler.succeeded())
                                    {
                                        LOGGER.info("initializing config db");

                                        var asyncFuture = Promise.<Boolean>promise();

                                        Bootstrap.configDBService().getOne(DBConstants.TBL_SYSTEM,
                                                result ->
                                                {
                                                    if (result.succeeded() && result.result().containsKey(INSTALLATION_DATE))
                                                    {
                                                        asyncFuture.complete(false);
                                                    }
                                                    else
                                                    {
                                                        asyncFuture.complete(true);
                                                    }
                                                });

                                        asyncFuture.future().onComplete(asyncResponse ->
                                                LicenseUtil.init(asyncResponse.result()).onComplete(asyncPromiseResult ->
                                                {
                                                    if (asyncPromiseResult.succeeded())
                                                    {
                                                        try
                                                        {
                                                            LOGGER.info("license verified successfully...");

                                                            LicenseUtil.load(asyncPromiseResult.result());

                                                            ConfigDBInitializer.init().onComplete(futureResult ->
                                                            {
                                                                if (futureResult.succeeded())
                                                                {
                                                                    var asyncPromise = Promise.promise();

                                                                    // init all stores...
                                                                    Bootstrap.initStores().onComplete(response ->
                                                                    {
                                                                        if (response.succeeded())
                                                                        {
                                                                            LOGGER.info("all config/cache stores loaded successfully...");

                                                                            LOGGER.info(String.format("executing patches : %s ....",bootstrapType()));

                                                                            Bootstrap.patch(asyncResponse.result()).onComplete(future ->
                                                                            {
                                                                                if (future.succeeded())
                                                                                {
                                                                                    LOGGER.info("patches executed successfully...");

                                                                                    asyncPromise.complete();
                                                                                }
                                                                                else
                                                                                {
                                                                                    Bootstrap.stop(future.cause());

                                                                                    asyncPromise.fail(future.cause());
                                                                                }
                                                                            });
                                                                        }
                                                                        else
                                                                        {
                                                                            asyncPromise.fail(response.cause());
                                                                        }
                                                                    });

                                                                    asyncPromise.future().onComplete(handler ->
                                                                    {
                                                                        if (handler.succeeded())
                                                                        {
                                                                            var futures = new ArrayList<Future<Object>>();

                                                                    var senderPort = CommonUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol());

                                                                    for (var index = 0; index < MotadataConfigUtil.getEventSenders(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()); index++)
                                                                            {
                                                                                var promise = Promise.promise();

                                                                                futures.add(promise.future());

                                                                        Bootstrap.startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol(), senderPort + index, null, MotadataConfigUtil.getRemoteEventSender(), EventBusConstants.SocketMode.PUSH)), RemoteEventSender.class.getSimpleName() + " " + (senderPort + index), null,EVENT_APP + DOT_SEPARATOR + (senderPort + index))
                                                                                        .onComplete(asyncResult ->
                                                                                        {
                                                                                            if (asyncResult.succeeded())
                                                                                            {
                                                                                                promise.complete();
                                                                                            }
                                                                                            else
                                                                                            {
                                                                                                promise.fail(asyncResult.cause());
                                                                                            }
                                                                                        });
                                                                            }

                                                                            Future.join(futures).onComplete(asyncResult ->
                                                                            {
                                                                                if (asyncResult.succeeded())
                                                                                {
                                                                                    var asyncResults = new ArrayList<Future<Object>>();

                                                                            var receiverPort = CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol());

                                                                            for (var index = 0; index < MotadataConfigUtil.getEventReceivers(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol()); index++)
                                                                                    {
                                                                                        var promise = Promise.promise();

                                                                                        asyncResults.add(promise.future());

                                                                                Bootstrap.startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol(), receiverPort + index, EVENT_APP + DOT_SEPARATOR + (receiverPort + index), CommonUtil.getRemoteEventReceiver(), EventBusConstants.SocketMode.SUB)), RemoteEventReceiver.class.getSimpleName() + " " + (receiverPort + index), null,EVENT_APP + DOT_SEPARATOR + (receiverPort + index)).onComplete(voidAsyncResult ->
                                                                                        {
                                                                                            if (voidAsyncResult.succeeded())
                                                                                            {
                                                                                                promise.complete();
                                                                                            }
                                                                                            else
                                                                                            {
                                                                                                promise.fail(voidAsyncResult.cause());
                                                                                            }
                                                                                        });
                                                                                    }

                                                                                    Future.join(asyncResults).onComplete(asyncFutureResult -> startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                                                                                            .compose(future -> startEngine(new LocalEventChangeNotificationHandler(), LocalEventChangeNotificationHandler.class.getSimpleName(), null))
                                                                                            .compose(future -> Bootstrap.startWorkerEngine(new JVMStatUtil(), JVMStatUtil.class.getSimpleName(), null))
                                                                                            .compose(future -> Bootstrap.startWorkerEngine(new DiagnosticUtil(), DiagnosticUtil.class.getSimpleName(), null))
                                                                                            .onComplete(result ->
                                                                                            {
                                                                                                try
                                                                                                {
                                                                                                    if (result.succeeded())
                                                                                                    {
                                                                                                        EventBusConstants.register(new CipherUtil());

                                                                                                        LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                                                                                                        LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.getInstallationMode()));
                                                                                                    }
                                                                                                    else
                                                                                                    {
                                                                                                        LOGGER.error(result.cause());

                                                                                                        stop(result.cause());
                                                                                                    }
                                                                                                }
                                                                                                catch (Exception exception)
                                                                                                {
                                                                                                    LOGGER.error(exception);
                                                                                                }
                                                                                            }));


                                                                                }
                                                                                else
                                                                                {
                                                                                    LOGGER.error(asyncResult.cause());

                                                                                    System.exit(0);
                                                                                }
                                                                            });
                                                                        }
                                                                        else
                                                                        {
                                                                            Bootstrap.stop(handler.cause());
                                                                        }
                                                                    });
                                                                }
                                                                else
                                                                {
                                                                    Bootstrap.stop(futureResult.cause());
                                                                }
                                                            });
                                                        }
                                                        catch (Exception exception)
                                                        {
                                                            stop(exception);
                                                        }
                                                    }
                                                    else
                                                    {
                                                        stop(asyncPromiseResult.cause());
                                                    }
                                                }));
                                    }
                                    else
                                    {
                                        LOGGER.error(syncHandler.cause());

                                        Bootstrap.stop(syncHandler.cause());
                                    }
                                });
                            }
                            else
                            {
                                Bootstrap.stop(promiseResult.cause());
                            }
                        });
            }
            else
            {
                stop("motadata observer server is not reachable...");

                System.exit(0);
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
