package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.Metric;
import com.mindarray.db.DBConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.CipherUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.GlobalConstants.GROUP_SEPARATOR;

public class TagCacheStore extends AbstractCacheStore
{
    private static final Logger LOGGER = new Logger(TagCacheStore.class, GlobalConstants.MOTADATA_STORE, "Tag Cache Store");

    private static final TagCacheStore STORE = new TagCacheStore();

    private final Map<String, JsonArray> instancesByTag = new ConcurrentHashMap<>(); //key ->  objectId + instanceType + tag , value-> [objectId ### instance.name]

    private final Map<String, JsonArray> instanceByKeyTags = new ConcurrentHashMap<>(); //key-> objectId + tag, value -> [tags]

    private final Map<String, JsonObject> instancesByType = new ConcurrentHashMap<>(); // key ->  objectId + instanceType, value-> { tag : [objectId ### instance.name] }


    private TagCacheStore()
    {
    }

    public static TagCacheStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        if (GlobalConstants.BootstrapType.COLLECTOR == Bootstrap.bootstrapType())
        {
            promise.fail("remote event processor can not init store... it must be master or default boot sequence...");
        }

        else
        {
            try
            {
                var items = MetricConfigStore.getStore().getItems();

                for (var index = 0; index < items.size(); index++)
                {
                    var item = items.getJsonObject(index);

                    var context = item.getJsonObject(Metric.METRIC_CONTEXT);

                    if (context.containsKey(NMSConstants.OBJECTS))
                    {
                        var objectId = ObjectConfigStore.getStore().getObjectId(MetricConfigStore.getStore().getMetricObjectId(item.getLong(ID)));

                        var objects = context.getJsonArray(NMSConstants.OBJECTS);

                        var instanceKey = objectId + KEY_SEPARATOR + NMSConstants.INSTANCE_TYPES.getOrDefault(item.getString(Metric.METRIC_PLUGIN), objects.getJsonObject(0).getString(AIOpsObject.OBJECT_TYPE)); //key: object.id + instance.type

                        var instancesByTag = new JsonObject();

                        for (var i = 0; i < objects.size(); i++)
                        {
                            var object = objects.getJsonObject(i);

                            if (object.containsKey(INSTANCE_USER_TAGS))
                            {
                                var instanceName = item.getString(Metric.METRIC_PLUGIN).equalsIgnoreCase(NMSConstants.MetricPlugin.SNMP_INTERFACE.getName()) ? object.getString(NMSConstants.INTERFACE) : object.getString(AIOpsObject.OBJECT_NAME);

                                object.getJsonArray(INSTANCE_USER_TAGS).forEach(tag ->
                                {

                                    if (CommonUtil.getString(tag).contains(COLON_SEPARATOR))
                                    {
                                        var keyGroupTag = objectId + KEY_SEPARATOR + CommonUtil.getString(tag).split(COLON_SEPARATOR)[0];

                                        instanceByKeyTags.computeIfAbsent(keyGroupTag, value -> new JsonArray());

                                        if (!instanceByKeyTags.get(keyGroupTag).contains(CommonUtil.getString(tag)))
                                        {
                                            instanceByKeyTags.get(keyGroupTag).add(CommonUtil.getString(tag));
                                        }
                                    }

                                    var key = instanceKey + KEY_SEPARATOR + CommonUtil.getString(tag); //key: objectId # instanceType # tag

                                    this.instancesByTag.computeIfAbsent(key, value -> new JsonArray());

                                    this.instancesByTag.get(key).add(objectId + GROUP_SEPARATOR + instanceName);

                                    instancesByTag.put(CommonUtil.getString(tag), instancesByTag.getJsonArray(CommonUtil.getString(tag), new JsonArray()).add(objectId + GROUP_SEPARATOR + instanceName));
                                });
                            }
                        }

                        if (!instancesByTag.isEmpty())
                        {
                            this.instancesByType.put(instanceKey, instancesByTag);
                        }
                    }
                }

                promise.complete();
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }

        return promise.future();
    }

    public void deleteTags(long objectId)
    {
        instanceByKeyTags.entrySet().removeIf(entry -> entry.getKey().split(KEY_SEPARATOR)[0].equalsIgnoreCase(CommonUtil.getString(objectId)));

        instancesByTag.entrySet().removeIf(entry -> entry.getKey().split(KEY_SEPARATOR)[0].equalsIgnoreCase(CommonUtil.getString(objectId)));

        instancesByType.entrySet().removeIf(entry -> entry.getKey().split(KEY_SEPARATOR)[0].equalsIgnoreCase(CommonUtil.getString(objectId)));
    }
    /*
     * method will update cache: instanceByTag, instanceByType and instanceByKeyGroup
     *
     * instanceByTag : key ->  objectId + instanceType + tag
     *                 value-> [objectId ### instance.name]
     *
     * instanceByType : key ->  objectId + instanceType
     *                  value-> { tag : [objectId ### instance.name] }
     *
     * instanceByGroup : key -> objectId + KeyTag
     *                   value -> [Tags]
     * ex. instanceType(esxi.vm, interface, access.point)
     * */
    public void updateInstanceTags(long id, JsonArray objects, String instanceType)
    {
        try
        {
            var objectId = ObjectConfigStore.getStore().getObjectId(MetricConfigStore.getStore().getMetricObjectId(id));

            var instancesByTag = new JsonObject();

            var instancesByInstanceKey = new HashMap<String, JsonArray>();

            var tagsByKey = new HashMap<String, JsonArray>();

            var instanceKey = objectId + KEY_SEPARATOR + instanceType;

            for (var index = 0; index < objects.size(); index++)
            {
                var object = objects.getJsonObject(index);

                if (object.containsKey(INSTANCE_USER_TAGS))
                {
                    var instanceName = instanceType.equalsIgnoreCase(NMSConstants.INTERFACE) ? object.getString(NMSConstants.INTERFACE) : object.getString(AIOpsObject.OBJECT_NAME);

                    object.getJsonArray(INSTANCE_USER_TAGS).forEach(tag ->
                    {

                        if (CommonUtil.getString(tag).contains(COLON_SEPARATOR))
                        {
                            var keyTag = objectId + KEY_SEPARATOR + CommonUtil.getString(tag).split(COLON_SEPARATOR)[0];

                            tagsByKey.computeIfAbsent(keyTag, value -> new JsonArray());

                            if (!tagsByKey.get(keyTag).contains(CommonUtil.getString(tag)))
                            {
                                tagsByKey.get(keyTag).add(CommonUtil.getString(tag));
                            }
                        }

                        var key = instanceKey + KEY_SEPARATOR + CommonUtil.getString(tag); //key: objectId # instanceType # tag

                        instancesByInstanceKey.computeIfAbsent(key, value -> new JsonArray());

                        instancesByInstanceKey.get(key).add(objectId + GROUP_SEPARATOR + instanceName);

                        instancesByTag.put(CommonUtil.getString(tag), instancesByTag.getJsonArray(CommonUtil.getString(tag), new JsonArray()).add(objectId + GROUP_SEPARATOR + instanceName));
                    });
                }
            }

            if (!instancesByTag.isEmpty())
            {
                this.instancesByType.put(instanceKey, instancesByTag);

                this.instancesByTag.entrySet().removeIf(entry -> entry.getKey().startsWith(objectId + KEY_SEPARATOR + instanceType));

                this.instancesByTag.putAll(instancesByInstanceKey);

                this.instanceByKeyTags.entrySet().removeIf(entry -> entry.getKey().startsWith(CommonUtil.getString(objectId)));

                this.instanceByKeyTags.putAll(tagsByKey);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    public Map<String, JsonArray> getTagsByInstances(JsonArray ids, String instanceType)
    {
        var items = new HashMap<String, JsonArray>();

        for (var id : ids)
        {
            if (instancesByType.containsKey(id + KEY_SEPARATOR + instanceType))
            {
                for (var entry : instancesByType.get(id + KEY_SEPARATOR + instanceType).getMap().entrySet())
                {
                    if (items.containsKey(entry.getKey()))
                    {
                        items.get(entry.getKey()).addAll(((JsonArray) entry.getValue()));
                    }
                    else
                    {
                        items.put(entry.getKey(), ((JsonArray) entry.getValue()));
                    }
                }
            }
        }

        return items;
    }

    public JsonArray getInstanceIdsByTags(JsonArray tags)
    {
        return new JsonArray(instancesByTag.keySet().stream()
                .filter(key -> tags.contains(key.split(KEY_SEPARATOR)[2]))
                .map(key -> key.split(KEY_SEPARATOR)[0])
                .distinct().collect(Collectors.toList()));
    }

    public JsonArray getInstanceTags()
    {
        var result = new JsonArray();

        for (var instance : instancesByType.entrySet())
        {
            instance.getValue().getMap().forEach((key, value) -> result.add(key));
        }

        return result;
    }

    public Map<String, JsonArray> getTagsByGroupInstances(JsonArray ids, String instanceType, String tagKey)
    {
        var items = new HashMap<String, JsonArray>();

        for (var id : ids)
        {
            if (instanceByKeyTags.containsKey(id + KEY_SEPARATOR + tagKey))
            {
                for (var entry : instanceByKeyTags.get(id + KEY_SEPARATOR + tagKey))
                {
                    if (instancesByTag.containsKey(id + KEY_SEPARATOR + instanceType + KEY_SEPARATOR + CommonUtil.getString(entry)))
                    {
                        if (items.containsKey(CommonUtil.getString(entry)))
                        {
                            items.get(CommonUtil.getString(entry)).addAll(instancesByTag.get(id + KEY_SEPARATOR + instanceType + KEY_SEPARATOR + entry));
                        }
                        else
                        {
                            items.put(CommonUtil.getString(entry), instancesByTag.get(id + KEY_SEPARATOR + instanceType + KEY_SEPARATOR + entry));
                        }
                    }
                }
            }
        }

        return items;
    }

}

