import com.mindarray.db.DBConstants;
import com.mindarray.db.DBServiceProvider;
import com.mindarray.eventbus.*;
import com.mindarray.ha.HAConstants;
import com.mindarray.ha.Observer;
import com.mindarray.log.LogParser;
import com.mindarray.log.UDPLogCollector;
import com.mindarray.nms.*;
import com.mindarray.plugin.PluginEngine;
import com.mindarray.plugin.PluginEngineResponseProcessor;
import com.mindarray.util.*;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.Bootstrap.*;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.ha.HAConstants.HA_SYNC_OPERATION;

public class BootstrapSecondary
{
    private static final Logger LOGGER = new Logger(BootstrapSecondary.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Secondary");

    public void start()
    {
        try
        {
            if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST) || PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverSender(), MotadataConfigUtil.getMotadataObserverEventSenderPort(), 5))
            {
                DatastoreConstants.loadConfigs();

                Bootstrap.logSystemConfig();

                ProcessUtil.setProcessors();

                EventBusConstants.setRemoteEventProcessorRegistrationId();

                startEngine(new DBServiceProvider(), DBServiceProvider.class.getSimpleName(), null)

                        .compose(future -> startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getEventObserverProtocol(), MotadataConfigUtil.getMotadataObserverEventReceiverPort(), null, MotadataConfigUtil.getRemoteEventObserverReceiver(), SocketMode.PUSH)), RemoteEventSender.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventReceiverPort(), null,EVENT_HA_OBSERVER))
                        .compose(future -> startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getEventObserverProtocol(), MotadataConfigUtil.getMotadataObserverEventSenderPort(), EVENT_APP + DOT_SEPARATOR + MotadataConfigUtil.getMotadataObserverEventSenderPort(), MotadataConfigUtil.getRemoteEventObserverSender(), SocketMode.SUB)), RemoteEventReceiver.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSenderPort(), null,EVENT_APP + DOT_SEPARATOR + MotadataConfigUtil.getMotadataObserverEventSenderPort()))

                        .compose(future -> startEngine(new DatastoreManager(), DatastoreManager.class.getSimpleName(), null))
                        .compose(future -> startEngine(new Observer(), Observer.class.getSimpleName(), null))
                        .onComplete(promiseResult ->
                        {
                            if (promiseResult.succeeded())
                            {
                                LOGGER.info("Starting syncing config events ......");

                                sync().onComplete(handler ->
                                {
                                    if (handler.succeeded())
                                    {
                                        LOGGER.info("initializing config db");

                                        var asyncFuture = Promise.<Boolean>promise();

                                        Bootstrap.configDBService().getOne(DBConstants.TBL_SYSTEM,
                                                result ->
                                                {
                                                    if (result.succeeded() && result.result().containsKey(INSTALLATION_DATE))
                                                    {
                                                        asyncFuture.complete(false);
                                                    }
                                                    else
                                                    {
                                                        asyncFuture.complete(true);
                                                    }
                                                });

                                        asyncFuture.future().onComplete(asyncResponse ->
                                                LicenseUtil.init(asyncResponse.result()).onComplete(asyncPromiseResult ->
                                                {
                                                    if (asyncPromiseResult.succeeded())
                                                    {
                                                        try
                                                        {
                                                            LOGGER.info("license verified successfully...");

                                                            LicenseUtil.load(asyncPromiseResult.result());

                                                            ConfigDBInitializer.init().onComplete(futureResult ->
                                                            {
                                                                if (futureResult.succeeded())
                                                                {
                                                                    LOGGER.info("loading all config/cache store");

                                                                    var asyncPromise = Promise.promise();

                                                                    // init all stores...
                                                                    Bootstrap.initStores().onComplete(response ->
                                                                    {
                                                                        if (response.succeeded())
                                                                        {
                                                                            LOGGER.info("all config/cache stores loaded successfully...");

                                                                            LOGGER.info(String.format("executing patches : %s ....",bootstrapType()));

                                                                            Bootstrap.patch(asyncResponse.result()).onComplete(future ->
                                                                            {
                                                                                if (future.succeeded())
                                                                                {
                                                                                    LOGGER.info("patches executed successfully...");

                                                                                    asyncPromise.complete();
                                                                                }
                                                                                else
                                                                                {
                                                                                    Bootstrap.stop(future.cause());

                                                                                    asyncPromise.fail(future.cause());
                                                                                }
                                                                            });
                                                                        }
                                                                        else
                                                                        {
                                                                            asyncPromise.fail(response.cause());
                                                                        }
                                                                    });

                                                                    asyncPromise.future().onComplete(asyncPromiseResponse ->
                                                                    {
                                                                        if (asyncPromiseResponse.succeeded())
                                                                        {
                                                                            var futures = new ArrayList<Future<Object>>();

                                                                    var senderPort = CommonUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol());

                                                                    for (var index = 0; index < MotadataConfigUtil.getEventSenders(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()); index++)
                                                                            {
                                                                                var promise = Promise.promise();

                                                                                futures.add(promise.future());

                                                                        Bootstrap.startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol(), senderPort + index, null, MotadataConfigUtil.getRemoteEventSender(), SocketMode.PUSH)), RemoteEventSender.class.getSimpleName() + " " + (senderPort + index), null,EVENT_APP + DOT_SEPARATOR + (senderPort + index))
                                                                                .onComplete(asyncResult ->
                                                                                {
                                                                                    if (asyncResult.succeeded())
                                                                                    {
                                                                                        promise.complete();
                                                                                    }
                                                                                    else
                                                                                    {
                                                                                        promise.fail(asyncResult.cause());
                                                                                    }
                                                                                });
                                                                    }

                                                                            Future.join(futures).onComplete(asyncResult ->
                                                                            {
                                                                                if (asyncResult.succeeded())
                                                                                {
                                                                                    var asyncResults = new ArrayList<Future<Object>>();

                                                                            var receiverPort = CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol());

                                                                            for (var index = 0; index < MotadataConfigUtil.getEventReceivers(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol()); index++)
                                                                                    {
                                                                                        var promise = Promise.promise();

                                                                                        asyncResults.add(promise.future());

                                                                                Bootstrap.startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol(), receiverPort + index, EVENT_APP + DOT_SEPARATOR + (receiverPort + index), MotadataConfigUtil.getRemoteEventReceiver(), SocketMode.SUB)), RemoteEventReceiver.class.getSimpleName() + " " + (receiverPort + index), null,
                                                                                                EVENT_APP + DOT_SEPARATOR + (receiverPort + index))
                                                                                        .onComplete(voidAsyncResult ->
                                                                                        {
                                                                                            if (voidAsyncResult.succeeded())
                                                                                            {
                                                                                                promise.complete();
                                                                                            }
                                                                                            else
                                                                                            {
                                                                                                promise.fail(voidAsyncResult.cause());
                                                                                            }
                                                                                        });
                                                                            }

                                                                                    Future.join(asyncResults).onComplete(asyncFutureResult -> startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                                                                                            .compose(future -> startEngine(new LocalEventChangeNotificationHandler(), LocalEventChangeNotificationHandler.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new DiscoveryEngine(), DiscoveryEngine.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new TopologyEngine(), TopologyEngine.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new RediscoverEngine(), RediscoverEngine.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new PluginEngine(), PluginEngine.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new MetricPoller(), MetricPoller.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new AutoScaler(), AutoScaler.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new PluginEngineResponseProcessor(), PluginEngineResponseProcessor.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new HealthUtil(), HealthUtil.class.getSimpleName(), null))
                                                                                            .compose(future -> startEngine(new LocalEventRouter(EventBusConstants.EVENT_LOG, EventBusConstants.EVENT_SOURCE, MotadataConfigUtil.getLogParsers(), LogParser.class.getCanonicalName(), true), LogParser.class.getSimpleName(), null))
                                                                                            .compose(future -> Bootstrap.startWorkerEngine(new UDPLogCollector(), UDPLogCollector.class.getSimpleName(), null))
                                                                                            .compose(future -> Bootstrap.startWorkerEngine(new JVMStatUtil(), JVMStatUtil.class.getSimpleName(), null))
                                                                                            .compose(future -> Bootstrap.startWorkerEngine(new DiagnosticUtil(), DiagnosticUtil.class.getSimpleName(), null))
                                                                                            .compose(future -> Bootstrap.startWorkerEngine(new TagUtil(), TagUtil.class.getSimpleName(), null))
                                                                                            .onComplete(result ->
                                                                                            {
                                                                                                try
                                                                                                {
                                                                                                    if (result.succeeded())
                                                                                                    {
                                                                                                        EventBusConstants.register(new CipherUtil());

                                                                                                        Bootstrap.vertx().eventBus().send(EVENT_REMOTE, new JsonObject().put(EVENT_TYPE, EVENT_APP)
                                                                                                                .put(HA_SYNC_OPERATION, HAConstants.HASyncOperation.ATTACHE.getName())
                                                                                                                .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC));

                                                                                                        LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                                                                                                        LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.getInstallationMode()));
                                                                                                    }
                                                                                                    else
                                                                                                    {
                                                                                                        LOGGER.error(result.cause());

                                                                                                        stop(result.cause());
                                                                                                    }
                                                                                                }
                                                                                                catch (Exception exception)
                                                                                                {
                                                                                                    LOGGER.error(exception);

                                                                                                    stop(exception);
                                                                                                }
                                                                                            }));

                                                                                }
                                                                                else
                                                                                {
                                                                                    LOGGER.error(asyncResult.cause());

                                                                                    System.exit(0);
                                                                                }
                                                                            });
                                                                        }
                                                                        else
                                                                        {
                                                                            Bootstrap.stop(asyncPromiseResponse.cause());
                                                                        }
                                                                    });

                                                                }
                                                                else
                                                                {
                                                                    Bootstrap.stop(futureResult.cause());
                                                                }
                                                            });
                                                        }
                                                        catch (Exception exception)
                                                        {
                                                            stop(exception);
                                                        }
                                                    }
                                                    else
                                                    {
                                                        stop(asyncPromiseResult.cause());
                                                    }
                                                }));
                                    }
                                    else
                                    {
                                        LOGGER.error(handler.cause());

                                        Bootstrap.stop(handler.cause());
                                    }
                                });
                            }
                            else
                            {
                                Bootstrap.stop(promiseResult.cause());
                            }
                        });
            }
            else
            {
                stop("motadata observer server is not reachable...");

                System.exit(0);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

}

