package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.api.MotadataApp;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.store.ArtifactConfigStore;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.json.JsonObject;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.GlobalConstants.ID;
import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE;
import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE;
import static com.mindarray.db.DBConstants.*;

public class Patch804 implements Patch
{
    private static final Logger LOGGER = new Logger(Patch804.class, MOTADATA_PATCH, "Patch 8.0.4");

    private static final String REMOTE_EVENT_TYPE = "remote.event.type";

    private static final String VERSION = "8.0.4";
    @Override
    public String getVersion()
    {
        return VERSION;
    }

    /**
     * -> For BOI:-
     * @CASE_1  - remote.event.processor.type = "MASTER"
     * @Solution - remote.event.processor.type = "APP", remote.event.processor.installation.mode = "PRIMARY"
     *
     * @CASE_2 - remote.event.processor.type = "SLAVE"
     * @Solution - remote.event.processor.type = "APP", remote.event.processor.installation.mode = "STANDALONE"
     *
     * @CASE_3 - remote.event.processor.type = "PRIMARY", remote.event.type = "DATASTORE"
     * @Solution - remote.event.processor.type = "DATASTORE", remote.event.processor.installation.mode = "PRIMARY"
     *
     * @CASE_4 - remote.event.processor.type = "SECONDARY", remote.event.type = "DATASTORE"
     * @Solution - remote.event.processor.type = "DATASTORE", remote.event.processor.installation.mode = "SECONDARY"
     *
     * @CASE_5 - remote.event.processor.type = "AGENT" || remote.event.processor.type = "COLLECTOR"
     * @Solution - remote.event.processor.type = "AGENT" || "COLLECTOR", remote.event.processor.installation.mode = "STANDALONE"
     *
     *@-> For Master Branch:-
     * @CASE_1 - remote.event.processor.type = "DEFAULT"
     * @Solution - remote.event.processor.type = "APP", remote.event.processor.installation.mode = "STANDALONE"
     *
     * @CASE_2 - remote.event.processor.type = "AGENT" || "COLLECTOR" || "DATASTORE"
     * @Solution - remote.event.processor.type = "AGENT" || "COLLECTOR" || "DATASTORE" , remote.event.installation.mode = "STANDALONE"
     **/
    @Override
    public boolean doPatch()
    {
        var status = false;

        LOGGER.info("changing remote.event.processor.type and remote.event.processor.installation.mode for all remote.event.processor");

        try
        {
            var processors = RemoteEventProcessorConfigStore.getStore().getItems();

            for (var index = 0; index <  processors.size(); index++)
            {
                var processor = processors.getJsonObject(index);

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("applying patch for remote event processor %s", processor.encode()));
                }

                switch (processor.getString(REMOTE_EVENT_PROCESSOR_TYPE))
                {
                    case "DEFAULT":

                        updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.APP.name())
                                .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.STANDALONE.name()));

                        break;
                    case "MASTER":

                        updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.APP.name())
                                .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.PRIMARY.name()));

                        break;
                    case "SLAVE":

                        updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.APP.name())
                                .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.SECONDARY.name()));

                        break;

                    case "REPLICA":

                        updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.APP.name())
                                .put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.FAILOVER.name()));

                        break;

                    case "PRIMARY":

                        if (processor.getString("remote.event.type").equalsIgnoreCase("DATANODE"))
                        {
                            updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.PRIMARY.name())
                                    .put(REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.DATASTORE.name()));
                        }
                        break;

                    case "SECONDARY":

                        if (processor.getString("remote.event.type").equalsIgnoreCase("DATANODE"))
                        {
                            updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.SECONDARY.name())
                                    .put(REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.DATASTORE.name()));
                        }

                        break;

                    case "AGENT", "COLLECTOR", "EVENT_COLLECTOR", "EVENT_PROCESSOR", "FLOW_COLLECTOR":

                        updateRemoteEventProcessorConfig(processor.put(REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.STANDALONE.name()));

                        break;
                    default:
                        LOGGER.info("Not applying patch for type: " + processor.getString(REMOTE_EVENT_PROCESSOR_TYPE));
                }

            }

            var artifacts = ArtifactConfigStore.getStore().getItems();

            for (var index = 0; index < artifacts.size(); index++)
            {
                var artifact = artifacts.getJsonObject(index);

                switch (artifact.getString(MotadataApp.ARTIFACT_TYPE))
                {
                    case "DEFAULT":

                        updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_TYPE, BootstrapType.APP.name())
                                .put(MotadataApp.ARTIFACT_MODE, InstallationMode.STANDALONE.name()));
                        break;

                    case "MASTER":

                        updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_TYPE, BootstrapType.APP.name())
                                .put(MotadataApp.ARTIFACT_MODE, InstallationMode.PRIMARY.name()));
                        break;

                    case "SLAVE":

                        updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_TYPE, BootstrapType.APP.name())
                                .put(MotadataApp.ARTIFACT_MODE, InstallationMode.SECONDARY.name()));
                        break;

                    case "REPLICA":

                        updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_TYPE, BootstrapType.APP.name())
                                .put(MotadataApp.ARTIFACT_MODE, InstallationMode.FAILOVER.name()));
                        break;

                    case "PRIMARY":

                        if (artifact.containsKey(REMOTE_EVENT_TYPE) && artifact.getString(REMOTE_EVENT_TYPE).equalsIgnoreCase("DATANODE"))
                        {
                            updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_TYPE, BootstrapType.DATASTORE.name())
                                    .put(MotadataApp.ARTIFACT_MODE, InstallationMode.PRIMARY.name()));
                        }
                        break;

                    case "SECONDARY":

                        if (artifact.containsKey(REMOTE_EVENT_TYPE) && artifact.getString(REMOTE_EVENT_TYPE).equalsIgnoreCase("DATANODE"))
                        {
                            updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_TYPE, BootstrapType.DATASTORE.name())
                                    .put(MotadataApp.ARTIFACT_MODE, InstallationMode.SECONDARY.name()));
                        }
                        break;

                    case "AGENT", "COLLECTOR", "EVENT_COLLECTOR", "EVENT_PROCESSOR", "FLOW_COLLECTOR":

                        updateArtifactConfig(artifact.put(MotadataApp.ARTIFACT_MODE, InstallationMode.STANDALONE.name()));
                        break;

                    default:
                        LOGGER.info("Not applying patch for type: " + artifact.getString(MotadataApp.ARTIFACT_TYPE));
                }
            }

            status = true;
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return status;
    }

    private void updateRemoteEventProcessorConfig(JsonObject item)
    {
        Bootstrap.configDBService().update(COLLECTION_REMOTE_EVENT_PROCESSOR,
                new JsonObject().put(FIELD_NAME, ID).put(VALUE, item.getLong(ID)),
                item.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_VERSION, VERSION),
                SYSTEM_USER, SYSTEM_REMOTE_ADDRESS,true, result ->
                {
                    if (result.succeeded())
                    {
                        RemoteEventProcessorConfigStore.getStore().updateItem(item.getLong(ID));

                        LOGGER.info(String.format("updated remote event processor : %s", item.getLong(ID)));
                    }
                    else
                    {
                        LOGGER.warn(String.format("failed to update remote event processor : %s ", item.getLong(ID)));
                    }
                });
    }

    private void updateArtifactConfig(JsonObject item)
    {
        Bootstrap.configDBService().update(COLLECTION_ARTIFACT,
                new JsonObject().put(FIELD_NAME, ID).put(VALUE, item.getLong(ID)),
                item.put(MotadataApp.ARTIFACT_VERSION, VERSION),
                SYSTEM_USER, SYSTEM_REMOTE_ADDRESS,true, result ->
                {
                    if (result.succeeded())
                    {
                        ArtifactConfigStore.getStore().updateItem(item.getLong(ID));

                        LOGGER.info(String.format("updated artifact : %s", item.getLong(ID)));
                    }
                    else
                    {
                        LOGGER.warn(String.format("failed to update artifact : %s ", item.getLong(ID)));
                    }
                });
    }
}

