import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.GlobalConstants.SYSTEM_REMOTE_ADDRESS;
import static com.mindarray.db.DBConstants.FIELD_NAME;

public class Patch812 implements Patch{

    private static final Logger LOGGER = new Logger(Patch812.class, MOTADATA_PATCH, "Patch 8.1.2");

    private static final String VERSION = "8.1.2";

    /**
     * Returns the version number of this patch.
     *
     * @return The version string "8.1.2"
     */
    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("executing 8.1.2 patch...");

            var futures = new ArrayList<Future<Void>>();

            futures.add(updateRetentionProfile());

            futures.add(executeKubernetesPatch());

            futures.add(executeTanzuKubernetesPatch());

            Future.join(futures).onComplete(result ->
            {
                if (result.succeeded())
                {
                    LOGGER.info("successfully executed 8.1.2 patch");

                    promise.complete();
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    private Future<Void> executeKubernetesPatch()
    {

        var promise = Promise.<Void>promise();

        var futures = new ArrayList<Future>();

        var items = ObjectConfigStore.getStore().getItemsByType(NMSConstants.Type.KUBERNETES);

        for (var item : items)
        {
            var metrics = MetricConfigStore.getStore().getItemsByObject((Long) item);

            var doPatch = true;

            for (var metric : metrics)
            {
                if (metric.getString(Metric.METRIC_PLUGIN).equals("kubernetesvolume"))
                {
                    doPatch = false;
                }
            }

            if (doPatch)
            {
                var itemPromise = Promise.promise();

                futures.add(itemPromise.future());

                var kubernetesVolumeMetric = metrics.getFirst().mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin("kubernetesvolume"));

                kubernetesVolumeMetric.remove(ID);

                Bootstrap.configDBService().saveAll(DBConstants.TBL_METRIC, new JsonArray().add(kubernetesVolumeMetric), DEFAULT_USER, MOTADATA_SYSTEM, result ->
                {
                    if (result.succeeded())
                    {
                        for (var record : result.result())
                        {
                            MetricConfigStore.getStore().addItem((Long) record).onComplete(response ->
                            {
                                LOGGER.info("successfully attached plugin for monitor " + item);

                            });
                        }

                        itemPromise.complete();
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        itemPromise.fail(result.cause());

                    }
                });
            }
        }

        CompositeFuture.all(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                LOGGER.info("successfully attached plugin for all monitors");

                promise.complete();
            }

            else
            {
                LOGGER.error(result.cause());

                promise.fail("Failed to attach plugin for all monitors with reason : " + result.cause().getMessage());

            }
        });

        return promise.future();
    }

    private Future<Void> executeTanzuKubernetesPatch()
    {

        var promise = Promise.<Void>promise();

        var futures = new ArrayList<Future>();

        var items = ObjectConfigStore.getStore().getItemsByType(NMSConstants.Type.TANZU_KUBERNETES);

        for (var item : items)
        {
            var metrics = MetricConfigStore.getStore().getItemsByObject((Long) item);

            var doPatch = true;

            for (var metric : metrics)
            {
                if (metric.getString(Metric.METRIC_PLUGIN).equals("tanzukubernetesvolume"))
                {
                    doPatch = false;
                }
            }

            if (doPatch)
            {
                var itemPromise = Promise.promise();

                futures.add(itemPromise.future());

                var tanzuKubernetesVolumeMetric = metrics.getFirst().mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin("tanzukubernetesvolume"));

                tanzuKubernetesVolumeMetric.remove(ID);

                Bootstrap.configDBService().saveAll(DBConstants.TBL_METRIC, new JsonArray().add(tanzuKubernetesVolumeMetric), DEFAULT_USER, MOTADATA_SYSTEM, result ->
                {
                    if (result.succeeded())
                    {

                        for (var record : result.result())
                        {
                            MetricConfigStore.getStore().addItem((Long) record).onComplete(response ->
                            {
                                LOGGER.info("successfully attached plugin for monitor " + item);

                            });
                        }

                        itemPromise.complete();
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        itemPromise.fail(result.cause());

                    }
                });
            }
        }

        CompositeFuture.all(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                LOGGER.info("successfully attached plugin for all monitors");

                promise.complete();
            }

            else
            {
                LOGGER.error(result.cause());

                promise.fail("Failed to attach plugin for all monitors with reason : " + result.cause().getMessage());

            }
        });

        return promise.future();
    }

    private Future<Void> updateRetentionProfile()
    {
        var promise = Promise.<Void>promise();

        var item = DataRetentionPolicyConfigStore.getStore().getItem(GlobalConstants.DEFAULT_ID);

        if (item != null)
        {
            LOGGER.info("Existing retention profile : " + item.encode());

            var context = item.getJsonObject(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT);

            if (context != null)
            {
                if (context.containsKey("AUDIT") && context.getJsonObject("AUDIT").getInteger("raw") < 180)
                {
                    context.put("AUDIT", context.getJsonObject("AUDIT").put("raw", 180));

                    item.put(DataRetentionPolicy.DATA_RETENTION_POLICY_CONTEXT,context);

                    Bootstrap.configDBService().update(DBConstants.TBL_DATA_RETENTION_POLICY,
                            new JsonObject().put(FIELD_NAME, ID).put(VALUE, GlobalConstants.DEFAULT_ID),
                            item,
                            DEFAULT_USER,
                            SYSTEM_REMOTE_ADDRESS, result ->
                            {
                                if (result.succeeded())
                                {
                                    DataRetentionPolicyConfigStore.getStore().updateItem(GlobalConstants.DEFAULT_ID).onComplete(handler ->
                                    {
                                        if (handler.succeeded())
                                        {
                                            LOGGER.info("Data retention value changed for audit , new updated profile is : " + item.encode());

                                            promise.complete();
                                        }
                                        else
                                        {
                                            LOGGER.warn(String.format("Failed to Audit update Data retention in config store with reason : %s", handler.cause().getMessage()));

                                            promise.fail(handler.cause());
                                        }
                                    });
                                }
                                else
                                {
                                    LOGGER.warn(String.format("Failed to Audit update Data retention with reason : %s", result.cause().getMessage()));

                                    promise.fail(result.cause());
                                }
                            });
                }
                else
                {
                    LOGGER.info("No need to update retention profile, because audit retention is greater than 180 days.");

                    promise.complete();
                }
            }
            else
            {
                promise.fail("No retention profile context found");
            }
        }
        else
        {
            promise.fail("item not found");
        }

        return promise.future();
    }
}

