                if (item.containsKey(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE) && item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE).equalsIgnoreCase(BootstrapType.APP.name()))
                {
                    item.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE, BootstrapType.APP.name());

                    item.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, InstallationMode.PRIMARY.name()); //TODO
                }

                if (!item.containsKey(RemoteEventProcessor.REMOTE_EVENT_TYPE))
                {
                    switch (BootstrapType.valueOf(item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE)))
                    {
                        case APP, COLLECTOR ->
                                item.put(RemoteEventProcessor.REMOTE_EVENT_TYPE, "REMOTE POLLER");

                        case DATANODE -> item.put(RemoteEventProcessor.REMOTE_EVENT_TYPE, "DATANODE");

                        default ->
                                LOGGER.warn("Invalid type : " + item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE));
                    }
                }

                Bootstrap.configDBService.update(COLLECTION_REMOTE_EVENT_PROCESSOR,
                        new JsonObject().put(FIELD_NAME, ID)
                                .put(VALUE, item.getLong(ID)), item,
                        SYSTEM_USER, SYSTEM_REMOTE_ADDRESS, true, result ->
                        {
                            if (result.succeeded())
                            {
                                RemoteEventProcessorConfigStore.getStore().updateItem(item.getLong(ID));

                                LOGGER.info("updated item : " + RemoteEventProcessorConfigStore.getStore().getItem(item.getLong(ID)));
                            }
                            else
                            {
                                LOGGER.warn(result.cause());
                            }
                        });
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }
