import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.SESSION_ID;
import static com.mindarray.eventbus.EventBusConstants.*;


public class UINotificationEventHandler extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(UINotificationEventHandler.class, GlobalConstants.MOTADATA_EVENT_BUS, "UI Notification Event Handler");

    private boolean timerHandler = false;

    private static final JsonArray changes = new JsonArray();

    private static final Map<String, Long> timestampBySession = new ConcurrentHashMap<>();

    private static final Map<String, Boolean> configChangesBySession = new ConcurrentHashMap<>();

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        // approach - 1
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.UI_NOTIFICATION_CONFIG_CHANGE, message ->
        {
            if (!timerHandler)
            {
                timerHandler = true;

                vertx.setTimer(3000, handler ->
                {
                    vertx.cancelTimer(handler);

                    vertx.<Void>executeBlocking(future ->
                    {
                        try
                        {
                            var objects = ObjectConfigStore.getStore().getFilteredItems();

                            for (var index = 0; index < objects.size(); index++)
                            {
                                var object = objects.getJsonObject(index);

                                if (object.getString(AIOpsObject.OBJECT_CATEGORY).equalsIgnoreCase(NMSConstants.Category.SERVER.getName()))
                                {
                                    var result = getServerApps(MetricConfigStore.getStore().getItemsByObject(objects.getJsonObject(index).getLong(ID)));

