    private JsonObject getConfigContext()
    {
        var metricTypes = MetricConfigStore.getStore().getMetricTypes();

        //add agent metric type like if agent is linux based than add linux metric type for custom metric plugin to avoid agent metric provision
        ObjectConfigStore.getStore().getItemsByAgentIds().stream().filter(item -> !metricTypes.contains(item.getString(AIOpsObject.OBJECT_TYPE)))
                .map(item -> item.getString(AIOpsObject.OBJECT_TYPE)).distinct().toList().forEach(metricTypes::add);

        return new JsonObject().put(AIOpsObject.OBJECT_TYPE, ObjectConfigStore.getStore().getObjectTypes())
                .put(Metric.METRIC_TYPE, metricTypes)
                .put("license", LicenseUtil.getLicenseDetails());
    }

    private JsonObject getServerApps(List<JsonObject> items)
    {
        var result = new JsonObject();

        var apps = new JsonArray();

        var appProcess = new JsonObject();

        for (var item : items)
        {
            if (!appProcess.containsKey(item.getString(Metric.METRIC_TYPE)) && item.getJsonObject(Metric.METRIC_CONTEXT).containsKey(NMSConstants.OBJECT))
            {
                appProcess.put(item.getString(Metric.METRIC_TYPE), item.getJsonObject(Metric.METRIC_CONTEXT).getJsonObject(NMSConstants.OBJECT));

                if (NMSConstants.APPLICATION_TYPES.contains(item.getString(Metric.METRIC_TYPE)))
                {
                    apps.add(new JsonObject().put(Metric.METRIC_TYPE, item.getString(Metric.METRIC_TYPE)).put(Metric.METRIC_DISCOVERY_METHOD, item.getString(Metric.METRIC_DISCOVERY_METHOD)));            //#28048
                }
            }
        }

        result.put(NMSConstants.APPS, apps);

        result.put(NMSConstants.APP_PROCESS, appProcess);

        return result;
    }
