package com.mindarray;

import com.mindarray.eventbus.*;
import com.mindarray.flow.FlowCacheProcessor;
import com.mindarray.flow.FlowListener;
import com.mindarray.flow.FlowProcessor;
import com.mindarray.flow.FlowStatCalculator;
import com.mindarray.log.LogParser;
import com.mindarray.log.TCPLogListener;
import com.mindarray.log.UDPLogListener;
import com.mindarray.util.*;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.eventbus.MessageConsumer;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;
import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.Bootstrap.buildClientTransportConfig;
import static com.mindarray.eventbus.EventBusConstants.EVENT_CONFIG_INIT;
import static com.mindarray.eventbus.EventBusConstants.EVENT_PUBLICATION;

public class BootstrapEventCollector
{
    private static final Logger LOGGER = new Logger(BootstrapEventCollector.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Event Collector");

    private static MessageConsumer<JsonObject> messageConsumer;

    private static void startRemoteEventProcessor()
    {
        Bootstrap.startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null)
                .onComplete(response ->
                {
                    if (response.succeeded())
                    {
                        EventBusConstants.setRemoteEventProcessorRegistrationId();

                        var promises = new ArrayList<Future<Object>>();

                        var receiverPort = CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol());

                        for (var index = 0; index < MotadataConfigUtil.getEventReceivers(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol()); index++)
                        {
                            var promise = Promise.promise();

                            promises.add(promise.future());

                            Bootstrap.startEngine(new RemoteEventReceiver(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorReceiverProtocol(), receiverPort + index, EVENT_PUBLICATION, CommonUtil.getRemoteEventSender(), EventBusConstants.SocketMode.SUB)), RemoteEventReceiver.class.getSimpleName() + " " + (receiverPort + index), null)
                                    .onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    promise.complete();
                                }
                                else
                                {
                                    promise.fail(result.cause());
                                }
                            });
                        }

                        Future.join(promises).onComplete(asyncResponse ->
                        {
                            if (asyncResponse.succeeded())
                            {
                                try
                                {
                                    var futures = new ArrayList<Future<Object>>();

                                    var senderPort = CommonUtil.getEventSenderPort(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol());

                                    for (var index = 0; index < MotadataConfigUtil.getEventSenders(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol()); index++)
                                    {
                                        var promise = Promise.promise();

                                        futures.add(promise.future());

                                        Bootstrap.startEngine(new RemoteEventSender(buildClientTransportConfig(MotadataConfigUtil.getEventRemoteProcessorSenderProtocol(), senderPort + index, null, CommonUtil.getRemoteEventSender(), EventBusConstants.SocketMode.PUSH)), RemoteEventSender.class.getSimpleName() + " " + (senderPort + index), null).onComplete(asyncResult ->
                                        {
                                            if (asyncResult.succeeded())
                                            {
                                                promise.complete();
                                            }
                                            else
                                            {
                                                promise.fail(asyncResult.cause());
                                            }
                                        });
                                    }

                                    Future.join(futures).onComplete(result ->
                                    {
                                        if (result.failed())
                                        {
                                            Bootstrap.stop(result.cause());
                                        }
                                        else
                                        {
                                            try
                                            {
                                                LOGGER.info(String.format("%s request to register...", Bootstrap.bootstrapType()));

                                                EventBusConstants.register(new CipherUtil());
                                            }
                                            catch (Exception exception)
                                            {
                                                LOGGER.error(exception);
                                            }
                                        }
                                    });
                                }
                                catch (Exception exception)
                                {
                                    Bootstrap.stop(exception);
                                }
                            }
                            else
                            {
                                Bootstrap.stop(asyncResponse.cause());
                            }
                        });
                    }
                    else
                    {
                        Bootstrap.stop(response.cause());
                    }
                });

        messageConsumer = Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EVENT_CONFIG_INIT, message ->
        {

            messageConsumer.unregister();

            if (message.body() != null)
            {
                Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_LOG, EventBusConstants.EVENT_SOURCE, MotadataConfigUtil.getLogParsers(), LogParser.class.getCanonicalName(), true, true, EventBusConstants.EventRouter.ROUND_ROBIN), LogParser.class.getSimpleName(), null)
                        .compose(future -> Bootstrap.startEngine(new LocalEventChangeNotificationHandler(), LocalEventChangeNotificationHandler.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startWorkerEngine(new TCPLogListener(), TCPLogListener.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startWorkerEngine(new UDPLogListener(), UDPLogListener.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startEngine(new HealthUtil(), HealthUtil.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startWorkerEngine(new JVMStatUtil(), JVMStatUtil.class.getSimpleName(), null))
                        .compose(future -> Bootstrap.startWorkerEngine(new DiagnosticUtil(), DiagnosticUtil.class.getSimpleName(), null))
                        .onComplete(result ->
                        {
                            if (result.failed())
                            {
                                Bootstrap.stop(result.cause());
                            }
                            else
                            {
                                LogUtil.resetLogLevel(MotadataConfigUtil.getLogLevelResetTimerSeconds());

                                if (MotadataConfigUtil.flowEnabled())
                                {
                                    Bootstrap.startEngine(new FlowListener(), FlowListener.class.getSimpleName(), null)
                                            .compose(future -> Bootstrap.startWorkerEngine(new FlowCacheProcessor(), FlowCacheProcessor.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_FLOW, "peer_ip_src", MotadataConfigUtil.getFlowProcessors(), FlowProcessor.class.getCanonicalName(), true, true, EventBusConstants.EventRouter.ROUND_ROBIN), FlowProcessor.class.getSimpleName(), null))
                                            .compose(future -> Bootstrap.startEngine(new FlowStatCalculator(), FlowStatCalculator.class.getSimpleName(), null))
                                            .onComplete(asyncResult ->
                                            {

                                                if (asyncResult.failed())
                                                {
                                                    Bootstrap.stop(asyncResult.cause());
                                                }
                                                else
                                                {
                                                    GeoDBUtil.init(Bootstrap.vertx());

                                                    LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                                                }
                                            });
                                }
                                else if (LicenseUtil.LICENSE_EDITION.get() == LicenseUtil.LicenseEdition.OBSERVABILITY)
                                {
                                    Bootstrap.startEngine(new LocalEventRouter(EventBusConstants.EVENT_FLOW, "peer_ip_src", MotadataConfigUtil.getFlowProcessors(), FlowProcessor.class.getCanonicalName(), true, true, EventBusConstants.EventRouter.ROUND_ROBIN), FlowProcessor.class.getSimpleName(), null).onComplete(asyncResult ->
                                    {

                                        if (asyncResult.succeeded())
                                        {
                                            LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, Bootstrap.bootstrapType()));
                                        }
                                        else
                                        {
                                            Bootstrap.stop(asyncResult.cause());
                                        }
                                    });
                                }
                                else
                                {
