package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.*;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Calendar;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;

public class Datastore
{
    private static final Logger LOGGER = new Logger(Datastore.class, GlobalConstants.MOTADATA_EVENT_BUS, "Event Data Store");
    private final String path; //path for get current event directory
    private final Calendar calendar;  //calendar for get current second
    private final Map<Long, EventFile> eventFiles; //store all files by time order (milliseconds)
    private byte[] bytes;

    protected Datastore(String path)
    {
        this.path = path;

        eventFiles = new LinkedHashMap<>();

        this.calendar = Calendar.getInstance();

        this.bytes = new byte[8 * 1024];
    }

    protected void put(JsonObject event) throws Exception
    {
        try
        {
            var timestamp = event.getLong(EventBusConstants.EVENT_TIMESTAMP, DateTimeUtil.currentSeconds());

            if (timestamp > 0)
            {
                calendar.setTimeInMillis(timestamp * 1000); //seconds to millis

                calendar.set(Calendar.MILLISECOND, 0);

                calendar.set(Calendar.SECOND, 0);

                timestamp = calendar.getTimeInMillis();

                var eventFile = eventFiles.get(timestamp);

                if (eventFile == null)
                {
                    var file = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp + ".dat");

                    var fileOutputStream = new FileOutputStream(file, true);

                    var fileInputStream = new FileInputStream(file);

                    var bufferedOutputStream = new BufferedOutputStream(fileOutputStream, bytes.length);

                    eventFile = new EventFile(bufferedOutputStream, fileInputStream, fileOutputStream, new AtomicLong(0L), new AtomicLong(0L));

                    eventFiles.put(timestamp, eventFile);

                }

                var bufferBytes = CodecUtil.compress(event.encode());

                if (bufferBytes.length + 4 > this.bytes.length)
                {
                    this.bytes = new byte[bufferBytes.length + 4]; //if buffer bytes is larger than existing bytes then we must need to expand for the future read purpose...
                }

                ByteUtil.writeInt(this.bytes, bufferBytes.length, 0);

                eventFile.bufferedOutputStream.write(bytes, 0, 4);

                eventFile.bufferedOutputStream.write(bufferBytes, 0, bufferBytes.length);

                eventFile.bufferedOutputStream.flush();

                eventFile.events().incrementAndGet(); //increment total events by file

            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void put(byte[] bytes) throws Exception
    {
        try
        {
            var timestamp = ByteUtil.readLongValue(bytes); //get timetick from first 8 bytes

            if (timestamp > 0)
            {
                calendar.setTimeInMillis(timestamp);

                calendar.set(Calendar.MILLISECOND, 0);

                calendar.set(Calendar.SECOND, 0);

                timestamp = calendar.getTimeInMillis();

                var eventFile = eventFiles.get(timestamp);

                if (eventFile == null)
                {
                    var file = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp + ".dat");

                    var fileOutputStream = new FileOutputStream(file, true);

                    var fileInputStream = new FileInputStream(file);

                    var bufferedOutputStream = new BufferedOutputStream(fileOutputStream, bytes.length);

                    eventFile = new EventFile(bufferedOutputStream, fileInputStream, fileOutputStream, new AtomicLong(0L), new AtomicLong(0L));

                    eventFiles.put(timestamp, eventFile);

                }

                eventFile.bufferedOutputStream.write(bytes, 8, bytes.length - 8); //skip first 8 bytes of timetick...

                eventFile.bufferedOutputStream.flush();

                eventFile.events().incrementAndGet();  //increment total events by file

                if (bytes.length + 4 > this.bytes.length)
                {
                    this.bytes = new byte[bytes.length + 4];  //if buffer bytes is larger than existing bytes then we must need to expand for the future read purpose...
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected byte[] get() throws Exception
    {
        byte[] bufferBytes;

        try
        {
            for (var iterator = eventFiles.entrySet().iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                try
                {
                    var length = entry.getValue().fileInputStream.read(bytes, 0, 4);

                    if (length != 4) //means invalid file ... delete it skip to next file.
                    {
                        entry.getValue().fileInputStream.close();

                        entry.getValue().bufferedOutputStream.close();

                        entry.getValue().fileOutputStream.close();

                        Files.deleteIfExists(Paths.get(path + GlobalConstants.PATH_SEPARATOR + entry.getKey() + ".dat"));

                        iterator.remove();
                    }
                    else
                    {
                        length = ByteUtil.readIntValue(bytes);

                        if (length != entry.getValue().fileInputStream.read(bytes, 0, length)) //means invalid file ... delete it skip to next file.
                        {
                            entry.getValue().fileInputStream.close();

                            entry.getValue().bufferedOutputStream.close();

                            entry.getValue().fileOutputStream.close();

                            Files.deleteIfExists(Paths.get(path + GlobalConstants.PATH_SEPARATOR + entry.getKey() + ".dat"));

                            iterator.remove();
                        }
                        else
                        {
                            entry.getValue().events().decrementAndGet();

                            entry.getValue().offset.addAndGet(length + 4); //mark read position

                            bufferBytes = CodecUtil.toBytes(bytes, 0, length); //plain  uncompressed bytes...

                            return bufferBytes;
                        }
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return null;
    }

    protected long load() throws Exception
    {
        var bookmark = new File(path + GlobalConstants.PATH_SEPARATOR + "bookmarks");

        var eventFiles = new File(path + GlobalConstants.PATH_SEPARATOR + "event-files");

        var offsets = new HashMap<Long, Long>();

        var events = new HashMap<Long, Long>();

        try
        {
            if (bookmark.exists())
            {
                var value = Files.readString(bookmark.toPath(), StandardCharsets.UTF_8);

                if (CommonUtil.isNotNullOrEmpty(value))
                {
                    for (var entry : new JsonObject(value))
                    {
                        offsets.put(CommonUtil.getLong(entry.getKey()), CommonUtil.getLong(entry.getValue().toString().split("_")[1]));

                        events.put(CommonUtil.getLong(entry.getKey()), CommonUtil.getLong(entry.getValue().toString().split("_")[0]));
                    }
                }
            }

            if (eventFiles.exists())
            {
                var content = Files.readString(eventFiles.toPath(), StandardCharsets.UTF_8);

                if (CommonUtil.isNotNullOrEmpty(content))
                {
                    (new JsonArray(content)).forEach(entry ->
                    {
                        var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + CommonUtil.getString(entry) + ".dat");

                        try
                        {
                            var name = CommonUtil.getString(entry);

                            var fileOutputStream = new FileOutputStream(eventFile, true);

                            var fileInputStream = new FileInputStream(eventFile);

                            var offset = offsets.getOrDefault(name, 0L);

                            fileInputStream.skip(offset);

                            this.eventFiles.put(CommonUtil.getLong(name), new EventFile(new BufferedOutputStream(fileOutputStream, bytes.length), fileInputStream, fileOutputStream, new AtomicLong(offset),new AtomicLong(events.getOrDefault(CommonUtil.getLong(entry), 0L))));
                        }
                        catch (Exception exception)
                        {
                            LOGGER.error(exception);
                        }
                    });
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return events.values().stream().reduce(0L, Long::sum); //return total pending events...
    }

    protected boolean isEmpty()
    {
        return eventFiles.isEmpty();
    }

    protected void save()
    {
        try
        {
            var bookmarks = new JsonObject();

            var writeFiles = new JsonArray();

            eventFiles.forEach((key, value) ->
            {
                bookmarks.put(CommonUtil.getString(key), value.events.get() + "_" + value.offset.get());

                writeFiles.add(key);
            });

            Bootstrap.vertx().fileSystem().writeFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "bookmarks", bookmarks.toBuffer());

            Bootstrap.vertx().fileSystem().writeFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "event-files", writeFiles.toBuffer());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void close()
    {
        try
        {
            for (Map.Entry<Long, EventFile> entry : eventFiles.entrySet())
            {
                entry.getValue().fileInputStream.close();

                entry.getValue().bufferedOutputStream.close();

                entry.getValue().fileOutputStream.close();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private
    record EventFile(BufferedOutputStream bufferedOutputStream, FileInputStream fileInputStream,
                     FileOutputStream fileOutputStream, AtomicLong offset, AtomicLong events)
    {

    }
}
