package com.mindarray.config;

import com.mindarray.ErrorCodes;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.api.*;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.store.ConfigurationConfigStore;
import com.mindarray.store.CredentialProfileConfigStore;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import com.mindarray.util.WorkerUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

import static com.mindarray.ErrorMessageConstants.*;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.InfoMessageConstants.SSH_CONNECTION_CLOSED;
import static com.mindarray.api.Configuration.CONFIG_CREDENTIAL_PROFILE;
import static com.mindarray.api.Configuration.CONFIG_OBJECT;
import static com.mindarray.api.CredentialProfile.CREDENTIAL_PROFILE_CONTEXT;
import static com.mindarray.eventbus.EventBusConstants.*;

public class SSHClientManager extends AbstractVerticle
{
    public static final String SSH_OPERATION = "ssh.operation";
    public static final String SSH_OUTPUT = "output";
    public static final String PROXY_SERVER = "proxy.server";
    public static final String PROXY_PASSWORD = "proxy.password";
    public static final String PROXY_USERNAME = "proxy.username";
    public static final String PROXY_PORT = "proxy.port";
    private static final Logger LOGGER = new Logger(SSHClientManager.class, MOTADATA_CONFIGURATION, "SSH Client Manager");
    private static final int SSH_MAX_CLIENTS = MotadataConfigUtil.getSSHMaxClients();
    private static final int SSH_CLIENT_TIMEOUT = MotadataConfigUtil.getSSHClientTimeoutSeconds();
    private final Map<String, Process> clientTrackers = new HashMap<>(); // key > value -> UUID > SSH Client Manager Process

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EVENT_SSH_CLIENT_MANAGER, message -> execute(message.body()));

        vertx.eventBus().<JsonObject>localConsumer(EVENT_SSH_CLIENT_CLOSE, message -> close(message.body()));

        promise.complete();
    }

    /**
     * Method will start, execute command and close the ssh sessions
     *
     * @param event Event from UI
     */
    private void execute(JsonObject event)
    {

        if (CommonUtil.traceEnabled())
        {
            LOGGER.trace(String.format("SSH event : %s", event));

        }

        if (event != null && !event.isEmpty())
        {
            if (event.getString(SSH_OPERATION).equalsIgnoreCase(ConfigConstants.ClientOperation.CONNECTION.getName()) &&
                    !clientTrackers.containsKey(event.getString(EventBusConstants.UI_EVENT_UUID)))
            {
                if (clientTrackers.size() <= SSH_MAX_CLIENTS)
                {
                    create(event);
                }
                else
                {
                    EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(SSH_OPERATION, ConfigConstants.ClientOperation.CONNECTION.getName()).put(STATUS, STATUS_FAIL).put(ERRORS, new JsonArray(new ArrayList<JsonObject>(1)).add(new JsonObject().put(ERROR_CODE, ErrorCodes.ERROR_CODE_SSH_CONNECTION_LIMIT_EXCEEDED).put(MESSAGE, SSH_SESSION_LIMIT_EXCEED))));

                    LOGGER.warn(String.format("Session limit exceeded while creating new session with UUID : %s, User : %s ", event.getString(UI_EVENT_UUID), event.getString(User.USER_NAME)));
                }
            }
            else if (event.getString(SSH_OPERATION).equalsIgnoreCase(ConfigConstants.ClientOperation.EXECUTION.getName()))
            {
                write(event);
            }
            else if (event.getString(SSH_OPERATION).equalsIgnoreCase(ConfigConstants.ClientOperation.CLOSE.getName()))
            {
                close(event);

                EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_SUCCEED).put(SSH_OPERATION, ConfigConstants.ClientOperation.CLOSE.getName()).put(SSH_OUTPUT, String.format(SSH_CONNECTION_CLOSED, event.getString(AIOpsObject.OBJECT_IP))));
            }
        }
    }

    private void create(JsonObject event)
    {
        try
        {
            var item = ConfigurationConfigStore.getStore().existItem(event.getLong(ID)) ? ConfigurationConfigStore.getStore().getItem(event.getLong(ID)) : ObjectConfigStore.getStore().getItem(event.getLong(ID));

            var object = item.containsKey(CONFIG_OBJECT) ? ObjectConfigStore.getStore().getItemByValue(AIOpsObject.OBJECT_ID, item.getLong(Configuration.CONFIG_OBJECT)) : ObjectConfigStore.getStore().getItem(event.getLong(ID));

            if (item.containsKey(CONFIG_OBJECT))
            {
                item.mergeIn(object);

                event.mergeIn(CredentialProfileConfigStore.getStore().getItem(item.getLong(CONFIG_CREDENTIAL_PROFILE)).getJsonObject(CREDENTIAL_PROFILE_CONTEXT)).put(PORT, item.getJsonObject(Configuration.CONFIG_CONTEXT).getLong(PORT));
            }

            event.put(AIOpsObject.OBJECT_VENDOR, object.getString(AIOpsObject.OBJECT_VENDOR, EMPTY_VALUE));

            if (item.containsKey(AIOpsObject.OBJECT_EVENT_PROCESSORS) && !MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
            {
                event.put(AIOpsObject.OBJECT_EVENT_PROCESSORS, item.getJsonArray(AIOpsObject.OBJECT_EVENT_PROCESSORS));

                event.put(PROXY_PASSWORD, ConfigConstants.SERVER_CONTEXT.getString("server.password")).put(PROXY_USERNAME, ConfigConstants.SERVER_CONTEXT.getString("server.username")).put(PROXY_PORT, SSH_PORT).put(PROXY_SERVER, RemoteEventProcessorConfigStore.getStore().getItem(event.getJsonArray(AIOpsObject.OBJECT_EVENT_PROCESSORS).getLong(0)).getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_IP));

                LOGGER.info(String.format("Updated event with processors : %s", event.encodePrettily()));
            }

            var protocol = CredentialProfileConfigStore.getStore().getItem(item.getLong(CONFIG_CREDENTIAL_PROFILE, 0L)).getString(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL);

            LOGGER.info(String.format("Creating new %s : protocol session for the user: %s, UUID : %s, object : %s", protocol, event.getString(User.USER_NAME), event.getString(UI_EVENT_UUID), event.getString(AIOpsObject.OBJECT_IP)));


            // checking if username, password and port is valid
            if (event.containsKey(USERNAME) && event.containsKey(PASSWORD) && event.containsKey(PORT) &&
                    !event.getString(USERNAME).isEmpty() && !event.getString(PASSWORD).isEmpty() && (event.getLong(PORT) != null))
            {
                var arguments = new ArrayList<String>();

                var util = protocol.equalsIgnoreCase(NMSConstants.Protocol.TELNET.getName()) ? "./telnetutils" : "./sshutils";

                arguments.add(CURRENT_DIR + PATH_SEPARATOR + util);

                LOGGER.trace(String.format("Event sent for util : %s is : %s", util, event.encodePrettily()));

                arguments.add(Base64.getEncoder().encodeToString(event.encode().getBytes()));

                var processBuilder = new ProcessBuilder(arguments).redirectErrorStream(true);

                var process = processBuilder.start();

                var pid = process.pid();

                LOGGER.info(String.format("%s client process started - PID: %s, UUID: %s, IP: %s", protocol, pid, event.getString(UI_EVENT_UUID), event.getString(AIOpsObject.OBJECT_IP)));

                clientTrackers.put(event.getString(EventBusConstants.UI_EVENT_UUID), process);

                WorkerUtil.setupCleanupTimer(SSH_CLIENT_TIMEOUT, process, processBuilder, NOT_AVAILABLE, null, null);

                // starting thread to read from stream
                new Thread(() -> read(process, event), String.format("%s Client (%s)", protocol, event.getString(EventBusConstants.UI_EVENT_UUID))).start();
            }
            else
            {
                LOGGER.trace(String.format("Invalid connection parameters for event : %s", event));

                EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_FAIL).put(SSH_OUTPUT, EMPTY_VALUE).put(SSH_OPERATION, ConfigConstants.ClientOperation.CONNECTION.getName()).put(ERRORS, new JsonArray().add(new JsonObject().put(ERROR_CODE, ErrorCodes.ERROR_CODE_SSH_CONNECTION_FAILED).put(ERROR, "Invalid input").put(MESSAGE, SSH_SESSION_INVALID_INPUT))));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_FAIL).put(SSH_OUTPUT, EMPTY_VALUE).put(SSH_OPERATION, ConfigConstants.ClientOperation.CONNECTION.getName()).put(ERRORS, new JsonArray().add(new JsonObject().put(ERROR_CODE, ErrorCodes.ERROR_CODE_SSH_CONNECTION_FAILED).put(ERROR, exception.getMessage()).put(MESSAGE, String.format("%s, check host server and credentials", ErrorMessageConstants.CONNECTION_FAILED)))));
        }
    }

    private void read(Process process, JsonObject event)
    {
        var errors = new StringBuilder();

        var output = new StringBuilder();

        event = CommonUtil.removeSensitiveFields(event, false);

        try
        {
            try (var reader = new BufferedReader(new InputStreamReader(process.getInputStream())))
            {
                var line = EMPTY_VALUE;

                while ((line = reader.readLine()) != null)
                {
                    output.append(line);

                    if (!output.isEmpty())
                    {
                        var response = output.toString();

                        if (response.contains(VALUE_SEPARATOR)) // success response will always get value separator from process
                        {
                            if (CommonUtil.traceEnabled())
                            {
                                LOGGER.trace(String.format("Response successfully received : %s", response));
                            }

                            var result = new JsonObject(new String(Base64.getDecoder().decode(response.split(VALUE_SEPARATOR_WITH_ESCAPE)[0])));

                            if (result.containsKey(RESULT) && result.containsKey(STATUS) && result.getString(STATUS).equalsIgnoreCase(STATUS_SUCCEED))
                            {
                                if (result.containsKey(SSH_OPERATION) && result.getString(SSH_OPERATION).equalsIgnoreCase(ConfigConstants.ClientOperation.CONNECTION.getName()))
                                {
                                    if (!result.getJsonObject(RESULT).isEmpty())
                                    {
                                        EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(SSH_OUTPUT, result.getJsonObject(RESULT).getString(SSH_OUTPUT)).put(SSH_OPERATION, ConfigConstants.ClientOperation.EXECUTION.getName()));
                                    }
                                    else
                                    {
                                        EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(SSH_OUTPUT, EMPTY_VALUE).put(STATUS, STATUS_SUCCEED).put(SSH_OPERATION, ConfigConstants.ClientOperation.CONNECTION.getName()));
                                    }
                                }
                                else if (result.containsKey(SSH_OPERATION) && result.getString(SSH_OPERATION).equalsIgnoreCase(ConfigConstants.ClientOperation.EXECUTION.getName()))
                                {
                                    EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(SSH_OUTPUT, result.getJsonObject(RESULT).getString(SSH_OUTPUT)).put(SSH_OPERATION, ConfigConstants.ClientOperation.EXECUTION.getName()));
                                }
                            }
                            else
                            {
                                vertx.eventBus().send(EVENT_SSH_CLIENT_CLOSE, event);
                            }

                            event.mergeIn(result);

                            output.setLength(0);
                        }
                        else
                        {
                            errors.append(response);
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            errors.append("Internal Error");
        }
        finally
        {
            if (!errors.isEmpty())
            {
                EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_FAIL).put(SSH_OUTPUT, EMPTY_VALUE).put(SSH_OPERATION, ConfigConstants.ClientOperation.CONNECTION.getName()).put(ERRORS, new JsonArray().add(new JsonObject().put(ERROR_CODE, ErrorCodes.ERROR_CODE_SSH_CONNECTION_FAILED).put(ERROR, errors.toString()).put(MESSAGE, String.format("%s, check host server and credentials", ErrorMessageConstants.CONNECTION_FAILED)))));
            }

            vertx.eventBus().send(EVENT_SSH_CLIENT_CLOSE, event);

            EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_FAIL).put(SSH_OUTPUT, EMPTY_VALUE).put(SSH_OPERATION, ConfigConstants.ClientOperation.CONNECTION.getName())
                    .put(ERRORS, new JsonArray().add(new JsonObject().put(ERROR_CODE, ErrorCodes.ERROR_CODE_SSH_CONNECTION_FAILED).put(ERROR, errors.toString())
                            .put(MESSAGE, event.getJsonArray(ERRORS) != null ? event.getJsonArray(ERRORS).getJsonObject(0).getString(MESSAGE) : String.format(SSH_CONNECTION_CLOSED, event.getString(AIOpsObject.OBJECT_IP))))));
        }
    }

    private void write(JsonObject event)
    {
        try
        {
            var uuid = event.getString(EventBusConstants.UI_EVENT_UUID);

            if (clientTrackers.containsKey(uuid))
            {
                var outputStream = clientTrackers.get(uuid).getOutputStream();

                outputStream.write((Base64.getEncoder().encodeToString(event.encode().getBytes()) + "\n").getBytes());

                outputStream.flush();
            }
            else
            {
                LOGGER.warn(String.format(SSH_CONNECTION_CLOSED, event.getString(AIOpsObject.OBJECT_IP)));

                EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_FAIL).put(SSH_OUTPUT, String.format(SSH_CONNECTION_CLOSED, event.getString(AIOpsObject.OBJECT_IP))).put(ERRORS, new JsonArray().add(new JsonObject().put(MESSAGE, SSH_SESSION_EXECUTION_FAILED))));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            close(event);

            EventBusConstants.publish(UI_ACTION_SSH_CLIENT_MANAGER, event.put(STATUS, STATUS_FAIL).put(SSH_OUTPUT, String.format(SSH_CONNECTION_CLOSED, event.getString(AIOpsObject.OBJECT_IP))).put(ERRORS, new JsonArray().add(new JsonObject().put(MESSAGE, "Failed to process EXECUTION, Reason : exception occurs"))));
        }
    }


    /**
     * Closes the SSH session identified by the event data. This method retrieves the session object
     * from the `sessions` map and checks for its existence. If the session exists, it disconnects
     * from the server and removes the session entry from the map.
     *
     * @param event A JsonObject containing the session identifier (UI_EVENT_UUID).
     */
    private void close(JsonObject event)
    {
        try
        {
            if (clientTrackers.containsKey(event.getString(EventBusConstants.UI_EVENT_UUID)))
            {
                var process = clientTrackers.remove(event.getString(EventBusConstants.UI_EVENT_UUID));

                if (process.isAlive())
                {
                    LOGGER.info(String.format("Killing process for UUID : %s, pid : %s", event.getString(UI_EVENT_UUID), process.pid()));

                    process.destroyForcibly();

                    process.getOutputStream().close();

                    process.getInputStream().close();

                    LOGGER.info(String.format("Session is close for %s", event.getString(AIOpsObject.OBJECT_IP)));
                }
            }
            else
            {
                LOGGER.warn(String.format("No Session is present for %s", event.getString(AIOpsObject.OBJECT_IP)));
            }
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }


    }
