package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.config.ConfigConstants;
import com.mindarray.policy.PolicyEngineConstants;
import com.mindarray.util.CodecUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

import static com.mindarray.GlobalConstants.Severity;

public class EventPolicyCacheStore extends AbstractCacheStore
{
    private static final EventPolicyCacheStore STORE = new EventPolicyCacheStore();

    private static final Logger LOGGER = new Logger(EventPolicyCacheStore.class, GlobalConstants.MOTADATA_STORE, "Event Policy Cache Store");
    private final Map<Long, JsonObject> ticks = new ConcurrentHashMap<>();//containing policy id and value as time
    private final AtomicBoolean dirty = new AtomicBoolean();
    private boolean updated = false;

    // Severity tracking maps - similar to MetricPolicyCacheStore
    private final Map<Long, Integer> warningSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> criticalSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> clearSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> downSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> majorSeverities = new ConcurrentHashMap<>();
    private final Map<Long, Integer> unreachableSeverities = new ConcurrentHashMap<>();

    private EventPolicyCacheStore()
    {
    }

    public static EventPolicyCacheStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + PolicyEngineConstants.EVENT_POLICY_TRIGGER_TICKS);

        if (file.exists())
        {
            var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

            if (buffer != null && buffer.getBytes().length > 0)
            {
                var context = new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap();

                ((Map<String, Object>) context.get("trigger.ticks")).forEach((key, value) -> ticks.put(CommonUtil.getLong(key), JsonObject.mapFrom(value)));

                LOGGER.info(String.format("%s loaded from the backup file...", PolicyEngineConstants.EVENT_POLICY_TRIGGER_TICKS));
            }
        }
        else
        {
            Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
        }

        promise.complete();

        LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

        return promise.future();
    }

    public void updateTriggerTicks(long policyId, long tick, JsonObject event)
    {
        ticks.computeIfAbsent(policyId, value -> new JsonObject());

        var context = ticks.get(policyId);

        context.getMap().computeIfAbsent(PolicyEngineConstants.POLICY_FIRST_TRIGGER_TICK, value -> tick * 1000);

        context.put(PolicyEngineConstants.POLICY_LAST_TRIGGER_TICK, tick * 1000);

        context.remove(PolicyEngineConstants.POLICY_ACKNOWLEDGE);

        if (event != null && event.containsKey(ConfigConstants.CONFIG_OBJECT_ID))
        {
            // Store multiple CONFIG_OBJECT_IDs as JsonArray instead of single value
            var configObjectIds = context.getJsonArray(ConfigConstants.CONFIG_OBJECT_ID, new JsonArray());

            var newObjectId = event.getLong(ConfigConstants.CONFIG_OBJECT_ID);

            // Add only if not already present to avoid duplicates
            if (!configObjectIds.contains(newObjectId))
            {
                configObjectIds.add(newObjectId);
            }

            context.put(ConfigConstants.CONFIG_OBJECT_ID, configObjectIds);
        }

        LOGGER.info("Event Policy Trigger Tick Updated for Policy ID: " + policyId + " with Tick: " + tick + " and context: " + context);
        updated = true;
    }

    public void remove(long policyId)
    {
        ticks.remove(policyId);
    }

    public boolean dirty()
    {
        return dirty.get();
    }

    public void setDirty(boolean value)
    {
        dirty.set(value);
    }


    public Map<Long, JsonObject> getTriggerTicks()
    {
        return new HashMap<>(ticks);
    }

    public JsonObject getTriggerTicks(long policyId)
    {
        return ticks.getOrDefault(policyId, new JsonObject());
    }

    public void dump(String path)
    {
        if (updated)
        {
            updated = false;

            dirty.set(true);

            Bootstrap.vertx().fileSystem().writeFileBlocking(path,
                    Buffer.buffer(CodecUtil.compress(new JsonObject().put("trigger.ticks", new HashMap<>(ticks)).encode().getBytes(StandardCharsets.UTF_8))));
        }
    }

    /**
     * Updates severity counts for a specific object/entity based on policy trigger events.
     * This method should be called when event policies are triggered to track severity counts.
     *
     * @param entityId the object/entity ID (typically config.object.id for Network Config policies)
     * @param severity the severity of the triggered policy
     * @param increment true to increment count, false to decrement
     */
    public void updateSeverityCount(long entityId, Severity severity, boolean increment)
    {
        int delta = increment ? 1 : -1;

        switch (severity)
        {
            case CRITICAL -> criticalSeverities.merge(entityId, delta, Integer::sum);
            case WARNING -> warningSeverities.merge(entityId, delta, Integer::sum);
            case MAJOR -> majorSeverities.merge(entityId, delta, Integer::sum);
            case CLEAR -> clearSeverities.merge(entityId, delta, Integer::sum);
            case DOWN -> downSeverities.merge(entityId, delta, Integer::sum);
            case UNREACHABLE -> unreachableSeverities.merge(entityId, delta, Integer::sum);
        }

        // Ensure counts don't go below zero
        criticalSeverities.computeIfPresent(entityId, (k, v) -> Math.max(0, v));
        warningSeverities.computeIfPresent(entityId, (k, v) -> Math.max(0, v));
        majorSeverities.computeIfPresent(entityId, (k, v) -> Math.max(0, v));
        clearSeverities.computeIfPresent(entityId, (k, v) -> Math.max(0, v));
        downSeverities.computeIfPresent(entityId, (k, v) -> Math.max(0, v));
        unreachableSeverities.computeIfPresent(entityId, (k, v) -> Math.max(0, v));
    }

    /**
     * Gets severity counts for multiple objects/entities.
     * Returns a JsonObject with entity IDs as keys and severity counts as values.
     * This method matches the signature and behavior of MetricPolicyCacheStore.getSeveritiesByObject(JsonArray).
     *
     * @param entities JsonArray of entity IDs
     * @return JsonObject containing severity counts for each entity
     */
    public JsonObject getSeveritiesByObject(JsonArray entities)
    {
        var items = new JsonObject();

        for (var index = 0; index < entities.size(); index++)
        {
            var id = entities.getLong(index);

            items.put(CommonUtil.getString(id), new JsonObject()
                .put(Severity.CRITICAL.name().toLowerCase(), criticalSeverities.getOrDefault(id, 0))
                .put(Severity.WARNING.name().toLowerCase(), warningSeverities.getOrDefault(id, 0))
                .put(Severity.MAJOR.name().toLowerCase(), majorSeverities.getOrDefault(id, 0))
                .put(Severity.CLEAR.name().toLowerCase(), clearSeverities.getOrDefault(id, 0))
                .put(Severity.DOWN.name().toLowerCase(), downSeverities.getOrDefault(id, 0))
                .put(Severity.UNREACHABLE.name().toLowerCase(), unreachableSeverities.getOrDefault(id, 0)));
        }

        return items;
    }

    /**
     * Clears severity counts for a specific entity.
     * This should be called when policies are deleted or when an entity is removed.
     *
     * @param entityId the entity ID to clear
     */
    public void clearSeverityCounts(long entityId)
    {
        criticalSeverities.remove(entityId);
        warningSeverities.remove(entityId);
        majorSeverities.remove(entityId);
        clearSeverities.remove(entityId);
        downSeverities.remove(entityId);
        unreachableSeverities.remove(entityId);
    }
}

