package com.mindarray.integration;

import com.mindarray.Bootstrap;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.eventbus.EventEngine;
import com.mindarray.policy.PolicyEngineConstants;
import com.mindarray.runbook.RunbookEngine;
import com.mindarray.store.IntegrationCacheStore;
import com.mindarray.store.IntegrationConfigStore;
import com.mindarray.store.MetricPolicyConfigStore;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.*;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import org.apache.http.HttpStatus;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.ErrorMessageConstants.API_ACCESS_FAILED_NOT_AUTHORIZED;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.ENTITY_ID;
import static com.mindarray.api.Integration.*;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.nms.NMSConstants.INTEGRATIONS_PENDING_EVENTS;

public class IntegrationEngine extends AbstractVerticle {

    private EventEngine integrationEngine;

    private static final Logger LOGGER = new Logger(RunbookEngine.class, "integration", "integration Engine");

    private static final String replyTopic = EVENT_SERVICE_OPS_INTEGRATION + EventBusConstants.EVENT_REPLY;

    private static final String DESCRIPTION_TEMPLATE  = "<ul><li><p>Object Name: <strong>$$$object.name$$$</strong></p></li><li><p>IP / Host: <strong>$$$ip$$$</strong></p></li><li><p>Object Type: <strong>$$$object.type$$$</strong></p></li><li><p>Metric: <strong>$$$metric$$$</strong></p></li><li><p>Metric Value: <strong>$$$metric.value$$$</strong></p></li><li><p>Severity: <strong>$$$severity$$$</strong></p></li><li><p>Policy Name: <strong>$$$policy.name$$$</strong></p></li><li><p>Policy Type: <strong>$$$policy.type$$$</strong></p></li><li><p>Message: <strong>$$$message$$$</strong></p></li></ul>";

    private static final int PENDING_EVENTS_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getPendingEventsFlushTimerSeconds();

    private final AtomicBoolean updated = new AtomicBoolean();

    private final List<JsonObject> pendingEvents = new ArrayList<>();

    private boolean setTimer = false;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + INTEGRATIONS_PENDING_EVENTS);

        if (file.exists())
        {
            var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

            if (buffer != null && buffer.getBytes().length > 0)
            {
                var context = new JsonArray(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes())));

                if(!context.isEmpty())
                {
                    for (var index = 0; index < pendingEvents.size(); index++)
                    {
                        pendingEvents.add(context.getJsonObject(index));
                    }
                }
            }
        }
        else
        {
            Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
        }

        var refreshTimer = new AtomicInteger(PENDING_EVENTS_FLUSH_TIMER_SECONDS);

        vertx.setPeriodic(30 * 1000L, timer ->
        {
            if (updated.get())
            {
                updated.set(false);

                vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + INTEGRATIONS_PENDING_EVENTS,
                        Buffer.buffer(CodecUtil.compress(pendingEvents.toString().getBytes())));
            }

            refreshTimer.set(refreshTimer.get() - 30);

            if (refreshTimer.get() <= 0)
            {
                vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + INTEGRATIONS_PENDING_EVENTS,
                        Buffer.buffer(CodecUtil.compress(pendingEvents.toString().getBytes())));

                refreshTimer.set(PENDING_EVENTS_FLUSH_TIMER_SECONDS);
            }

        });

        vertx.eventBus().<JsonObject>localConsumer(EVENT_INTEGRATION_URL_CHECK_TIMER, message ->

            vertx.setPeriodic(MotadataConfigUtil.getIntegrationURLCheckTimerSeconds() * 1000L,handler->{

                setTimer = true;

                integrationUrlCheck().onComplete(asyncResult ->{

                    if(asyncResult.succeeded())
                    {
                        vertx.cancelTimer(handler);

                        while (!pendingEvents.isEmpty())
                        {
                            send(pendingEvents.remove(0));
                        }

                        setTimer = false;
                    }
                });
            }));

        vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
        {
            var event = message.body();

            if (ChangeNotificationType.valueOf(event.getString(CHANGE_NOTIFICATION_TYPE)) == ChangeNotificationType.UPDATE_INTEGRATION) {

                while (!pendingEvents.isEmpty())
                {
                    send(pendingEvents.remove(0));
                }
            }
        }).exceptionHandler(LOGGER::error);

        integrationEngine = new EventEngine().setEventType(EVENT_SERVICE_OPS_INTEGRATION).setEventQueueSize(20)
                .setBlockingEvent(true).setLogger(LOGGER).setEventHandler(this::send).start(vertx,promise);
    }

    private Future<Void> integrationUrlCheck()
    {
        var promise = Promise.<Void>promise();

        var item = IntegrationConfigStore.getStore().getItemByValue(INTEGRATION_TYPE,IntegrationType.SERVICEOPS.getName());

        vertx.eventBus().<JsonObject>request(EVENT_INTEGRATION_AUTH_TOKEN_CREATE, item.put(EVENT_COPY_REQUIRED, false), result ->
        {
            if (result.succeeded())
            {
                if (result.result().body().containsKey(STATUS) && STATUS_FAIL.equalsIgnoreCase(result.result().body().getString(STATUS)))
                {
                    promise.fail(result.result().body().encode());
                }
                else
                {
                    promise.complete();
                }
            }
            else
            {
                promise.fail(result.cause().getMessage());
            }
        });

        return promise.future();
    }

    public void send(JsonObject event)
    {
        if(event.getString(INTEGRATION_TYPE).equalsIgnoreCase(IntegrationType.SERVICEOPS.getName()))
        {
            var item = IntegrationConfigStore.getStore().getItemByValue(INTEGRATION_TYPE,IntegrationType.SERVICEOPS.getName());

            if(event.containsKey(IntegrationUtil.TICKET_ID)) //Update Ticket
            {
                event.put(INTEGRATION_SERVER_UPDATE_TICKET_URL, item.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? item.getString(INTEGRATION_SERVER_URL) + "api/request/" + event.getString(IntegrationUtil.TICKET_ID) + "/conversation" : item.getString(INTEGRATION_SERVER_URL) + "/" + "api/request/" + event.getString(IntegrationUtil.TICKET_ID) + "/conversation");

                integration(event,item,event.getString(INTEGRATION_SERVER_UPDATE_TICKET_URL),false);
            }
            else  //Create Ticket
            {
                event.put(INTEGRATION_SERVER_CREATE_TICKET_URL, item.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? item.getString(INTEGRATION_SERVER_URL) + "api/v1/request" : item.getString(INTEGRATION_SERVER_URL) + "/" + "api/v1/request");

                integration(event,item,event.getString(INTEGRATION_SERVER_CREATE_TICKET_URL),true);
            }
        }
    }

    private void integration(JsonObject event, JsonObject item, String url, boolean create)
    {
        WebClientUtil.getWebClient().postAbs(url)
                .bearerTokenAuthentication(item.getString("access_token")).putHeader("Content-Type","application/json").sendJsonObject(create ? prepareCreateContext(event,item) : prepareUpdateContext(event), handler ->
                {
                    if (handler.succeeded())
                    {
                        var result = handler.result();

                        if (result.statusCode() == HttpStatus.SC_UNAUTHORIZED)
                        {
                            LOGGER.warn(String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_CREATE_TICKET_URL)));

                            updated.set(true);

                            pendingEvents.add(event);

                        }
                        else if (result.statusCode() == HttpStatus.SC_BAD_REQUEST)
                        {
                            LOGGER.warn(String.format("Invalid credentials for url %s", event.getString(INTEGRATION_SERVER_CREATE_TICKET_URL)));

                            updated.set(true);

                            pendingEvents.add(event);
                        }
                        else if (result.statusCode() == HttpStatus.SC_OK)
                        {
                            if(create)
                            {
                                LOGGER.info(String.format("Ticket: %s created Successfully", result.bodyAsJsonObject().getString("subject")));

                                IntegrationCacheStore.getStore().update(event.getString(PolicyEngineConstants.POLICY_KEY),result.bodyAsJsonObject().getInteger(ID));
                            }
                            else
                            {
                                LOGGER.info(String.format("Ticket: %s updated Successfully", result.bodyAsJsonObject().getString("subject")));
                            }

                            vertx.eventBus().send(replyTopic,result.bodyAsJsonObject());
                        }

                    }
                    else
                    {

                        LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s", event.getString(INTEGRATION_TYPE)));

                        if(!setTimer) //when ServiceOps server goes down, start timer
                        {
                            vertx.eventBus().send(EVENT_INTEGRATION_URL_CHECK_TIMER,new JsonObject());
                        }

                        updated.set(true);

                        pendingEvents.add(event);
                    }
                });
    }
    private JsonObject prepareCreateContext(JsonObject event, JsonObject item)
    {
        var policy = MetricPolicyConfigStore.getStore().getItem(event.getLong(ID));

        var defaultFields = new JsonObject()
                .put("requesterName","Motadata")
                .put("impactName","On department")
                .put("statusName","Open")
                .put("departmentName","IT")
                .put("source","NMS");

        var description = DESCRIPTION_TEMPLATE
                .replace("$$$object.name$$$",event.getString(AIOpsObject.OBJECT_NAME))
                .replace("$$$ip$$$",event.getString(AIOpsObject.OBJECT_IP))
                .replace("$$$object.type$$$",event.getString(AIOpsObject.OBJECT_TYPE))
                .replace("$$$metric$$$",event.getString(METRIC))
                .replace("$$$metric.value$$$",event.getString(VALUE))
                .replace("$$$severity$$$",event.getString(SEVERITY))
                .replace("$$$policy.name$$$",policy.getString(PolicyEngineConstants.POLICY_NAME))
                .replace("$$$policy.type$$$",policy.getString(PolicyEngineConstants.POLICY_TYPE))
                .replace("$$$message$$$",event.getString(MESSAGE)); //add timestamp

        if(event.containsKey(INSTANCE))
        {
            defaultFields.put("subject",event.getString(SEVERITY) + " - " + event.getString(AIOpsObject.OBJECT_NAME) + " (" +event.getString(AIOpsObject.OBJECT_IP) +  ")" + " - " + event.getString(METRIC) + " - " +event.getString(INSTANCE,""));
        }
        else
        {
            defaultFields.put("subject",event.getString(SEVERITY) + " - " + event.getString(AIOpsObject.OBJECT_NAME) + " (" +event.getString(AIOpsObject.OBJECT_IP) +  ")" + " - " + event.getString(METRIC));
        }

        defaultFields.put("requesterEmail",item.getString(USERNAME))
                .put("description",description);

        var urgency = item.getJsonObject("urgency");

        if(urgency != null && !urgency.isEmpty())
        {
            for(var entry : urgency)
            {
                if(event.getString(SEVERITY).equalsIgnoreCase(CommonUtil.getString(entry.getValue())))
                {
                    defaultFields.put("urgencyName",entry.getKey());
                }
            }
        }

        var tags = ObjectConfigStore.getStore().getItem(event.getLong(ENTITY_ID)).getJsonArray(AIOpsObject.OBJECT_USER_TAGS);

        if(!tags.isEmpty())
        {
            defaultFields.put("tags",tags);
        }

        return defaultFields;
    }

    private JsonObject prepareUpdateContext(JsonObject event)
    {
        var policy = MetricPolicyConfigStore.getStore().getItem(event.getLong(ID));

        var defaultValue = new JsonObject()
                .put("conversationType","note")
                .put("noteAsFirstResponse",false)
                .put("conversationState","published");

        var description = DESCRIPTION_TEMPLATE
                .replace("$$$object.name$$$",event.getString(AIOpsObject.OBJECT_NAME))
                .replace("$$$ip$$$",event.getString(AIOpsObject.OBJECT_IP))
