                .replace("$$$policy.type$$$",policy.getString(PolicyEngineConstants.POLICY_TYPE,""))
                .replace("$$$message$$$",event.getString(MESSAGE)); //add timestamp

        defaultValue.put("details",description);

        return defaultValue;
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        integrationEngine.stop(vertx, promise);
    }
