package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.CodecUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.nms.NMSConstants.INTEGRATIONS;

public class IntegrationCacheStore extends AbstractCacheStore
{
    private static final IntegrationCacheStore STORE = new IntegrationCacheStore();

    private static final Logger LOGGER = new Logger(IntegrationCacheStore.class, GlobalConstants.MOTADATA_STORE, "Integration Cache Store");

    private static final int TICKET_IDS_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getTicketIdsFlushTimerSeconds();

    private final Map<String, Integer> ticketIdsByMetricKey = new ConcurrentHashMap<>();

    private final AtomicBoolean updated = new AtomicBoolean();

    private IntegrationCacheStore()
    {
    }

    public static IntegrationCacheStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + INTEGRATIONS);

        if (file.exists())
        {
            var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

            if (buffer != null && buffer.getBytes().length > 0)
            {
                var context = new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))).getMap();

                ((Map<String, Integer>) (context.get("items"))).forEach((key, value) -> ticketIdsByMetricKey.put(CommonUtil.getString(key), CommonUtil.getInteger(value)));

            }
        }
        else
        {
            Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
        }

        if (Bootstrap.bootstrapType() == GlobalConstants.BootstrapType.DEFAULT)
        {

            var refreshTimer = new AtomicInteger(TICKET_IDS_FLUSH_TIMER_SECONDS);

            Bootstrap.vertx().setPeriodic(30 * 1000L, timer ->
            {
                if (updated.get())
                {
                    updated.set(false);

                    Bootstrap.vertx().fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + INTEGRATIONS,
                            Buffer.buffer(CodecUtil.compress(new JsonObject().put("items", new HashMap<>(ticketIdsByMetricKey)).encode().getBytes())));
                }

                refreshTimer.set(refreshTimer.get() - 30);

                if (refreshTimer.get() <= 0)
                {

                    Bootstrap.vertx().fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + INTEGRATIONS,
                            Buffer.buffer(CodecUtil.compress(new JsonObject().put("items", new HashMap<>(ticketIdsByMetricKey)).encode().getBytes())));

                    refreshTimer.set(TICKET_IDS_FLUSH_TIMER_SECONDS);
                }

            });

            promise.complete();

            LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

        }

        else
        {
            promise.fail(String.format("failed to init store %s, reason: invalid boot sequence...", this.getClass().getSimpleName()));
        }

        return promise.future();
    }

    public void update(String key, int ticketId)
    {
        updated.set(true);

        ticketIdsByMetricKey.put(key,ticketId);
    }

    // -1 does not have entry
    // 0  create request is done, waiting for ticket id
    // >1 ticket id
    public int getTicketId(String key)
    {
        return ticketIdsByMetricKey.getOrDefault(key,-1);
    }

}

