    private void createZipFile(int currentMajorVersion, String parentFolder)
    {
        var srcFiles = new String[]{"motadata", "VERSION"};

        var zipFile = CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + "rpe-upgrade.zip";

        try
        {

            deleteFile(zipFile);

            var bytes = new byte[1024];

            var fileOutputStream = new FileOutputStream(zipFile);

            var zipOutputStream = new ZipOutputStream(fileOutputStream);

            for (var file : srcFiles)
            {
                deleteFile(CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + file);

                VERTX.fileSystem().copyBlocking(CURRENT_DIR + PATH_SEPARATOR + file, CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + file);

                if (file.equals("VERSION"))
                {
                    VERTX.fileSystem().writeFileBlocking(CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + file, Buffer.buffer((currentMajorVersion + 1) + ".0.0"));
                }

                var srcFile = new File(CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + file);

                var fis = new FileInputStream(srcFile);

                if (file.equalsIgnoreCase(VERSION_FILE))
                {
                    zipOutputStream.putNextEntry(new ZipEntry(srcFile.getName()));
                }
                else
                {
                    zipOutputStream.putNextEntry(new ZipEntry(parentFolder + PATH_SEPARATOR + srcFile.getName()));
                }

                var length = 0;

                while ((length = fis.read(bytes)) > 0)
                {
                    zipOutputStream.write(bytes, 0, length);
                }

                zipOutputStream.closeEntry();

                fis.close();
            }

            zipOutputStream.close();

        }
        catch (Exception ignored)
        {
        }
    }

    private void deleteFile(String file)
    {
        try
        {
            VERTX.fileSystem().deleteBlocking(file);
        }
        catch (Exception ignored)
        {
        }
    }

