    @Override
    protected Future<JsonObject> getReferencesPreHook(RoutingContext routingContext, JsonObject response)
    {
        try
        {
            var id = CommonUtil.getLong(routingContext.request().getParam(ID));

            var metrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_CREDENTIAL_PROFILE, id);

            for (var index = 0; index < metrics.size(); index++)
            {
                var metric = metrics.getJsonObject(index);

                if (NMSConstants.CUSTOM_METRIC_TYPES.contains(metric.getString(Metric.METRIC_TYPE))) // custom metric category
                {
                    addEntity(response, APIConstants.Entity.METRIC.getName());

                    response.getJsonArray(APIConstants.Entity.METRIC.getName()).add(enrich(metric, routingContext.user().principal().getLong(ID)));
                }

                else if (NMSConstants.isBaseTypeMetricPlugin(metric.getString(Metric.METRIC_PLUGIN)) || NMSConstants.CLOUD_PLUGINS.contains(metric.getString(Metric.METRIC_PLUGIN))) // if parent metric plugin or cloud type than only send UI
                {
                    if (NMSConstants.APPLICATION_TYPES.contains(metric.getString(Metric.METRIC_TYPE)))
                    {
                        addEntity(response, NMSConstants.APPS);

                        var item = enrich(metric, routingContext.user().principal().getLong(ID));

                        if (item.containsKey(AIOpsObject.OBJECT_HOST))
                        {
                            response.getJsonArray(NMSConstants.APPS).add(item);
                        }
                    }

                    else
                    {
                        addEntity(response, APIConstants.Entity.OBJECT.getName());

                        var item = enrich(metric, routingContext.user().principal().getLong(ID));

                        if (item.containsKey(AIOpsObject.OBJECT_HOST) || Category.CLOUD.getName().equals(item.getString(Metric.METRIC_CATEGORY)))
                        {
                            response.getJsonArray(APIConstants.Entity.OBJECT.getName()).add(item);
                        }
                    }
                }
            }

            //Now as we have introduced OAuth credentials that will be used in integrations like teams,slack,GCP so adding integrations profile used count in it
            var items = IntegrationConfigStore.getStore().getItemsByMapValueField(Integration.INTEGRATION_CONTEXT, IntegrationProfile.INTEGRATION_CREDENTIAL_PROFILE, id);

            for (var index = 0; index < items.size(); index++)
            {
                var item = items.getJsonObject(index);

                item.remove(Integration.INTEGRATION_ATTRIBUTES);

                addEntity(response, APIConstants.Entity.INTEGRATION.getName());

                response.getJsonArray(APIConstants.Entity.INTEGRATION.getName()).add(item);
            }


            if (response != null && !response.isEmpty() && response.containsKey(APIConstants.Entity.CONFIGURATION.getName()))
            {
                var entities = response.getJsonArray(APIConstants.Entity.CONFIGURATION.getName());

                for (var index = 0; index < entities.size(); index++)
                {
                    var item = entities.getJsonObject(index);

                    var object = ObjectConfigStore.getStore().getItemByValue(AIOpsObject.OBJECT_ID, item.getInteger(Configuration.CONFIG_OBJECT));

                    ConfigConstants.removeGarbageFields(object);

                    item.mergeIn(object);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
        return Future.succeededFuture(response);
    }

    private void addEntity(JsonObject response, String entity)
    {
        if (!response.containsKey(entity))
        {
            response.put(entity, new JsonArray());
        }
    }

    /*Method will now first check if object is part of groups allowed to user or not
     */
    private JsonObject enrich(JsonObject item, long userId)
    {
        var items = ObjectConfigStore.getStore().getItemsByUserScope(userId, new JsonArray().add(item.getLong(Metric.METRIC_OBJECT)));

        var object = items.isEmpty() ? null : ObjectConfigStore.getStore().getItem(items.getLong(0));

        if (object != null)
        {
            NMSConstants.enrich(object);

            item.mergeIn(object);
        }

        return item;
    }

    @Override
    protected Future<JsonObject> getEntityCountPreHook(JsonObject response)
    {
        try
        {
            var ids = CredentialProfileConfigStore.getStore().getIds();

            for (var count = 0; count < ids.size(); count++)
            {
                var metrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_CREDENTIAL_PROFILE, ids.getLong(count));

                var references = 0;

                for (var index = 0; index < metrics.size(); index++)
                {
                    var metric = metrics.getJsonObject(index);

                    // 1. custom metric category
                    // 2. if parent metric plugin than only send UI
                    //3 . for cloud category qualify instances reference
                    if (NMSConstants.CUSTOM_METRIC_TYPES.contains(metric.getString(Metric.METRIC_TYPE)))
                    {
                        references++;
                    }

                    if (NMSConstants.isBaseTypeMetricPlugin(metric.getString(Metric.METRIC_PLUGIN))
                            || NMSConstants.CLOUD_PLUGINS.contains(metric.getString(Metric.METRIC_PLUGIN)))
                    {
                        var item = enrich(metric, response.getLong(USER_ID));

                        if (item.containsKey(AIOpsObject.OBJECT_HOST) || Category.CLOUD.getName().equals(item.getString(Metric.METRIC_CATEGORY)))
                        {
                            references++;
                        }
                    }
                }

                references += IntegrationConfigStore.getStore().getItemsByMapValueField(Integration.INTEGRATION_CONTEXT, IntegrationProfile.INTEGRATION_CREDENTIAL_PROFILE, ids.getLong(count)).size();

                response.put(CommonUtil.getString(ids.getLong(count)),
                        response.containsKey(CommonUtil.getString(ids.getLong(count))) ? response.getInteger(CommonUtil.getString(ids.getLong(count))) + references : references);
            }
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture(response);
    }

    @Override
    protected Future<JsonObject> beforeCreate(RoutingContext routingContext)
    {
        var requestBody = routingContext.body().asJsonObject();

        var promise = Promise.<JsonObject>promise();

        if (requestBody.containsKey(CREDENTIAL_PROFILE_PROTOCOL) && NMSConstants.Protocol.HTTP_HTTPS.getName().equalsIgnoreCase(requestBody.getString(CREDENTIAL_PROFILE_PROTOCOL)))
        {
            prepareContext(requestBody, promise);
        }
        else
        {
            promise.complete(requestBody);
        }

        return promise.future();
    }

    private void prepareContext(JsonObject requestBody, Promise<JsonObject> promise)
    {
        try
        {
            var context = requestBody.getJsonObject(CREDENTIAL_PROFILE_CONTEXT);

            if (context.containsKey(OAuthUtil.AUTHENTICATION_TYPE) && NMSConstants.AuthenticationType.OAUTH.getName().equalsIgnoreCase(context.getString(OAuthUtil.AUTHENTICATION_TYPE)) && context.containsKey(SESSION_ID) && NMSConstants.OAuthGrantType.AUTHORIZATION_CODE.getName().equalsIgnoreCase(context.getString(OAuthUtil.GRANT_TYPE)))
            {
                Bootstrap.vertx().eventBus().<JsonObject>request(EventBusConstants.EVENT_OAUTH_CONTEXT_FETCH, context,
                        new DeliveryOptions().setSendTimeout(2 * 1000L),
                        reply ->
                        {
                            if (reply.succeeded())
                            {
                                context.mergeIn(reply.result().body());

                                context.remove(SESSION_ID);

                                promise.complete(requestBody);
                            }
                            else
                            {
                                promise.fail(reply.cause());
                            }
                        });
            }
            else if (context.containsKey(OAuthUtil.AUTHENTICATION_TYPE) && AuthenticationType.CERTIFICATE.getName().equalsIgnoreCase(context.getString(OAuthUtil.AUTHENTICATION_TYPE)) && context.containsKey(CLIENT_CERTIFICATE_CONFIGURATION))
            {
                if (context.getString(CLIENT_CERTIFICATE_CONFIGURATION).equalsIgnoreCase(ConfigurationType.UPLOAD.getName()))
                {
                    if (context.containsKey(CLIENT_CERTIFICATE_FILE) && context.containsKey(CLIENT_KEY_FILE) && context.containsKey(CERTIFICATE_AUTHORITY_FILE))
                    {
                        context.put(CLIENT_KEY, new String(Base64.decodeBase64(Bootstrap.vertx().fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.UPLOADS + GlobalConstants.PATH_SEPARATOR + context.getJsonObject(CLIENT_KEY_FILE).getString(RESULT)).toString())));

                        context.put(CLIENT_CERTIFICATE, new String(Base64.decodeBase64(Bootstrap.vertx().fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.UPLOADS + GlobalConstants.PATH_SEPARATOR + context.getJsonObject(CLIENT_CERTIFICATE_FILE).getString(RESULT)).toString())));

                        context.put(CERTIFICATE_AUTHORITY, new String(Base64.decodeBase64(Bootstrap.vertx().fileSystem().readFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.UPLOADS + GlobalConstants.PATH_SEPARATOR + context.getJsonObject(CERTIFICATE_AUTHORITY_FILE).getString(RESULT)).toString())));

                        promise.complete(requestBody);
                    }
                    else
                    {
                        promise.fail("Missing required certificate files");
                    }
                }
                else if (context.getString(CLIENT_CERTIFICATE_CONFIGURATION).equalsIgnoreCase(ConfigurationType.MANUAL.getName()))
                {
                    if (context.containsKey(CLIENT_CERTIFICATE) && context.containsKey(CLIENT_KEY) && context.containsKey(CERTIFICATE_AUTHORITY))
                    {
                        context.put(CLIENT_KEY, new String(Base64.decodeBase64(context.getString(CLIENT_KEY))));

                        context.put(CLIENT_CERTIFICATE, new String(Base64.decodeBase64(context.getString(CLIENT_CERTIFICATE))));

                        context.put(CERTIFICATE_AUTHORITY, new String(Base64.decodeBase64(context.getString(CERTIFICATE_AUTHORITY))));

                        promise.complete(requestBody);
                    }
                    else
                    {
                        promise.fail("Missing required certificate fields");
                    }
                }
                else
                {
                    promise.fail("Invalid certificate configuration");
                }
            }
            else
            {
                promise.complete(requestBody);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
    }
