                }
            }).exceptionHandler(LOGGER::error);

            subscriber.setHWM(MotadataConfigUtil.getEventBacklogSize());

            subscriber.setRcvHWM(MotadataConfigUtil.getEventBacklogSize());

            subscriber.subscribe(remoteEventTopic);

