import static com.mindarray.ErrorMessageConstants.API_ACCESS_FAILED_NOT_AUTHORIZED;
import static com.mindarray.ErrorMessageConstants.CREDENTIAL_ERROR;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.InfoMessageConstants.INTEGRATION_PROFILE_TEST_SUCCEEDED;
import static com.mindarray.api.IntegrationProfile.*;

public class IntegrationUtil extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(IntegrationUtil.class, GlobalConstants.MOTADATA_UTIL, "Integration Util");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {

        if (!IntegrationProfileConfigStore.getStore().getItems().isEmpty())
        {
            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_INTEGRATION_AUTH_TOKEN_CREATE, handler ->{

                var event = handler.body();

                var form = MultipartForm.create().attribute(USERNAME,event.getString(USERNAME)).attribute(PASSWORD,event.getString(PASSWORD)).attribute("grant_type",PASSWORD);

                WebClientUtil.getWebClient().postAbs(event.getString(INTEGRATION_SERVER_TOKEN_URL)).timeout(event.getInteger(INTEGRATION_SERVER_URL_TIMEOUT) * 1000)
                        .putHeader("Authorization",event.getString(INTEGRATION_AUTH_TOKEN)).sendMultipartForm(form,message ->{

                            if(message.succeeded())
                            {
                                var result = message.result();

                                if(result.statusCode() == HttpStatus.SC_UNAUTHORIZED)
                                {
                                    LOGGER.warn(String.format(API_ACCESS_FAILED_NOT_AUTHORIZED,event.getString(INTEGRATION_SERVER_TOKEN_URL)));

                                    handler.reply(new JsonObject().put(STATUS,STATUS_FAIL).put(ERROR,String.format(API_ACCESS_FAILED_NOT_AUTHORIZED,event.getString(INTEGRATION_SERVER_TOKEN_URL))).put(MESSAGE,"Integration test failed"));
                                }
                                else if (result.statusCode() == HttpStatus.SC_BAD_REQUEST)
                                {
                                    LOGGER.warn(String.format("Credential invalid for %s integration",event.getString(INTEGRATION_TYPE)));

                                    handler.reply(new JsonObject().put(STATUS,STATUS_FAIL).put(ERROR,CREDENTIAL_ERROR).put(MESSAGE,"Integration test failed"));
                                }
                                else if(result.statusCode() == HttpStatus.SC_OK)
                                {
                                    LOGGER.info(String.format(INTEGRATION_PROFILE_TEST_SUCCEEDED,event.getString(INTEGRATION_TYPE)));

                                    handler.reply(result.bodyAsJsonObject().put(STATUS,STATUS_SUCCEED).put(MESSAGE,"Integration test successful"));
                                }
                            }
                            else
                            {
                                handler.fail(HttpStatus.SC_INTERNAL_SERVER_ERROR,message.cause().getMessage());

                                LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s",event.getString(INTEGRATION_TYPE)));
                            }
                        });
            });
        }

        promise.complete();
    }

    @Override
    public void stop(Promise<Void> promise)
    {
        promise.complete();
    }
}

