        var objectIds = new JsonArray();

        for (var entry : items.entrySet())
        {
            if(entry.getValue().getString(OBJECT_STATE).equalsIgnoreCase(NMSConstants.State.ARCHIVE.name()))
            {
                objectIds.add(entry.getValue().getInteger(OBJECT_ID));
            }
        }

        return objectIds;
