package com.mindarray.visualization;


import com.mindarray.Bootstrap;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.GlobalConstants;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import org.apache.commons.lang3.math.NumberUtils;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.EVENT_VISUALIZATION;
import static com.mindarray.eventbus.EventBusConstants.UI_EVENT_UUID;
import static com.mindarray.visualization.VisualizationConstants.*;

public class VisualizationMetricResponseProcessor extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(VisualizationMetricResponseProcessor.class, GlobalConstants.MOTADATA_VISUALIZATION, "Visualization Metric Response Processor");

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_VISUALIZATION_METRIC_RESPONSE_PROCESSOR, message ->
            {
                var event = message.body();

                if (!event.isEmpty())
                {
                    try
                    {
                        var context = event.getJsonObject(QUERY_CONTEXT);

                        if (event.containsKey("child.query"))
                        {
                            composeSubQueryResponse(event.getLong(QUERY_ID),context, event.getJsonObject(RESULT), event.getString(VISUALIZATION_CATEGORY),event.getJsonObject("column.mappers", new JsonObject()));
                        }

                        else
                        {
                            composeQueryResponse(event.getJsonObject("column.mappers", new JsonObject()), event.getInteger(QUERY_PROGRESS), event.getJsonObject(RESULT), event.getString(VISUALIZATION_CATEGORY, VisualizationCategory.GRID.getName()), event.getLong(QUERY_ID), event.getLong(VisualizationConstants.SUB_QUERY_ID), context, LOGGER, event.getJsonObject(QUERY_CONTEXT).containsKey(DUMMY_FIELDS) ? event.getJsonObject(QUERY_CONTEXT).getBoolean(DUMMY_FIELDS) : false);
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        promise.complete();
    }

    private void composeSubQueryResponse(long queryId,JsonObject context, JsonObject response, String category,JsonObject metricColumns)
    {
        try
        {
            JsonObject visualizationContext = null;

            var instance = response.getString(INSTANCE);

            var desc = true;

            var aggregators = new HashSet<String>(context.getJsonArray("aggregators",new JsonArray()).getList());

            if (response.containsKey(RESULT) && !response.getJsonArray(RESULT).isEmpty())
            {
                var rows = response.getJsonArray(RESULT);

                var visualizationProperties = context.getJsonObject(VISUALIZATION_PROPERTIES);

                for (var visualizationProperty : visualizationProperties.getMap().values())
                {
                    var value = JsonObject.mapFrom(visualizationProperty);

                    if (value.containsKey(SORTING))
                    {
                        desc = value.getJsonObject(SORTING).getString("order").equalsIgnoreCase("desc");
                    }
                }

                if (category.equalsIgnoreCase(VisualizationCategory.HISTOGRAM.getName()))
                {
                    visualizationContext = new JsonObject(VISUALIZATION_CHART_CONTEXT);

                    visualizationContext.getJsonObject(VISUALIZATION_PROPERTIES).getJsonObject(VisualizationCategory.HISTOGRAM.getName().toLowerCase()).getJsonObject(SORTING).put("order", desc ? "desc" : "asc");

                    visualizationContext.getJsonObject(VISUALIZATION_PROPERTIES).mergeIn(context.getJsonObject(VISUALIZATION_PROPERTIES));
                }
                else if (category.equalsIgnoreCase(VisualizationCategory.GRID.getName()))
                {
                    visualizationContext = new JsonObject(VISUALIZATION_GRID_CONTEXT);

                    visualizationContext.getJsonObject(VISUALIZATION_PROPERTIES).mergeIn(context.getJsonObject(VISUALIZATION_PROPERTIES));
                }

                var entityType = VisualizationConstants.VisualizationGrouping.MONITOR.getName();

                if (context.getJsonArray(VisualizationConstants.VISUALIZATION_RESULT_BY).isEmpty())
                {
                    context.remove(VisualizationConstants.VISUALIZATION_RESULT_BY);
                }

                else
                {
                    if (context.getJsonArray(VisualizationConstants.VISUALIZATION_RESULT_BY).contains(VisualizationConstants.VisualizationGrouping.GROUP.getName()))
                    {
                        entityType = VisualizationConstants.VisualizationGrouping.GROUP.getName();
                    }

                    else if (context.getJsonArray(VisualizationConstants.VISUALIZATION_RESULT_BY).contains(VisualizationConstants.VisualizationGrouping.TAG.getName()))
                    {

                        entityType = VisualizationConstants.VisualizationGrouping.TAG.getName();
                    }
                }

                var gridStats = new HashMap<String, double[]>(8);

                 var dataSources = context.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES);

                //in case of previous result as Histogram will be directly generating result with min max avg and sum values from chart result received from DB where Grid request cannot be sent to DB as no result by is there
                if (!dataSources.getJsonObject(0).containsKey(VISUALIZATION_RESULT_BY) && context.getString(VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationCategory.HISTOGRAM.getName()))
                {
                    for (var i = 0; i < rows.size(); i++)
                    {
                        var row = rows.getJsonObject(i);

                        for (var entry:row.getMap().entrySet())
                        {
                            if (entry.getKey().contains(CARET_SEPARATOR) && entry.getValue() != null)
                            {
                                var value = CommonUtil.getDouble(entry.getValue());

                                var stats = gridStats.computeIfAbsent(entry.getKey().split(CARET_SEPARATOR_WITH_ESCAPE)[0].trim(),val -> new double[]{value, value, value, 1.0});

                                if (value < stats[0]) stats[0] = value;  // min

                                if (value > stats[1]) stats[1] = value;  // max

                                stats[2] += value;                          // sum

                                stats[3]++;                                    // count
                            }
                        }
                    }
                }

                var entities = new HashSet<>();

                var entityKeys = new HashSet<String>();

                if (gridStats.isEmpty())
                {
                    for (var i = 0; i < rows.size(); i++)
                    {
                        var row = rows.getJsonObject(i);

                        if (!instance.isEmpty() && row.getValue(instance) != null)
                        {
                            entityKeys.add(row.getValue(entityType) + CARET_SEPARATOR + row.getValue(instance));
                        }

                        if (entityType.equalsIgnoreCase(VisualizationConstants.VisualizationGrouping.MONITOR.getName()))
                        {
                            var id = -1L;

                            //in case of previous result as Histogram will be directly splitting entities will be adding monitor as entities received from DB
                            if (context.getString(VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationCategory.HISTOGRAM.getName()))
                            {
                                for (var entry:row.getMap().entrySet())
                                {
                                    if (entry.getKey().contains(GROUP_SEPARATOR))
                                    {
                                        var tokens = entry.getKey().split(GROUP_SEPARATOR);

                                        id = ObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(tokens[0].trim()));

                                        entityKeys.add(CommonUtil.getInteger(tokens[0].trim()) + CARET_SEPARATOR + tokens[1].split(CARET_SEPARATOR_WITH_ESCAPE)[0].trim());
                                    }
                                    else if (entry.getKey().contains(CARET_SEPARATOR))
                                    {
                                        id = ObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(NumberUtils.isParsable(entry.getKey().split(CARET_SEPARATOR_WITH_ESCAPE)[0]) ? entry.getKey().split(CARET_SEPARATOR_WITH_ESCAPE)[0].trim() : -1));
                                    }

                                    if (id != -1L)
                                    {
                                        entities.add(id);
                                    }
                                }

                                break;
                            }
                            else
                            {
                                id = ObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(row.getValue("monitor")));

                                if (id != -1L)
                                {
                                    entities.add(id);
                                }
                            }
                        }
                        else
                        {
                            //in case of previous result as Histogram will be directly splitting entities will be adding tag or group as entities received from DB
                            if (context.getString(VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationCategory.HISTOGRAM.getName()))
                            {
                                for (var entry:row.getMap().entrySet())
                                {
                                    var entity = EMPTY_VALUE;

                                    if (entry.getKey().contains(CARET_SEPARATOR))
                                    {
                                        entity = entry.getKey().split(CARET_SEPARATOR_WITH_ESCAPE)[0].trim();
                                    }

                                    if (!entity.isEmpty())
                                    {
                                        entities.add(entity);
                                    }
                                }

                                break;
                            }
                            else
                            {
                                entities.add(row.getValue(entityType));
                            }
                        }
                    }
                }

                if (visualizationContext != null)
                {
                    for (var i = 0; i < dataSources.size(); i++)
                    {
                        var visualizationDataSource = dataSources.getJsonObject(i);

                        visualizationDataSource.remove(ENTITIES);

                        var dataPoints = visualizationDataSource.getJsonArray(VisualizationConstants.DATA_POINTS);

                        JsonObject externalGrouping = null;

                        if (!entityType.equalsIgnoreCase(VisualizationConstants.VisualizationGrouping.MONITOR.getName()))
                        {
                            externalGrouping = (JsonObject) visualizationDataSource.remove(entityType);

                            visualizationDataSource.put(entityType, new JsonObject());
                        }

                        if (!aggregators.isEmpty())
                        {
                            var aggregatedDataPoints = new JsonArray();

                            for (var aggregator : aggregators)
                            {
                                for (var j = 0; j < dataPoints.size(); j++)
                                {
                                    var dataPoint = dataPoints.getJsonObject(j);

                                    dataPoint.put(AGGREGATOR,aggregator);

                                    aggregatedDataPoints.add(new JsonObject().mergeIn(dataPoint));
                                }
                            }

                            dataPoints = aggregatedDataPoints;
                        }

                        var plugins = (JsonArray)visualizationDataSource.remove(PLUGINS);

                        var points = new JsonArray();

                        for (var j = 0; j < dataPoints.size(); j++)
                        {
                            var dataPoint = dataPoints.getJsonObject(j);

                            Map<String, String> keys;

                            dataPoint.remove(ENTITY_KEYS);

                            if (externalGrouping != null)
                            {
                                var externalEntities = new HashSet<>();

                                for (var entity : entities)
                                {
                                    externalEntities.addAll(ObjectConfigStore.getStore().getItemsByObjectIds(externalGrouping.getJsonArray(CommonUtil.getString(entity)).getList()).getList());

                                    visualizationDataSource.getJsonObject(entityType).put(CommonUtil.getString(entity), externalGrouping.getJsonArray(CommonUtil.getString(entity)));
                                }

                                dataPoint.put(ENTITIES, new ArrayList<>(externalEntities));
                            }

                            else
                            {
                                dataPoint.put(ENTITIES, new ArrayList<>(entities));

                            }

                            dataPoint.put(ENTITY_TYPE, VisualizationConstants.VisualizationGrouping.MONITOR.getName());

                            if (!entityKeys.isEmpty())
                            {
                                keys = new HashMap<>();

                                for (var plugin : plugins)
                                {
                                    for (var key : entityKeys)
                                    {
                                        keys.put(key + CARET_SEPARATOR + dataPoint.getString(DATA_POINT), CommonUtil.getString(plugin));
                                    }
                                }

                                dataPoint.put(ENTITY_KEYS, keys);
                            }

                            points.add(new JsonObject().mergeIn(dataPoint));
                        }

                        visualizationDataSource.put(DATA_POINTS,points);
                    }

                    visualizationContext.put(VISUALIZATION_TIMELINE, context.getValue(VISUALIZATION_TIMELINE))
                            .put(VISUALIZATION_TYPE_CHILD_VISUALIZATION, context.getString(VISUALIZATION_TYPE_CHILD_VISUALIZATION)).put(UI_EVENT_UUID, context.getString(UI_EVENT_UUID))
                            .put(VISUALIZATION_DATA_SOURCES, context.getJsonArray(VisualizationConstants.VISUALIZATION_DATA_SOURCES)).put(QUERY_ID, queryId);

                    if (!gridStats.isEmpty())
                    {
                        var result = new JsonObject();

                        //as per selected aggregation from UI in widget will be sending that particular aggregation result to UI
                        gridStats.forEach((columnName, stats) ->
                        {
                            var mapper = metricColumns.getJsonObject(columnName);

                            if (aggregators.contains(DatastoreConstants.AggregationType.MIN.getName()))
                            {
                                result.getMap().computeIfAbsent(columnName+CARET_SEPARATOR+DatastoreConstants.AggregationType.MIN.getName(),  val -> new JsonArray().add(CommonUtil.getLong(stats[0])));
                            }

                            if (aggregators.contains(DatastoreConstants.AggregationType.MAX.getName()))
                            {
                                result.getMap().computeIfAbsent(columnName+CARET_SEPARATOR+DatastoreConstants.AggregationType.MAX.getName(),  val -> new JsonArray().add(CommonUtil.getLong(stats[1])));
                            }

                            if (aggregators.contains(DatastoreConstants.AggregationType.SUM.getName()))
                            {
                                result.getMap().computeIfAbsent(columnName+CARET_SEPARATOR+DatastoreConstants.AggregationType.SUM.getName(),  val -> new JsonArray().add(mapper.getJsonArray(DatastoreConstants.MAPPER_DATA_CATEGORIES).contains(DatastoreConstants.DataCategory.FLOAT.ordinal()) ? CommonUtil.getFloat(stats[2]) : CommonUtil.getLong(stats[2])));
                            }

                            if (aggregators.contains(DatastoreConstants.AggregationType.AVG.getName()))
                            {
                                result.getMap().computeIfAbsent(columnName+CARET_SEPARATOR+DatastoreConstants.AggregationType.AVG.getName(),  val -> new JsonArray().add(mapper.getJsonArray(DatastoreConstants.MAPPER_DATA_CATEGORIES).contains(DatastoreConstants.DataCategory.FLOAT.ordinal()) ? CommonUtil.getFloat(stats[2] / stats[3]) : CommonUtil.getLong(stats[2] / stats[3])));
                            }
                        });

                        visualizationContext.put(RESULT,result);
                    }

                    //in case where request from widget where we get ID > 0 so adding it in context also passing passover.datasource in which considering datasource with custom request not from saved widget
                    if (context.getLong(ID,-1L) > 0)
                    {
                        visualizationContext.put(ID, context.getLong(ID));
                    }

                    Bootstrap.vertx().eventBus().send(EVENT_VISUALIZATION, visualizationContext.put("passover.datasource",YES));
                }
            }
            else
            {
                VisualizationConstants.send(context.getString(VisualizationConstants.VISUALIZATION_CATEGORY), context.getString(VisualizationConstants.VISUALIZATION_TYPE), null, String.format(ErrorMessageConstants.VISUALIZATION_QUERY_FAILED, context.getLong(ID) > 0 ? context.getString(VisualizationConstants.VISUALIZATION_NAME) : "Preview Widget", "No Data Found"), queryId, response.getLong(SUB_QUERY_ID), LOGGER, EventBusConstants.EVENT_VISUALIZATION_RESPONSE);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
}

