@ExtendWith(VertxExtension.class)
@Timeout(220 * 1000)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@EnabledIfSystemProperty(named = "system.bootstrap.type", matches = "APP")
public class TestCloudObjectPoller
{

    private static final JsonObject POLLER_CONTEXT = new JsonObject();

    @BeforeAll
    static void beforeAll(VertxTestContext testContext)
    {

        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "src" + GlobalConstants.PATH_SEPARATOR
                    + "test" + GlobalConstants.PATH_SEPARATOR + "resources" + GlobalConstants.PATH_SEPARATOR + "poll-parameters.json");

            if (file.exists())
            {
                TestUtil.startEventStreaming(new JsonObject().put(EventBusConstants.EVENT_STATE, EventBusConstants.EVENT_STATE_COMPLETED));

                POLLER_CONTEXT.mergeIn(new JsonObject(Files.readString(file.toPath(), StandardCharsets.UTF_8)));

                testContext.completeNow();
            }
        }
        catch (Exception exception)
        {
            testContext.failNow(exception.getMessage());

            exception.printStackTrace();
        }
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    void testPollAWSCloudMetric(VertxTestContext testContext, TestInfo testInfo)
    {
        var metric = TestNMSUtil.prepareMetricPollContext(new JsonObject().put(GlobalConstants.ID, ObjectConfigStore.getStore().getItemByTarget(POLLER_CONTEXT.getString(testInfo.getTestMethod().get().getName()))).put(Metric.METRIC_PLUGIN, NMSConstants.MetricPlugin.AWS_CLOUD.getName()), testContext);

        TestNMSUtil.assertMetricPollResponseTestResult(metric, testContext);
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(2)
    void testPollAWSCloudBillingMetric(VertxTestContext testContext, TestInfo testInfo)
    {
        var metric = TestNMSUtil.prepareMetricPollContext(new JsonObject().put(GlobalConstants.ID, ObjectConfigStore.getStore().getItemByTarget(POLLER_CONTEXT.getString(testInfo.getTestMethod().get().getName()))).put(Metric.METRIC_PLUGIN, NMSConstants.MetricPlugin.AWS_BILLING.getName()), testContext);

        TestNMSUtil.assertMetricPollResponseTestResult(metric, testContext);
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(3)
    void testPollAWSEC2Metric(VertxTestContext testContext, TestInfo testInfo) throws InterruptedException
    {
        var metric = TestNMSUtil.prepareMetricPollContext(MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_TYPE, POLLER_CONTEXT.getString(testInfo.getTestMethod().get().getName())).getJsonObject(0));

        metric.put(AIOpsObject.OBJECT_REGION, "ap-south-1").put(AIOpsObject.OBJECT_TARGET, "ServiceOps_Saas_AMI(ap-south-1)");

        TestNMSUtil.assertMetricPollResponseTestResult(metric, testContext);
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(4)
    void testPollAWSSNSMetric(VertxTestContext testContext, TestInfo testInfo)
