 */

package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.db.DBConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.store.RemoteEventProcessorCacheStore;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.*;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import org.zeromq.SocketType;
import org.zeromq.ZMQ;

import java.util.concurrent.atomic.AtomicBoolean;

import static com.mindarray.db.DBConstants.OPERATION_TYPE;
import static com.mindarray.eventbus.EventBusConstants.*;

public class EventSubscriber extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(EventSubscriber.class, GlobalConstants.MOTADATA_EVENT_BUS, "Event Subscriber");

    private final ZMQ.Socket subscriber;

    private final int subscriberPort;

    private final String subscriberType;

    private final AtomicBoolean hasMoreEvent = new AtomicBoolean(true);

    public EventSubscriber(int port, String type)
    {
        subscriber = Bootstrap.zcontext().socket(SocketType.PULL);

        subscriberPort = port;

        subscriberType = type;
    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var cipherUtil = new CipherUtil();

        vertx.eventBus().<byte[]>localConsumer(EVENT_REMOTE, message ->
        {
            try
            {
                if (message.body() != null && message.body().length > 0)
                {
                    var buffer = Buffer.buffer(message.body());

                    var position = 0;

                    var topic = buffer.getString(2, buffer.getShortLE(0) + 2);

                    position = 2 + buffer.getShortLE(0);

                    if (topic.contains(REMOTE_EVENT_PROCESSOR_TOPIC) || topic.contains(HA_TOPIC))
                    {
                        var event = CodecUtil.toJSONObject(cipherUtil.decrypt(buffer.getBytes(position, buffer.length())));

                        switch (event.getString(EVENT_TYPE))
                        {
                            // event processor register / event acknowledge event
                            case EVENT_REGISTRATION -> vertx.eventBus().send(event.getString(EVENT_TYPE), event);

                            case EVENT_ACKNOWLEDGEMENT -> vertx.eventBus().publish(event.getString(EVENT_TYPE), event);

                            case EVENT_ENGINE_STATISTICS ->
                                    vertx.eventBus().publish(EVENT_ENGINE_STATISTICS_RESPONSE, event);

                            //remote event discovery response
                            case EVENT_DISCOVERY -> vertx.eventBus().send(EVENT_DISCOVERY_RESPONSE, event);

                            //remote event metric poll response
                            case EVENT_METRIC_POLL -> vertx.eventBus().publish(EVENT_METRIC_POLL_RESPONSE, event);

                            //remote event rediscovery response
                            case EVENT_REDISCOVER -> vertx.eventBus().send(EVENT_REDISCOVER_RESPONSE, event);

                            //remote event topology response
                            case EVENT_TOPOLOGY -> vertx.eventBus().send(EVENT_TOPOLOGY_RESPONSE, event);

                            //event processor heartbeat event
                            case EVENT_REMOTE_PROCESSOR_HEARTBEAT ->
                            {
                                if (CommonUtil.isNotNullOrEmpty(event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                        && RemoteEventProcessorConfigStore.getStore().getItemUUIDByType(event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID),event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE)) != null)
                                {
                                    RemoteEventProcessorCacheStore.getStore().updateDuration(RemoteEventProcessorConfigStore.getStore().getItemUUIDByType(event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID),event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE)), event.getLong(GlobalConstants.DURATION));
                                }
                            }

                            //remote event plugin engine response
                            case EVENT_PLUGIN_ENGINE ->
                            {
                                if (event.containsKey(WorkerUtil.WORKER_CONTEXT)) // worker id tracker
                                {
                                    vertx.eventBus().send(EVENT_STREAMING_WORKER_TRACKER, event);
                                }
                                else
                                {
                                    vertx.eventBus().send(EVENT_PLUGIN_ENGINE_RESPONSE, event);
                                }
                            }

                            case EVENT_LOG -> vertx.eventBus().send(EVENT_LOG_PROCESS, event);

                            case EVENT_HA_SYNC_READ ->
                                {
                                    if (event.getInteger(OPERATION_TYPE) == DBConstants.OperationType.DATA_READ.getName().intValue())
                                    {
                                        vertx.eventBus().publish(EVENT_DATASTORE_REQUEST + GlobalConstants.DOT_SEPARATOR + event.getString(DBConstants.DATASTORE_CATEGORY), event);
                                    }
                                }

                            case EVENT_HA_SYNC_ACKNOWLEDGEMENT,EVENT_HA_SYNC_WRITE,EVENT_HA_SYNC_FLUSH ->
                                    vertx.eventBus().send(event.getString(EVENT_TYPE), event);

                            case EVENT_HOT_SWAPPING ->
                            {
                                LOGGER.info(String.format("event received for hot swapping %s ",event.getJsonArray(NMSConstants.OBJECTS)));

                                Bootstrap.restartVerticle(event.getJsonArray(NMSConstants.OBJECTS));
                            }

                            default -> vertx.eventBus().send(CommonUtil.getString(event.remove(EVENT_TYPE)), event);
                        }
                    }

                    else if (topic.contains(DATASTORE_QUERY_RESPONSE_TOPIC)) // report db query response event
                    {
                        vertx.eventBus().publish(EVENT_DATASTORE_QUERY_RESPONSE, buffer.getBytes(position, buffer.length()));
                    }

                    else if (topic.contains(DATASTORE_OPERATION_TOPIC)) // report db event topic
                    {
                        var context = CodecUtil.toJSONObject(buffer.getBytes(position, buffer.length()));

                        if (context.containsKey(OPERATION_TYPE))
                            {
                                if (context.getInteger(OPERATION_TYPE) == DBConstants.OperationType.DATA_WRITE.getName().intValue())
                                {
                                    vertx.eventBus().publish(EVENT_DATASTORE_REQUEST + GlobalConstants.DOT_SEPARATOR + context.getInteger(DBConstants.DATASTORE_CATEGORY), context);
                                }
                                else if (context.getInteger(OPERATION_TYPE) == DBConstants.OperationType.DATA_FLUSH.getName().intValue())
                                {
                                    vertx.eventBus().publish(EVENT_DATASTORE_FLUSH, context);
                                }
                                else if (context.getInteger(OPERATION_TYPE) == DBConstants.OperationType.DATASTORE_INIT.getName().intValue())
                                {
                                    vertx.eventBus().send(EVENT_DATASTORE_INIT, context);
                                }
                                else if (context.getInteger(OPERATION_TYPE) == DBConstants.OperationType.INDEX_UPDATE.getName().intValue())
                                {
                                    vertx.eventBus().publish(EVENT_INDEXABLE_COLUMN_UPDATE, context);
                                }
                            }
                            else if (context.containsKey(EVENT_TYPE) && context.getString(EVENT_TYPE).equalsIgnoreCase(EVENT_REGISTRATION))
                            {
                                vertx.eventBus().send(EVENT_REGISTRATION,context);
                            }
                            else if (context.containsKey(EVENT_TYPE) && context.getString(EVENT_TYPE).equalsIgnoreCase(EVENT_REMOTE_PROCESSOR_HEARTBEAT))
                            {
                                if (CommonUtil.isNotNullOrEmpty(context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                        && RemoteEventProcessorConfigStore.getStore().getItemUUIDByType(context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID),context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE)) != null)
                                {
                                    RemoteEventProcessorCacheStore.getStore().updateDuration(RemoteEventProcessorConfigStore.getStore().getItemUUIDByType(context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID),context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE)), context.getLong(GlobalConstants.DURATION));
                                }
                            }
                        }

                    else if (topic.contains(AGENT_TOPIC)) //agent event
                    {
                        vertx.eventBus().publish(EVENT_AGENT, CodecUtil.toJSONObject(cipherUtil.decrypt(buffer.getBytes(position, buffer.length()))));
                    }

                    else if (topic.contains(MOTADATA_MANAGER_TOPIC)) //motadata manager event (for collector/agent start/stop or backup/restore/master upgrade)
                    {
                        vertx.eventBus().send(EVENT_MANAGER_RESPONSE_PROCESSOR, new JsonObject(buffer.getBuffer(position, buffer.length())));
                    }
                    else if (topic.startsWith(FLOW_TOPIC))
                    {
                        if (LicenseUtil.updateUsedFlowQuota(buffer.length()))
                        {
                            vertx.eventBus().send(EVENT_FLOW, new JsonObject(buffer.getBuffer(position, buffer.length())));
                        }
                    }
                    else if (topic.contains(SHUTDOWN_TOPIC))
                    {
                        Bootstrap.stop(true, null);
                    }
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }

        }).exceptionHandler(LOGGER::error);

        subscribe(subscriber, subscriberPort, subscriberType);

        promise.complete();
    }

    private void subscribe(ZMQ.Socket zmqSubscriber, int port, String filter)
    {
        zmqSubscriber.setHWM(MotadataConfigUtil.getEventBacklogSize());

        zmqSubscriber.setRcvHWM(MotadataConfigUtil.getEventBacklogSize());

        zmqSubscriber.bind("tcp://*:" + port);

        LOGGER.info(String.format("%s bind to port %s", filter.toLowerCase(), port));

        new Thread(() ->
        {
            while (hasMoreEvent.get())
            {
                try
                {
                    var bytes = zmqSubscriber.recv();

                    if (bytes != null && bytes.length > 0)
                    {
                        vertx.eventBus().send(EventBusConstants.EVENT_REMOTE, bytes);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }

            LOGGER.warn(String.format("%s disconnected......", filter));

            LOGGER.info(String.format("stopping motadata %s ....", Bootstrap.bootstrapType().toString().toLowerCase()));

            //Bootstrap.stop(true, null);

        }, filter).start();
    }


    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        hasMoreEvent.set(false);

        subscriber.close();

        promise.complete();

    }

}

