package com.mindarray.manager;

import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import com.mindarray.util.PortUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.manager.MotadataAppManager.PATCH_ARTIFACT_FILE;

public class MotadataSwitchOverEngine extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(MotadataSwitchOverEngine.class, GlobalConstants.MOTADATA_APP_MANAGER, "Switch Over Engine");
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        if (MotadataConfigUtil.getRemoteEventFailOverSubscriber() != null && !MotadataConfigUtil.getRemoteEventFailOverSubscriber().isEmpty())
        {
            LOGGER.info(String.format("switch over engine starting with installation mode : %s , ha mode : %s ", MotadataConfigUtil.getInstallationMode(),MotadataConfigUtil.getHAMode()));

            // when secondary becomes primary and if any one stopped service or restart then we need to check for master is up or not.

            if (MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(GlobalConstants.InstallationMode.PRIMARY.name()) && MotadataConfigUtil.getHAMode() != null && MotadataConfigUtil.getHAMode().equalsIgnoreCase(GlobalConstants.HAMode.PASSIVE.name()))
            {
                vertx.setTimer(180000,handler -> verifyMasterUp());
            }
            else
            {
                vertx.setTimer(180000,handler -> verifyMasterDown());
            }

            promise.complete();
        }
        else
        {
            promise.fail("Failed to deploy switch over engine , reason : fail over key is missing ");
        }

    }

    private void verifyMasterDown()
    {
        try
        {
            LOGGER.info(String.format("verifying master is down or not .... with inspection time : %s and flap value : %s ",MotadataConfigUtil.getMasterHealthInspectionTimer(),MotadataConfigUtil.getHAHeartbeatFlapCount()));

            var flap = new AtomicInteger(0);

            var promise = Promise.<Void>promise();

            vertx.setPeriodic(MotadataConfigUtil.getMasterHealthInspectionTimer(),timer ->
            {
                try
                {
                    if (!PortUtil.isConnected(CommonUtil.getRemoteEventPublisher(), MotadataConfigUtil.getEventPublisherPort(),2000))
                    {
                        flap.getAndIncrement();

                        LOGGER.info(String.format("Master is found DOWN , address is : %s ",MotadataConfigUtil.getEventPublisherPort()+ ":" + CommonUtil.getRemoteEventPublisher()));

                        if (flap.get() >= MotadataConfigUtil.getHAHeartbeatFlapCount() && !promise.future().isComplete())
                        {
                            LOGGER.info(String.format("Master is found DOWN  with flap value %s ",flap.get()));

                            vertx.cancelTimer(timer);

                            switchOver();

                            verifyMasterUp();

                            promise.complete();
                        }
                    }
                    else
                    {
                        flap.set(0);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void verifyMasterUp()
    {
        try
        {
            LOGGER.info(String.format("verifying master is up or not ..... with inspection time : %s and flap value : %s ",MotadataConfigUtil.getMasterHealthInspectionTimer(),MotadataConfigUtil.getHAHeartbeatFlapCount()));

            var flap = new AtomicInteger(0);

            var promise = Promise.<Void>promise();

            vertx.setPeriodic(MotadataConfigUtil.getMasterHealthInspectionTimer(),timer ->
            {
                if (PortUtil.isConnected(CommonUtil.getRemoteEventFailOverSubscriber(), MotadataConfigUtil.getEventPublisherPort(),2000))
                {
                    flap.getAndIncrement();

                    LOGGER.trace(String.format("master is UP , address is : %s ",CommonUtil.getRemoteEventFailOverSubscriber() + ":" + MotadataConfigUtil.getEventPublisherPort()));

                    if (flap.get() >= MotadataConfigUtil.getHAHeartbeatFlapCount() && !promise.future().isComplete())
                    {
                        LOGGER.info(String.format("master is UP with flap value %s ",flap.get()));

                        vertx.cancelTimer(timer);

                        switchOver();

                        verifyMasterDown();

                        promise.complete();
                    }
                }
                else
                {
                    flap.set(0);
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void switchOver()
    {
        try
        {
            LOGGER.info(String.format("switch over for %s and installation mode %s ",MotadataConfigUtil.getSystemBootstrapType(),MotadataConfigUtil.getInstallationMode()));

            switch (InstallationMode.valueOf(MotadataConfigUtil.getInstallationMode()))
            {
                case PRIMARY ->
                {
                    if (!MotadataConfigUtil.getVIPCommand().isEmpty())
                    {
                        switchOver(InstallationMode.PRIMARY, InstallationMode.SECONDARY);
                    }
                    else
                    {
                        LOGGER.warn("can not perform switch over , reason : vip.command not found");
                    }
                }
                case SECONDARY ->
                {
                    if (!MotadataConfigUtil.getVIPCommand().isEmpty())
                    {
                        switchOver(InstallationMode.SECONDARY, InstallationMode.PRIMARY);
                    }
                    else
                    {
                        LOGGER.warn("can not perform switch over , reason : vip.command not found");
                    }
                }

                case FAILOVER -> switchOver(InstallationMode.FAILOVER, InstallationMode.FAILOVER);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void switchOver(GlobalConstants.InstallationMode previousMode, GlobalConstants.InstallationMode currentMode)
    {
        try
        {
            if (previousMode.equals(GlobalConstants.InstallationMode.PRIMARY) && currentMode.equals(GlobalConstants.InstallationMode.SECONDARY))
            {
                LOGGER.info("while SECONDARY switching from PRIMARY to SECONDARY , detaching vip from SECONDARY");

                MotadataConfigUtil.assignUnassignedVIP(DETACH_VIP);
            }

            vertx.eventBus().send(EVENT_REMOTE,new JsonObject()
                    .put(SYSTEM_BOOTSTRAP_TYPE, GlobalConstants.BootstrapType.APP)
                    .put(INSTALLATION_MODE, currentMode)
                    .put(EVENT_TYPE,EVENT_SWITCH_OVER)
                    .put(EventBusConstants.EVENT_CONFIG_CHANGE,new JsonObject()
                            .put(SYSTEM_BOOTSTRAP_TYPE,BootstrapType.APP.name())
                            .put(INSTALLATION_MODE, currentMode)
                            .put(EVENT_PUBLISHER_HOST,MotadataConfigUtil.getRemoteEventFailOverSubscriber())
                            .put(EVENT_SUBSCRIBER_HOST,MotadataConfigUtil.getRemoteEventFailOverSubscriber())
                            .put(EVENT_SUBSCRIBER_FAILOVER_HOST,MotadataConfigUtil.getRemoteEventPublisher())));

            vertx.eventBus().send(EVENT_REMOTE,new JsonObject()
                    .put(SYSTEM_BOOTSTRAP_TYPE,BootstrapType.APP)
                    .put(EVENT_TYPE, EVENT_REMOTE_PROCESSOR_RESTART));

            vertx.eventBus().send(EVENT_REMOTE,new JsonObject()
                    .put(SYSTEM_BOOTSTRAP_TYPE,BootstrapType.AGENT)
                    .put(EVENT_TYPE,EVENT_AGENT_RESTART));

            if (MotadataConfigUtil.getInstallationType() == 0)
            {
                vertx.eventBus().send(EVENT_REMOTE,new JsonObject()
                        .put(SYSTEM_BOOTSTRAP_TYPE,BootstrapType.DATASTORE)
                        .put(EVENT_TYPE,EVENT_REMOTE_PROCESSOR_RESTART));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> stopPromise) throws Exception
    {
        stopPromise.complete();
    }
}

