package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.BootstrapMain;
import com.mindarray.GlobalConstants;
import com.mindarray.api.APIConstants;
import com.mindarray.api.LogParserPlugin;
import com.mindarray.store.*;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.LogUtil;
import com.mindarray.util.Logger;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.util.Map;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.LogParserPlugin.LOG_PARSER_PLUGIN_NAME;
import static com.mindarray.db.DBConstants.*;
import static com.mindarray.eventbus.EventBusConstants.EVENT_CONFIG_CHANGE;

public class RemoteEventChangeNotificationHandler extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(RemoteEventChangeNotificationHandler.class, MOTADATA_EVENT_BUS, "Remote Event Change Notification Handler");

    private static final Map<String, AbstractConfigStore> STORES_BY_COLLECTION =
            Map.ofEntries(Map.entry(COLLECTION_DISCOVERY, DiscoveryConfigStore.getStore()),
                    Map.entry(COLLECTION_DEPENDENCY_MAPPER, DependencyMapperConfigStore.getStore()),
                    Map.entry(COLLECTION_APPLICATION_MAPPER, ApplicationMapperConfigStore.getStore()),
                    Map.entry(COLLECTION_METRIC, MetricConfigStore.getStore()),
                    Map.entry(COLLECTION_METRIC_PLUGIN, MetricPluginConfigStore.getStore()),
                    Map.entry(COLLECTION_RUNBOOK_PLUGIN, RunbookPluginConfigStore.getStore()),
                    Map.entry(COLLECTION_SNMP_OID_GROUP, SNMPOIDGroupConfigStore.getStore()),
                    Map.entry(COLLECTION_SCHEDULER, SchedulerConfigStore.getStore()),
                    Map.entry(COLLECTION_SYSTEM_PROCESS, SystemProcessConfigStore.getStore()),
                    Map.entry(COLLECTION_SYSTEM_FILE, SystemFileConfigStore.getStore()),
                    Map.entry(COLLECTION_SYSTEM_SERVICE, SystemServiceConfigStore.getStore()),
                    Map.entry(COLLECTION_TOPOLOGY_PLUGIN, TopologyPluginConfigStore.getStore()),
                    Map.entry(COLLECTION_OBJECT, ObjectConfigStore.getStore()),
                    Map.entry(COLLECTION_BUSINESS_HOUR, BusinessHourConfigStore.getStore()),
                    Map.entry(COLLECTION_CREDENTIAL_PROFILE, CredentialProfileConfigStore.getStore()),
                    Map.entry(COLLECTION_AGENT, AgentConfigStore.getStore()),
                    Map.entry(COLLECTION_REMOTE_EVENT_PROCESSOR, RemoteEventProcessorConfigStore.getStore()),
                    Map.entry(COLLECTION_SNMP_DEVICE_CATALOG, SNMPDeviceCatalogConfigStore.getStore()),
                    Map.entry(COLLECTION_LOG_PARSER, LogParserConfigStore.getStore()),
                    Map.entry(COLLECTION_LOG_PARSER_PLUGIN, LogParserPluginConfigStore.getStore()),
                    Map.entry(COLLECTION_CONFIG_TEMPLATE, ConfigTemplateConfigStore.getStore()),
                    Map.entry(COLLECTION_CONFIGURATION, ConfigurationConfigStore.getStore()),
                    Map.entry(COLLECTION_STORAGE_PROFILE, StorageProfileConfigStore.getStore()),
                    Map.entry(COLLECTION_FLOW_SETTING, FlowSettingsConfigStore.getStore()),
                    Map.entry(COLLECTION_EVENT_SOURCE, EventSourceConfigStore.getStore())
            );

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_CHANGE_NOTIFICATION, message ->
        {
            var event = message.body();

            switch (EventBusConstants.ChangeNotificationType.valueOf(event.getString(EventBusConstants.CHANGE_NOTIFICATION_TYPE)))
            {
                case RUN_DISCOVERY -> vertx.eventBus().send(EventBusConstants.EVENT_DISCOVERY_RUN, event);

                case COMPLETE_DISCOVERY ->
                        vertx.eventBus().send(EventBusConstants.EVENT_DISCOVERY_COMPLETE, event.getLong(GlobalConstants.ID));

                case ABORT_DISCOVERY ->
                        vertx.eventBus().send(EventBusConstants.EVENT_DISCOVERY_ABORT, event.getLong(GlobalConstants.ID));

                case STOP_REDISCOVER_JOB -> vertx.eventBus().send(EventBusConstants.EVENT_REDISCOVER_STOP, event);

                case ABORT_PLUGIN_ENGINE_REQUEST ->
                        vertx.eventBus().send(EventBusConstants.EVENT_PLUGIN_ENGINE_ABORT, event);

                case RUN_TOPOLOGY -> vertx.eventBus().send(EventBusConstants.EVENT_TOPOLOGY_RUN, event);

                case COMPLETE_TOPOLOGY -> vertx.eventBus().send(EventBusConstants.EVENT_TOPOLOGY_COMPLETE, event);

                case STOP_TOPOLOGY -> vertx.eventBus().send(EventBusConstants.EVENT_TOPOLOGY_STOP, event);

                case CONFIG_INIT ->
                {
                    for (var entry : event.getJsonObject(GlobalConstants.RESULT))
                    {
                        var store = STORES_BY_COLLECTION.get(entry.getKey());

                        if (store != null)
                        {
                            store.clear();

                            for (var result : (JsonArray) entry.getValue())
                            {
                                var item = (JsonObject) result;

                                    store.addItem(item.getLong(GlobalConstants.ID), item);
                                }
                                Bootstrap.vertx().eventBus().publish(entry.getKey() + ".init" ,entry.getKey() +" collection is loaded");
                            }
                        }
                    }

                case CONFIG_CHANGE ->
                {
                    var collection = event.getString(APIConstants.ENTITY_COLLECTION);

                    var request = event.getString(APIConstants.REQUEST);

                    if (CommonUtil.isNotNullOrEmpty(collection) && CommonUtil.isNotNullOrEmpty(request) && STORES_BY_COLLECTION.get(collection) != null)
                    {
                        var store = STORES_BY_COLLECTION.get(collection);

                            if (request.equalsIgnoreCase(APIConstants.REQUEST_CREATE) || request.equalsIgnoreCase(APIConstants.REQUEST_UPDATE))
                            {
                                store.addItem(event.getLong(GlobalConstants.ID), event.getJsonObject(GlobalConstants.RESULT));
                            }
                            else if (request.equalsIgnoreCase(APIConstants.REQUEST_DELETE))
                            {
                                store.deleteItem(event.getLong(GlobalConstants.ID));
                            }

                            if(APIConstants.REQUEST_CREATE.equalsIgnoreCase(request) && COLLECTION_LOG_PARSER_PLUGIN.equalsIgnoreCase(collection))
                            {
                                event.mergeIn(event.getJsonObject(RESULT));

                                event.remove(RESULT);

                                var fileName = event.getString(LOG_PARSER_PLUGIN_NAME).replace("-", "").replace(" ", "");

                                LogParserPlugin.createPlugin(event,fileName).onComplete(handler -> {

                                    if(handler.succeeded())
                                    {
                                        Bootstrap.vertx().eventBus().publish(EVENT_CONFIG_CHANGE,event);
                                    }
                                });
                            }
                            else
                            {
                                Bootstrap.vertx().eventBus().publish(EVENT_CONFIG_CHANGE,event);
                            }
                        }
                    }

                case DELETE_REMOTE_POLLER ->
                {
                    //Todo: implement shutdown code...
                }
                case LOGGER_LEVEL_CHANGE ->
                {

                    LOGGER.info(String.format("Changing log-level: %s to %s", LOG_LEVELS.get(CommonUtil.getLogLevel()), LOG_LEVELS.get(event.getInteger(SYSTEM_LOG_LEVEL))));

                    LogUtil.setLogLevel(event.getInteger(SYSTEM_LOG_LEVEL));
                }

                default ->
                {
                }

            }
        });

        promise.complete();

    }
}

