import com.mindarray.ha.HAConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.DateTimeUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.*;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import org.apache.commons.io.FileUtils;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.datastore.DatastoreConstants.BATCH_FILE;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.ha.HAConstants.HA_SYNC_OPERATION;
import static com.mindarray.ha.HAConstants.HA_SYNC_TYPE;

public class EventDatastoreManager extends AbstractVerticle
{
    private final Logger LOGGER;
    private final TreeSet<String> eventFiles = new TreeSet<>();
    private final Map<String, Integer> offsets = new TreeMap<>();
    private final Map<String, String> deployedRouters = new HashMap<>();
    private final Map<String, Long> ticks = new HashMap<>();
    private final String eventType;
    private final String clazz;
    private final int eventRouters;
    private final boolean blocking;
    private String storeDirectory;

    public EventDatastoreManager(String eventType, int eventRouters, String clazz, boolean blocking)
    {
        this.blocking = blocking;

        this.eventType = eventType;

        this.clazz = clazz;

        this.eventRouters = eventRouters >= 0 ? eventRouters : 1;

        this.LOGGER = new Logger(EventDatastoreManager.class, MOTADATA_DATASTORE, String.format("Event Datastore Manager:(%s)", eventType));
    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var futures = new ArrayList<Future>();

        storeDirectory = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.EVENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.replace(eventType);

        for (var eventRouter = 0; eventRouter < this.eventRouters; eventRouter++)
        {
            load(eventRouter);

            var future = Promise.<Void>promise();

            var router = eventType + GlobalConstants.DOT_SEPARATOR + eventRouter;

            futures.add(future.future());

            if (blocking)
            {
                vertx.deployVerticle(clazz, new DeploymentOptions().setConfig(new JsonObject().put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router)).put(EVENT_TYPE, router)).setWorker(true).setWorkerPoolSize(1).setWorkerPoolName("wp." + router), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.eventBus().<String>localConsumer(router + DOT_SEPARATOR + "create", message -> eventFiles.add(message.body()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });

            }

            else
            {
                vertx.deployVerticle(clazz, new DeploymentOptions()
                        .setConfig(new JsonObject()
                                .put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router))
                                .put(EVENT_TYPE, router)), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.eventBus().<String>localConsumer(router + DOT_SEPARATOR + "create", message -> eventFiles.add(message.body()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });
            }
        }

        CompositeFuture.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                vertx.setPeriodic(120 * 1000, handler -> purge(eventType));

                vertx.eventBus().<Void>localConsumer(EVENT_DATASTORE_RETENTION_TRIGGER, message ->
                        runRetention(eventType, DateTimeUtil.currentSeconds() - MotadataConfigUtil.getDatastoreRetentionDays() * 86400L));

                vertx.eventBus().<JsonObject>localConsumer(EVENT_EVENT_DATASTORE_MANGER + "." + eventType, message ->
                {
                    var event = message.body();

                    switch (HAConstants.HASyncOperation.valueOfName(CommonUtil.getByteValue(event.getValue(HA_SYNC_OPERATION))))
                    {
                        case SAVE ->
                        {
                            if (event.containsKey(EVENT_TYPE) && event.getString(EVENT_TYPE).equalsIgnoreCase(EVENT_HA_DATASTORE_SECONDARY_SYNC))
                            {
                                vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + (event.getLong(EVENT_TIMESTAMP) % eventRouters), event);
                            }
                            else
                            {
                                vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + (event.getLong(EVENT_TIMESTAMP) % eventRouters), event.getBinary(EVENT_CONTEXT)); //send event to writer
                            }
                        }

                        case READ ->
                        {
                            try
                            {
                                if (CommonUtil.traceEnabled())
                                {
                                    LOGGER.trace("db metric store write request received");
                                }

                                var bytes = 0L;

                                var futurePromise = Promise.<Void>promise();

                                var requests = new ArrayList<JsonObject>();

                                var maxBufferBytes = message.body().getLong(DatastoreConstants.DATASTORE_WRITER_MAX_BUFFER_BYTES, 1048576L);

                                if (!eventFiles.isEmpty())
                                {
                                    for (var eventFile : eventFiles)
                                    {
                                        var timestamp = CommonUtil.getLong(eventFile.split(GlobalConstants.DASH_SEPARATOR)[0]);

                                        if ((DateTimeUtil.currentSeconds() - timestamp) > 5 && bytes <= maxBufferBytes)
                                        {
                                            var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + eventFile + ".dat");

                                            if (file.exists() && file.length() > 0)
                                            {
                                                var length = CommonUtil.getInteger(file.length());

                                                if (!offsets.containsKey(eventFile))
                                                {
                                                    requests.add(new JsonObject()
                                                            .put(EVENT_TIMESTAMP, timestamp)
                                                            .put(EVENT_TYPE, EVENT_EVENT_DATASTORE_WORKER + DOT_SEPARATOR + eventType + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                            .put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC)
                                                            .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                                            .put(HA_SYNC_OPERATION, HAConstants.HASyncOperation.READ.getName())
                                                            .put(BATCH_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                                    offsets.put(eventFile, length);

                                                    ticks.put(eventFile, System.currentTimeMillis());

                                                    bytes += length;
                                                }
                                                else
                                                {
                                                    var currentOffset = offsets.get(eventFile);

                                                    if (currentOffset < length)
                                                    {
                                                        length = CommonUtil.getInteger(length - currentOffset);

                                                        requests.add(new JsonObject()
                                                                .put(EVENT_TIMESTAMP, timestamp)
                                                                .put(EVENT_TYPE, EVENT_EVENT_DATASTORE_WORKER + DOT_SEPARATOR + eventType + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                                .put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC)
                                                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                                                .put(HA_SYNC_OPERATION, HAConstants.HASyncOperation.READ.getName())
                                                                .put(BATCH_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                                        offsets.put(eventFile, length + currentOffset);

                                                        bytes += length;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }

                                else
                                {
                                    if (message.body().containsKey(EVENT_TYPE) && message.body().getString(EVENT_TYPE).equalsIgnoreCase(EVENT_HA_DATASTORE_SECONDARY_SYNC))
                                    {
                                        vertx.eventBus().send(EVENT_REMOTE, message.body().put(EVENT_COPY_REQUIRED, false)
                                                .put(EVENT_TYPE, EVENT_HA_ACKNOWLEDGEMENT)
                                                .put(HA_SYNC_TYPE, HAConstants.HASyncType.EVENT.getName()));
                                    }
                                }

                                if (!requests.isEmpty())
                                {
                                    var requestFutures = new ArrayList<Future>();

                                    if (CommonUtil.debugEnabled())
                                    {
                                        LOGGER.debug(String.format("db store qualified %s files total bytes %s", requests.size(), bytes));
                                    }

                                    requests.forEach(item ->
                                    {
                                        var future = Promise.<Void>promise();

                                        requestFutures.add(future.future());

                                        Bootstrap.vertx().eventBus().<JsonObject>request(item.getString(EVENT_TYPE), item, handler -> future.complete());
                                    });

                                    CompositeFuture.join(requestFutures).onComplete(handler ->
                                    {
                                        if (CommonUtil.debugEnabled())
                                        {
                                            LOGGER.debug(String.format("db store %s files received response", requests.size()));
                                        }

                                        requests.forEach(item ->
                                        {
                                            if (item.containsKey(EVENT_CONTEXT))
                                            {
                                                if (message.body().containsKey(EVENT_TYPE) && message.body().getString(EVENT_TYPE).equalsIgnoreCase(EVENT_HA_DATASTORE_SECONDARY_SYNC))
                                                {
                                                    vertx.eventBus().send(EVENT_REMOTE, item.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE, MotadataConfigUtil.getInstallationMode()).put(DatastoreConstants.DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.METRIC.getName()).put(EVENT_COPY_REQUIRED, false).put(EVENT_TYPE, EVENT_HA_DATASTORE_SECONDARY_SYNC));

                                                    if (CommonUtil.debugEnabled())
                                                    {
                                                        LOGGER.debug(String.format("db store %s file send to primary app ", item.getString(BATCH_FILE)));
                                                    }
                                                }
                                                else
                                                {
                                                    vertx.eventBus().send(EVENT_PUBLICATION_DATASTORE_WRITE, item.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)).put(EVENT_COPY_REQUIRED, false));

                                                    if (CommonUtil.debugEnabled())
                                                    {
                                                        LOGGER.debug(String.format("db store %s file send to datastore", item.getString(BATCH_FILE)));
                                                    }
                                                }

                                                if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                                                {
                                                    vertx.eventBus().send("test.datastore.event", item);
                                                }
                                            }
                                        });

                                        futurePromise.complete();
                                    });
                                }
                            }
                            catch (Exception exception)
                            {
                                LOGGER.error(exception);
                            }
                        }
                    }
                });

                promise.complete();
            }
            else
            {
                promise.fail(result.cause());
            }
        });
    }

    private void purge(String eventType)
    {
        try
        {
            for (var iterator = eventFiles.iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                var timestamp = CommonUtil.getLong(entry.split(GlobalConstants.DASH_SEPARATOR)[0]);

                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + entry + ".dat");

                if (file.exists() && offsets.containsKey(entry) && offsets.get(entry) == file.length())
                {
                    offsets.remove(entry);

                    ticks.remove(entry);

                    iterator.remove();

                    vertx.eventBus().send(EVENT_EVENT_DATASTORE_WORKER + DOT_SEPARATOR + eventType + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters), new JsonObject().put(HA_SYNC_OPERATION, HAConstants.HASyncOperation.DELETE.getName()).put(FILE_NAME, entry));

                    if (CommonUtil.debugEnabled())
                    {
                        LOGGER.debug(String.format("event db store %s file deleted because file reach point reach EOF", entry));
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void runRetention(String eventType, long seconds)
    {
        try
        {
            for (var iterator = eventFiles.iterator(); iterator.hasNext(); )
            {
                var entry = iterator.next();

                var timestamp = CommonUtil.getLong(entry.split(GlobalConstants.DASH_SEPARATOR)[0]);

                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + entry + ".dat");

                if (file.exists() && timestamp < seconds)
                {
                    offsets.remove(entry);

                    ticks.remove(entry);

                    iterator.remove();

                    vertx.eventBus().send(EVENT_EVENT_DATASTORE_WORKER + DOT_SEPARATOR + eventType + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters), new JsonObject().put(HA_SYNC_OPERATION, HAConstants.HASyncOperation.DELETE.getName()).put(FILE_NAME, entry));

                    if (CommonUtil.debugEnabled())
                    {
                        LOGGER.debug(String.format("event db store %s file deleted because of retention", entry));
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load(int eventRouter)
    {
        try
        {
            var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + eventRouter + PATH_SEPARATOR + "event-files");

            if (file.exists())
            {
                var content = FileUtils.readFileToString(file, StandardCharsets.UTF_8);

                if (content != null && !content.isEmpty())
                {
                    var objects = new JsonArray(content);

                    for (var object : objects)
                    {
                        this.eventFiles.add(CommonUtil.getString(object));
                    }
                }
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            var futures = new ArrayList<Future>();

            for (var deploymentId : deployedRouters.values())
            {
                var future = Promise.<Void>promise();

                futures.add(future.future());

                vertx.undeploy(deploymentId, handler -> future.complete());
            }

            CompositeFuture.join(futures).onComplete(handler -> promise.complete());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            if (!promise.future().isComplete())
            {
                promise.fail(exception);
            }
        }
    }

}

