import com.mindarray.store.FlowSamplingRateConfigStore;
import com.mindarray.store.MetricConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import io.vertx.ext.web.Router;
import io.vertx.ext.web.RoutingContext;
import org.apache.http.HttpStatus;

import static com.mindarray.ErrorMessageConstants.INTERNAL_SERVER_EXCEPTION;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.RESPONSE_CODE;
import static com.mindarray.api.User.USER_NAME;
import static org.apache.http.HttpStatus.SC_INTERNAL_SERVER_ERROR;

public class FlowSamplingRate extends AbstractAPI
{
    private static final Logger LOGGER = new Logger(FlowSamplingRate.class, GlobalConstants.MOTADATA_API, "Flow Sampling Rate API");

    public FlowSamplingRate()
    {
        super("flow-sampling-rates", FlowSamplingRateConfigStore.getStore(), LOGGER);
    }

    @Override
    public void init(Router router)
    {
        try
        {
            router.get("/" + endpoint + "/:id").handler(this::get);

            router.post("/" + endpoint + "/:id").handler(this::save);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    protected void get(RoutingContext routingContext)
    {
        try
        {
            var sourceIP = routingContext.request().getParam(ID);

            if (sourceIP != null)
            {
                var items = this.configStore.getItemByValue(EventBusConstants.EVENT_SOURCE, sourceIP);

                items = items != null ? items.getJsonObject(NMSConstants.OBJECTS) : null;

                var objects = MetricConfigStore.getStore().getNetworkInterfacesBySource(sourceIP);

                if (objects.isEmpty() && items != null)
                {
                    items.getMap().values().forEach(objects::add);
                }

                else if (!objects.isEmpty())
                {
                    for (var index = 0; index < objects.size(); index++)
                    {
                        var object = objects.getJsonObject(index);

                        object.put(NMSConstants.INTERFACE, object.remove(NMSConstants.INTERFACE_INDEX));

                        if (items != null && items.containsKey(object.getString(NMSConstants.INTERFACE)) && items.getJsonObject(object.getString(NMSConstants.INTERFACE)).getLong(NMSConstants.INTERFACE_SAMPLING_RATE) != null)
                        {
                            object.put(NMSConstants.INTERFACE_SAMPLING_RATE, items.getJsonObject(object.getString(NMSConstants.INTERFACE)).getLong(NMSConstants.INTERFACE_SAMPLING_RATE));
                        }
                    }
                }

                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK)
                        .put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                        .put(GlobalConstants.RESULT, objects));
            }

            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                        .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                        .put(GlobalConstants.MESSAGE, ErrorMessageConstants.API_INVALID_INPUT_PARAMETERS));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            this.send(routingContext, new JsonObject().put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                    .put(RESPONSE_CODE, SC_INTERNAL_SERVER_ERROR)
                    .put(GlobalConstants.ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()))
                    .put(GlobalConstants.ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                    .put(GlobalConstants.MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, exception.getMessage())));
        }
    }

    /**
     * save: In case of NO Entry found for the Given Source IP
     * update: If entry is available for Given Source IP
     * <p>
     * UI Sends list of Interface with sampling rate for given Source IP, there is no flag to differentiate between both request.
     *
     * @param routingContext
     */
    private void save(RoutingContext routingContext)
    {
        var sourceIP = routingContext.request().getParam(GlobalConstants.ID);

        if (sourceIP != null)
        {
            var context = routingContext.body().asJsonObject();

            var params = context.getJsonArray(APIConstants.REQUEST_PARAMS);

            var objects = new JsonObject();

            for (var index = 0; index < params.size(); index++)
            {
                var object = params.getJsonObject(index);

                objects.put(object.getString(NMSConstants.INTERFACE), object);
            }

            var item = this.configStore.getItemByValue(EventBusConstants.EVENT_SOURCE, sourceIP);

            if (item != null)
            {
                item.getJsonObject(NMSConstants.OBJECTS).mergeIn(objects);

                routingContext.setBody(Buffer.buffer(new JsonObject().put(NMSConstants.OBJECTS, item.getJsonObject(NMSConstants.OBJECTS)).toString()));

                this.update(routingContext);
            }

            else
            {
                routingContext.setBody(Buffer.buffer(new JsonObject().put(EventBusConstants.EVENT_SOURCE, sourceIP).put(NMSConstants.OBJECTS, objects).toString()));

                this.create(routingContext);
            }
        }

        else
        {
            this.send(routingContext, new JsonObject()
                    .put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                    .put(GlobalConstants.MESSAGE, ErrorMessageConstants.API_INVALID_INPUT_PARAMETERS));
        }
    }

    @Override
    protected void update(RoutingContext routingContext)
    {
        try
        {
            var schema = CommonUtil.getEntitySchema(endpoint);

            if (schema != null)
            {
                this.beforeUpdate(routingContext).compose(parameters ->

                        Future.<JsonObject>future(promise ->
                        {
                            APIUtil.removeDefaultParameters(parameters);

                            var id = this.configStore.getItemByValue(EventBusConstants.EVENT_SOURCE, routingContext.request().getParam(GlobalConstants.ID)).getLong(GlobalConstants.ID);

                            Bootstrap.configDBService().update(schema.getString(APIConstants.ENTITY_COLLECTION),
                                    new JsonObject().put(DBConstants.FIELD_NAME, GlobalConstants.ID).put(VALUE, id),
                                    parameters, routingContext.user().principal().getString(USER_NAME), routingContext.request().remoteAddress().host(),
                                    true, result ->
                                    {
                                        if (result.succeeded() && !result.result().isEmpty())
                                        {
                                            this.configStore.updateItem(id).onComplete(handler -> promise.complete(new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                                    .put(GlobalConstants.MESSAGE, String.format(InfoMessageConstants.ENTITY_UPDATED, schema.getString(APIConstants.ENTITY_NAME))).put(ID, id)));

                                            parameters.put(GlobalConstants.ID, id);

                                            CommonUtil.removeSensitiveFields(parameters, true);
                                        }

                                        else
                                        {
                                            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                                                    .put(GlobalConstants.STATUS, STATUS_FAIL)
                                                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                                                    .put(GlobalConstants.ERROR, result.failed() ? CommonUtil.formatStackTrace(result.cause().getStackTrace()) : UNKNOWN)
                                                    .put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.ENTITY_UPDATE_FAILED, schema.getString(APIConstants.ENTITY_NAME), result.failed() ? result.cause().getMessage() : UNKNOWN)));

                                            promise.fail(result.failed() ? result.cause().getMessage() : UNKNOWN);

                                            parameters.put(GlobalConstants.ID, id);
                                        }
                                    });

                        }).compose(entity -> this.afterUpdate(entity, routingContext))
                );
            }
            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL).put(GlobalConstants.MESSAGE, String.format(ErrorMessageConstants.SCHEMA_FILE_NOT_FOUND, endpoint)));
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }
}

