package com.mindarray.nms;

import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.store.ObjectStatusCacheStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.SESSION_ID;
import static com.mindarray.eventbus.EventBusConstants.publish;
import static com.mindarray.nms.NMSConstants.STATUS_KEY;

public class ObjectStatusChangeEventProcessor extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(ObjectStatusChangeEventProcessor.class, GlobalConstants.MOTADATA_NMS, "Object Status Change Event Processor");

    private static final Map<String, JsonObject> eventsBySessionId = new HashMap<>();

    private static final Map<String, Long> ticksBySessionId = new HashMap<>();

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.UI_NOTIFICATION_OBJECT_STATUS_INIT, message ->
        {
            var event = message.body();

            try
            {
                var sessionId = event.getString(SESSION_ID);

                ticksBySessionId.put(sessionId, System.currentTimeMillis());

                // object status
                eventsBySessionId.put(sessionId, new JsonObject());

                var response = new JsonObject().put("object.status", JsonObject.mapFrom(ObjectStatusCacheStore.getStore().getItems())).put("instance.status", new JsonObject());

                var iterator = ObjectStatusCacheStore.getStore().getInstanceItems().entrySet().iterator();

                while (iterator.hasNext())
                {
                    var entry = iterator.next();

                    var instances = entry.getValue().entrySet().iterator();

                    while (instances.hasNext())
                    {
                        var instanceEntry = instances.next();

                        var objectDetails = instanceEntry.getKey().split(INSTANCE_SEPARATOR);

                        if (objectDetails[0].toLowerCase().contains("vm") || objectDetails[0].toLowerCase().contains("system.process") || objectDetails[0].toLowerCase().contains("access.point") || objectDetails[0].toLowerCase().contains("system.service"))
                        {
                            response.getJsonObject("instance.status").mergeIn(new JsonObject().put(entry.getKey() + SEPARATOR + objectDetails[1], instanceEntry.getValue()));
                        }
                    }
                }

                publish(sessionId, EventBusConstants.UI_NOTIFICATION_OBJECT_STATUS_INIT, response);
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_OBJECT_STATUS_CHANGE, message ->
        {
            var event = message.body();

            LOGGER.trace(event.encode());

            try
            {
                eventsBySessionId.forEach((key, value) ->
                        value.put(event.getString(STATUS_KEY),
                                new JsonObject().put(event.getString(STATUS_KEY), event.getString(STATUS)).put("status.type", event.getString("status.type"))));
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_USER_PING, message ->
        {
            var event = message.body();

            try
            {
                var sessionId = event.getString(SESSION_ID);

                ticksBySessionId.put(sessionId, System.currentTimeMillis());

                eventsBySessionId.computeIfAbsent(sessionId, value -> new JsonObject());

                if (!eventsBySessionId.get(sessionId).isEmpty())
                {
                    var iterator = eventsBySessionId.get(sessionId).iterator();

                    var response = new JsonObject();

                    while (iterator.hasNext())
                    {
                        var status = JsonObject.mapFrom(iterator.next().getValue());

                        var statusType = CommonUtil.getString(status.remove("status.type"));

                        if (statusType != null)
                        {
                            if (response.containsKey(statusType))
                            {
                                response.getJsonObject(statusType).mergeIn(status);
                            }
                            else
                            {
                                response.put(statusType, new JsonObject().mergeIn(status));
                            }
                        }
                    }

                    EventBusConstants.publish(sessionId, EventBusConstants.UI_NOTIFICATION_OBJECT_STATUS_INIT, response);

                    eventsBySessionId.get(sessionId).clear();
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.setPeriodic(TimeUnit.MINUTES.toMillis(MotadataConfigUtil.getUISessionTimeoutMinutes()), handler ->
        {
            var iterator = ticksBySessionId.entrySet().iterator();

            while (iterator.hasNext())
            {
                var entry = iterator.next();

                if (entry.getValue() < System.currentTimeMillis() - TimeUnit.MINUTES.toMillis(5)) // user is inactive for more than 5 minutes
                {
                    LOGGER.debug("removing " + entry.getKey());

                    eventsBySessionId.remove(entry.getKey());

                    iterator.remove();
                }
            }
        });

        promise.complete();
    }
}

