package com.mindarray.store;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.Metric;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.CompositeFuture;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.ApplicationMapper.APPLICATION_MAPPER_NAME;
import static com.mindarray.api.ApplicationMapper.APPLICATION_MAPPER_PORT;

public class ApplicationMapperConfigStore extends AbstractConfigStore
{

    private static final Logger LOGGER = new Logger(ApplicationMapperConfigStore.class, GlobalConstants.MOTADATA_STORE, "Application Mapper Config Store");

    private static final ApplicationMapperConfigStore STORE = new ApplicationMapperConfigStore();

    private final Map<Integer, Long> itemsByPort = new ConcurrentHashMap<>();

    private ApplicationMapperConfigStore()
    {

        super(DBConstants.COLLECTION_APPLICATION_MAPPER, LOGGER, true);
    }

    public static ApplicationMapperConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            Bootstrap.configDBService().getAll(DBConstants.COLLECTION_APPLICATION_MAPPER, result ->
            {
                if (result.succeeded())
                {
                    items.clear();

                    itemsByPort.clear();

                    if (result.result() != null && !result.result().isEmpty())
                    {
                        for (var index = 0; index < result.result().size(); index++)
                        {
                            var item = result.result().getJsonObject(index);

                            items.put(item.getLong(GlobalConstants.ID), item);

                            if (CommonUtil.debugEnabled())
                            {
                                LOGGER.debug(String.format("item added %s into the store", CommonUtil.removeSensitiveFields(item, false).encodePrettily()));
                            }

                            itemsByPort.put(item.getInteger(APPLICATION_MAPPER_PORT), item.getLong(ID));
                        }
                    }

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));

                }
                else
                {
                    LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    @Override
    public Future<Void> addItem(long id)
    {
        return super.addItem(id).onComplete(handler -> update(super.getItem(id), EventBusConstants.ChangeNotificationType.ADD_APPLICATION_MAPPER));
    }

    @Override
    public Future<Void> updateItem(long id)
    {
        var oldItem = super.getItem(id);

        return super.updateItem(id).onComplete(handler ->
        {
            var item = super.getItem(id);

            if (!oldItem.getString(APPLICATION_MAPPER_NAME).equalsIgnoreCase(item.getString(APPLICATION_MAPPER_NAME)) || !oldItem.getInteger(APPLICATION_MAPPER_PORT).equals(item.getInteger(APPLICATION_MAPPER_PORT)))
            {
                update(item, EventBusConstants.ChangeNotificationType.UPDATE_APPLICATION_MAPPER);

                //old name -> {port + ( + application name + )}
                var previousName = oldItem.getInteger(APPLICATION_MAPPER_PORT) + " (" + oldItem.getString(APPLICATION_MAPPER_NAME) + ")";

                // updated name
                var name = item.getInteger(APPLICATION_MAPPER_PORT) + " (" + item.getString(APPLICATION_MAPPER_NAME) + ")";

                if (!previousName.equalsIgnoreCase(name))
                {
                    //if changes in name list down all network service metrics
                    var metrics = MetricConfigStore.getStore().getItemsByValue(Metric.METRIC_PLUGIN, NMSConstants.MetricPlugin.NETWORK_SERVICE.getName());

                    var futures = new ArrayList<Future>();

                    var entities = new JsonArray();

                    for (var index = 0; index < metrics.size(); index++)
                    {
                        var metric = metrics.getJsonObject(index);

                        var metricContext = metric.getJsonObject(Metric.METRIC_CONTEXT);

                        if (metricContext != null && metricContext.getJsonArray(NMSConstants.OBJECTS) != null)
                        {
                            var objects = metricContext.getJsonArray(NMSConstants.OBJECTS);

                            var updated = false;

                            for (var count = 0; count < objects.size(); count++)
                            {
                                var object = objects.getJsonObject(count);

                                if (object.getString(AIOpsObject.OBJECT_NAME).equalsIgnoreCase(previousName)) //if any match of object name with previous name than update that
                                {
                                    updated = true;

                                    object.put(AIOpsObject.OBJECT_NAME, name);

                                    break;
                                }
                            }

                            if (updated)
                            {
                                var metricId = metric.getLong(ID);

                                var promise = Promise.<Long>promise();

                                futures.add(promise.future());

                                Bootstrap.configDBService().update(DBConstants.COLLECTION_METRIC,
                                        new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, metricId),
                                        metric.put(NMSConstants.OBJECTS, objects),
                                        SYSTEM_USER,
                                        SYSTEM_REMOTE_ADDRESS,
                                        true, future ->
                                        {
                                            entities.add(metricId);

                                            promise.complete(metricId);
                                        });
                            }
                        }
                    }

                    CompositeFuture.join(futures).onComplete(future ->
                    {
                        if (future.succeeded() && !entities.isEmpty())
                        {
                            MetricConfigStore.getStore().updateItems(entities);
                        }
                    });
                }
            }
        });
    }

    @Override
    public void deleteItem(long id)
    {
        var item = items.get(id);

        super.deleteItem(id);

        if (item != null)
        {
            itemsByPort.remove(item.getInteger(APPLICATION_MAPPER_PORT));

            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject().put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.DELETE_APPLICATION_MAPPER));
        }
    }

    private void update(JsonObject item, EventBusConstants.ChangeNotificationType notificationType)
    {
        if (item != null)
        {
            itemsByPort.put(item.getInteger(APPLICATION_MAPPER_PORT), item.getLong(ID));

            Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject().put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, notificationType));
        }
    }

    public Long getItemByPort(Integer port)
    {
        return itemsByPort.getOrDefault(port, GlobalConstants.DUMMY_ID);
    }

    public JsonArray getPorts()
    {
        return new JsonArray(new ArrayList(itemsByPort.keySet()));
    }
}

